quests[12043] = { id = 12043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung von Düsenrost", description = "Ihr da, {class}! Diese Untoten südlich von uns belästigen ständig unsere Arbeit. Nun geht schon und räumt sie aus dem Weg.", sourceObjective = "Tötet 12 Buddler der Weiten und 1 Zuchtmeister der Weiten, die sich in den Ausgrabungsorten um Galakronds Ruhestätte herum befinden. Kehrt anschließend zu Narf im Düsenrostposten zurück, sobald die Aufgabe erledigt ist.", progress = "Hä? Wer seid Ihr? Was wollt Ihr?", completion = "Oh! Ja, die Untoten. Hier ist Eure Bezahlung - nun trollt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[12044] = { id = 12044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstocken", description = "Aber hallo! Die Diener der Geißel graben im Süden irgend so ein uraltes Drachending aus. Mir könnte es eigentlich völlig egal sein, aber die holen dabei auch Karrenladungen voll mit Kompositerz aus dem Boden.\n\nGeht und klaut mir ein wenig von dem Erz. Angesichts der vielen Waffen, die von der Horde hergestellt werden, sollte ordentlich was dabei rausspringen.", sourceObjective = "Geht zu den Ausgrabungsorten, die sich um Galakronds Ruhestätte herum befinden, sammelt 8 Ladungen Kompositerz und bringt sie anschließend zu Xink im Düsenrostposten.", progress = "Habt Ihr das Erz dabei? Mein Träger wird bald zurück sein - wir müssen diese Lieferung verschicken, solange der Kampf noch tobt!", completion = "Ha! Das ist ziemlich viel! Wie geht es Eurem Rücken?", sourceObjectiveStatus = "unverified-source-field" }
quests[12045] = { id = 12045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eiskristalle", description = "Ich habe Euch noch nie zuvor gesehen... Seid Ihr neu in der Schlucht? Freut mich, Euch hier zu haben. Ein paar mehr helfende Hände kann ich immer gut gebrauchen.\n\nMachen wir's so: Ihr beschafft mir die Materialien, ich stelle meine Maschine fertig, dann verkaufen wir das Zeugs an diese Befehlshabertypen und alle gehen reich nach Hause.\n\nIch habe die meisten der Hauptkomponenten hier, also brauche ich nur noch ein paar der Materialien für die Waffe selbst. Narf hat gemeint, dass die gezackten Eissplitter dieser Elementare gen Norden die perfekten Schrapnelle für meine Bomben wären. Geht und holt mir ein paar, ok?", sourceObjective = "Sammelt 4 Eissplitterklumpen von den Eiselementaren gen Norden und bringt sie zu Zivlix im Düsenrostposten.", progress = "Habt Ihr die Splitter? Ich bin schon fast fertig mit der Hauptkühlungseinheit.", completion = "Ausgezeichnet! Sie sind sogar schärfer als erwartet. Ich werde sie erst einmal in den Schnee stecken und sie solange dort lassen, bis die Bombe fertig ist.\n\nNa dann sehen wir mal... Was kommt als nächstes dran...", sourceObjectiveStatus = "unverified-source-field" }
quests[12046] = { id = 12046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiches Hüllenmaterial", description = "Meine Schrapnellbomben brauchen neues Hüllenmaterial. All das Zeug hier ist zu hart und die Schrapnelle werden bei der Explosion nicht richtig verstreut.\n\nWas wir brauchen ist richtig dünner Tierbalg. Die Jormungartunnelgräber im Westen würden womöglich geeignete Bälge hergeben... oder vielleicht auch die Kondore, die bei den Drachenknochen nach Essbarem suchen. Geht und bringt mir, was auch immer sich finden lässt.", sourceObjective = "Sammelt 12 dünne Tierbälge von den Jormungartunnelgräbern oder den Drachenknochenkondoren in der Nähe des Düsenrostpostens und bringt sie anschließend zu Zivlix.", progress = "Läuft die Jagd gut? Habt Ihr meine Bälge dabei?", completion = "Gut... gut... die hier sollten genügen. Die Schrapnellbomben sind fast fertig.\n\nHalt... was ist mit meinen Eissplittern passiert? Narf hat mir gesagt, dass die Splitter von diesen Elementaren verzaubert sein sollen, doch sie schmelzen genauso wie die Dinger, die von Narfs grimmiger Visage hängen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12047] = { id = 12047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas, das nicht schmilzt", description = "Nein, nein, nein! Diese Eissplitter funktionieren überhaupt nicht! Sie schmelzen, bevor sie überhaupt irgendwelchen Schaden anrichten. Das war das letzte Mal, dass ich auf Narfs Meinung in Sachen Materialien vertraut habe. Das bedeutet, dass wir irgendwas ganz anderes zur Herstellung des Schrapnells benötigen.\n\nIch hab's! Ich bin genial - Knochensplitter.\n\nHier liegen überall Knochen herum, an denen die Jormungar ziemlich gründlich herumgenagt haben. Seht einmal nach, ob Ihr mir nicht einen zersplitterten Knochen finden könnt, den ich gebrauchen kann.", sourceObjective = "Sucht inmitten der Drachenknochen östlich des Düsenrostpostens nach 12 zersplitterten Knochenstücken.", progress = "Konntet Ihr irgendwelche Splitter finden?", completion = "Ausgezeichnet! Mehr brauche ich nicht, um die neuen Bomben austesten zu können. Einen Moment, ich werde das hier mal austesten!", sourceObjectiveStatus = "unverified-source-field" }
quests[12048] = { id = 12048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen der Geißel", description = "Aus diesem verdammten Erz lässt sich nichts gewinnen. Es will einfach nicht zusammenhalten! Ich habe alles versucht, doch das Metall der Geißel lässt sich nicht verbiegen!\n\nWenn ich vielleicht ein paar Proben von den Waffen der Geißel hätte, wäre ich vielleicht dazu in der Lage, den Schmiedeprozess zurückzuverfolgen und sie gleichzeitig auseinanderzunehmen.\n\nEisnebel wimmelt nur so von gepanzerten Nerubern der Geißel. Geht dorthin und beschafft mir ein paar ihrer Waffen! Mit Eurer Hilfe könnte ich vielleicht sogar etwas aus diesem Erz machen.\n\nEisnebel liegt im Westen.", sourceObjective = "Borus Eisenbieger in Agmars Hammer in der Drachenöde möchte, dass Ihr ihm 8 Waffen der Geißel bringt.", progress = "<Borus pfeffert seine Werkzeuge auf den Boden.>\n\nDie sind nutzlos!", completion = "Diese hier befinden sich in einem ausgezeichneten Zustand, {name}. Ich werde mich sofort an die Arbeit machen. Wenn daraus irgendwas werden soll, dann werdet Ihr es als Erster erfahren!", sourceObjectiveStatus = "unverified-source-field" }
quests[12049] = { id = 12049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwer zu schlucken", description = "Die Truppen werden sich sicherlich die Bäuche vollstopfen wollen.\n\nIch werde Euch in ein kleines Geheimnis einweihen, das <ein zart Besaiteter/eine zart Besaitete> {race} wie Ihr niemals wissen könnte... diese Jormungarwürmer schmecken nämlich wie Hühnchen.\n\nGeht nach Osten und fordert einen dieser riesigen, bulligen Jormungar heraus. Es ist eher unwahrscheinlich, dass Ihr dazu in der Lage sein werdet, einen von ihnen so mir nichts, dir nichts zu töten - wartet also, bis er sein Maul weit aufsperrt und werft das hier seinen Rachen hinunter. Bringt mir so viele Fleischstücke, wie Ihr nur schleppen könnt.", sourceObjective = "Kämpft so lange gegen einen bulligen Jormungar östlich des Düsenrostpostens, bis er sein Maul öffnet, um dann eine potente Sprengladung hineinzuwerfen. Sammelt, nachdem er explodiert ist, 6 Stücke verbranntes Jormungarfleisch vom Boden auf und bringt sie zu Xink.", progress = "Habt Ihr alles bekommen? Ihr stinkt zweifellos danach.", completion = "Ha, ha! Eins der Fleischstücke ist genau hier drüben gelandet! Saubere Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[12050] = { id = 12050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holz hacken", description = "Als nächstes müssen wir etwas Holz für all die im Bau befindlichen Türme der Allianz beschaffen. Im Süden gibt es einige dünne Bäume, doch die Bäume im Norden, auf denen die Harpyien nisten, sehen so aus, als wären sie ein viel besseres Baumaterial für Gebäude.\n\nNehmt die Steuerung hier. Benutzt sie, wenn Ihr im Nistgebiet der Harpyien seid, und einer meiner Schredder wird zu Euch kommen. Sammelt so viel Holz, wie er nur tragen kann. Die Harpyien werden sicherlich damit nicht einverstanden sein, dass Ihr deren Zuhause fällt - kümmert Euch also um sie, falls nötig.\n\nLos, ran ans Holz!", sourceObjective = "Ruft mithilfe von Xinks Schreddersteuerung einen Schredder, sobald Ihr das Nistgebiet der Harpyien im Norden erreicht habt. Sammelt 50 Bündel Nutzholz von den Bäumen in der Gegend und kehrt anschließend zu Xink im Düsenrostposten zurück.\n\nWendet Euch an Xink im Düsenrostposten, falls Ihr Xinks Schreddersteuerung verlieren solltet, um eine neue zu erhalten.", progress = "Wo ist die Lastenmaschine? Hoffe, die Jormungar haben sie nicht erwischt. Sie hatte diesmal eine ziemlich große Ladung dabei.", completion = "Wenn ein Baum im Wald umfällt und Ihr wegen der Sägerei nichts hören könnt, macht er dann ein Geräusch?", sourceObjectiveStatus = "unverified-source-field" }
quests[12051] = { id = 12051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein paar Federn rascheln lassen", description = "Diese Harpyien haben unsere Profite schon lange genug beeinträchtigt! Tötet sie alle.", sourceObjective = "Narf im Düsenrostposten möchte, dass Ihr 20 Harpyien nordwestlich des Düsenrostpostens tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[12052] = { id = 12052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nimm das, Harpyie!", description = "{class}, habt Ihr das gesehen? Das ist die Harpyie, die den Überfall auf unsere Lieferungen zur Pforte angeführt hat! Ich hab' sie schon einmal gesehen: im hinteren Teil der Kaltwindanhöhen.\n\nDiese Harpyien haben unsere Profite schon lange genug beeinträchtigt! Tötet sie alle.", sourceObjective = "Tötet die Meisterin des Kaltwinds und 15 Kaltwindharpyien in den Bergen nordwestlich des Düsenrostpostens. Kehrt zu Narf zurück, sobald die Aufgabe erledigt ist.\n\nSprecht mit Xink im Düsenrostposten, falls Ihr seine Schreddersteuerung benötigen solltet.", progress = "Ich erinnere mich an Euch. Ihr seid nicht tot - doch diese Harpyienweiber werden es wohl besser sein.", completion = "Das sollte diese Scheusale eines Besseren belehren. Hier... nehmt Eure Belohnung und macht, dass Ihr davonkommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12053] = { id = 12053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Horde", description = "Die Taunka sind zu unseren Waffenbrüdern geworden - wir müssen ein Zeichen der Solidarität setzen und Eisnebel zurückerobern.\n\nDas Dorf befindet sich am Fuße der Berge westlich von Agmars Hammer. Macht Euch auf den Weg dorthin und fordert die Neruber der Anub'ar zum Kampfe heraus! Rammt unser geliebtes Banner der Horde in den Boden, sobald Ihr dort angelangt seid, und vernichtet all diejenigen, die es wieder niederreißen möchten!\n\nDie Anub'ar sollen die wahre Macht der Horde spüren! Möge unsere Schlachtstandarte das Letzte sein, das sie vor dem Tode sehen werden!", sourceObjective = "Schlachtrufer Juktok in Agmars Hammer in der Drachenöde möchte, dass Ihr die Schlachtstandarte des Kriegshymnenklans in Eisnebel aufstellt und sie gegen alle Angreifer verteidigt.\n\nBringt die Schlachtstandarte des Kriegshymnenklans wieder zurück, wenn Ihr die Aufgabe abgeschlossen habt.", progress = "Es ist nicht einfach, {name}!", completion = "Wir haben den Sieg zu Land errungen! Und bald werden wir ihn auch in der Luft erringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12054] = { id = 12054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Tagebuch entschlüsseln", description = "Vor'takh hat Recht... Wir können uns diese Gelegenheit nicht durch die Lappen gehen lassen.\n\nZum Glück weiß ich, wie wir das Tagebuch dieses Branns übersetzen könnten.\n\nDie Schamanen der Rotfangfurbolgs, die sich am Schrein des Herzensblutes südlich des Lagers versammeln, pflanzen ein Kraut mit Namen 'Geisteratem' an. Ein erfahrener Mystiker kann daraus einen Weihrauch herstellen, mit dessen Hilfe er sich die Weisheit der Geister der Vorfahren zu Nutze machen kann.\n\nDie Gärten der Schamanen sind ein wohl gehütetes Geheimnis; doch sucht den Schamanen namens Grumbald Einauge auf - er sollte das Kraut bei sich tragen, da er es für seine Opfergaben an Ursoc benötigt.", sourceObjective = "Bringt der Weisen Paluna in Camp Oneqwah einen Geisteratemzweig.", progress = "Habt Ihr genug von dem Kraut mitgebracht?", completion = "Gut gemacht, {name}. Ich werde das Rauchwerk vorbereiten und dann werden wir sehen, was genau dieser königliche Zwerg so weit von zu Hause gemacht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[12055] = { id = 12055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein seltsames Gerät", description = "Ihr seid Euch sicher, als Ihr das seltsame Gerät aufhebt, dass es von magischer Natur ist. Leider scheint es keinen erkennbaren Nutzen aufzuweisen.\n\nWomöglich weiß die Erzmagierin in Sternenruh östlich der Mondruhgärten mehr darüber.", sourceObjective = "Bringt Goramoshs seltsames Gerät zum Abbild der Erzmagierin Modera in Sternenruh.", progress = "Was habt Ihr denn da?", completion = "{name}, wenn ich mich nicht täusche, habt Ihr den Schlüssel entdeckt, mit dessen Hilfe wir die Absichten der Magierjäger genau erkennen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[12056] = { id = 12056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Tode verurteilt: Hochkultist Zangus", description = "Ich habe mit eigenen Augen beobachten können, wie er uns verriet! Der Verräter hat einen Angriff der Anub'ar auf diese Festung geleitet, bei dem einige meiner besten Soldaten ums Leben kamen.\n\n<Gort schüttelt den Kopf.>\n\nEr hat die ganze Zeit über gemeinsame Sache mit der Geißel gemacht und wir haben davon nichts gewusst! Wie viele Verräter wie Zangus gibt es denn? Wir werden sie alle finden und wenn wir sie haben...\n\n<Gort macht mit seinem Finger eine Bewegung, als durchschneide er seine Kehle.>\n\nErster auf der Liste ist Zangus. Unsere Späher berichten mir, dass er sich in der Grube von Narjun gen Westen verstecken soll. Findet ihn, tötet ihn und bringt mir seinen Kopf.", sourceObjective = "Tötet Hochkultist Zangus und bringt den Kopf des Hochkultisten Zangus zu Hauptmann Gort in Agmars Hammer in der Drachenöde.", progress = "Ist da der abgetrennte Kopf eines Orcs in Eurem Rucksack oder seid Ihr bloß froh, mich zu sehen?", completion = "<Gort hält den Kopf hoch und starrt in seine toten Augen.>\n\nIch hab' dir gesagt, dass wir dich erwischen würden...\n\nHier ist Eure Belohnung, {class}. Damit hätten wir eine Sorge weniger, die uns Kopfschmerzen bereitet hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[12057] = { id = 12057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der fleischgebundene Foliant", description = "Der Foliant ist in Fleisch eingebunden und es scheint, als würde er bluten. Nach näherer Betrachtung entdeckt Ihr unzählige Seiten, die über und über mit seltsamen blutigen Symbolen beschriftet sind.\n\nWelches Wissen auch immer in diesem Folianten enthalten sein mag, es könnte von Bedeutung sein. Bringt ihn zurück zu Hauptmann Gort in Agmars Hammer östlich von Eisnebel.", sourceObjective = "Bringt Hauptmann Gort in Agmars Hammer den fleischgebundenen Folianten.", progress = "<Gort hebt eine Braue.>", completion = "<Gort nimmt den Folianten an sich.>\n\nBarbaren... In Orcfleisch eingebunden... Diese Sprache... Dass sie wirklich existiert, wurde jedoch niemals bestätigt. Es ist die Sprache des Todes... die Zunge der Geißel.", sourceObjectiveStatus = "unverified-source-field" }
quests[12058] = { id = 12058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prophezeiungen der Runen", description = "Branns Tagebuch enthält auch eine Legende für die Symbole der Eisenzwerge. Ich habe sie auf einen Schlüsselstein übertragen, der Euch beim Verstehen der Inschrift auf den Runenplatten helfen wird.\n\nLaut seinen Tagebucheinträgen scheint es, als suche Brann Hinweise auf die Herkunft seines Volks. Haltet Eure Augen nach jedem Hinweis auf seinen Aufenthaltsort offen.\n\nKehrt nach Thor Modan zurück, nordöstlich von hier, stellt Euch vor jede der Platten und verwendet den Stein, um ihren Inhalt zu bestimmen. Die Allianz darf ihn nicht vor uns finden.", sourceObjective = "Die Weise Paluna im Camp Oneqwah möchte, dass Ihr die drei Runenplatten entziffert.", progress = "Habt Ihr Thor Modans Geheimnisse enthüllt?", completion = "<Die Weise Paluna hört Euch zu, als Ihr die Übersetzung der Platten wiederholt.>\n\nAlso glaubt Brann, eine neue Titanenstadt entdeckt zu haben?\n\n\"Die Wiege von Stein und Eisen.\"\n\n\"Ulduar schmiegt sich in den Sturm.\"\n\nIch werde den Häuptling bitten, Fernläufer zu den Sturmgipfeln zu entsenden. Mein Volk kennt diese Lande gut und sollte in der Lage sein, diesen eigensinnigen Zwerg aufzuspüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[12059] = { id = 12059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein seltsames Gerät", description = "Ihr seid Euch sicher, als Ihr das seltsame Gerät aufhebt, dass es von magischer Natur ist. Leider scheint es keinen erkennbaren Nutzen aufzuweisen.\n\nWomöglich weiß der Erzmagier in Agmars Hammer nordöstlich der Mondruhgärten mehr darüber.", sourceObjective = "Bringt Goramoshs seltsames Gerät zum Abbild des Erzmagiers Aethas Sonnenhäscher.", progress = "Was habt Ihr denn da?", completion = "{name}, wenn ich mich nicht täusche, habt Ihr den Schlüssel entdeckt, mit dessen Hilfe wir die Absichten der Magierjäger genau erkennen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[12060] = { id = 12060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Projektionen und Pläne", description = "Das hier ist ein Teleportationsgerät. Müsste ich raten, würde ich meinen, dass es einen zur Sognadelplattform über den Mondruhgärten gen Westen teleportiert.\n\nIch möchte, dass Ihr es benutzt, um herauszufinden, was sich dort oben befindet. Es scheint, als könne man sich mit dem Gerät auch wieder zurückbefördern, also müsstet Ihr nicht herunterspringen.\n\nMeinen Erwartungen nach wird sich ganz oben auf der Sognadel eine Art Apparat befinden, den es zu untersuchen gilt.\n\nIhr solltet den Teleporter benutzen können, solange Ihr Euch in den Gärten aufhaltet.", sourceObjective = "Geht zur Projektion auf der Sognadel über den Mondruhgärten, um sie zu untersuchen.\n\nKehrt anschließend mit den Informationen zum Abbild der Erzmagierin Modera in Sternenruh zurück.", completion = "Was Ihr beschreibt... hört sich wie eine Projektion des Arkanomikons an!\n\n<Kurz kommt die Sorge der Erzmagierin zum Vorschein, doch dann gewinnt ihre unerschütterliche Fassung wieder die Oberhand.>\n\nDas Arkanomikon ist eine Karte all der Stellen auf der Welt, an denen sich die magischen Leylinien überkreuzen. Mit seiner Hilfe hat der blaue Drachenschwarm die 'Anker' der Leylinien entdeckt und zerstört, um die magische Energie wieder zurück zum Nexus zu leiten.\n\nNun stellt sich die Frage, weshalb sich der Zerstörungspfad nach Osten zieht, wenn er sich doch nach Westen ziehen sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[12061] = { id = 12061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Projektionen und Pläne", description = "Das hier ist ein Teleportationsgerät. Müsste ich raten, würde ich meinen, dass es einen zur Sognadelplattform über den Mondruhgärten gen Südwesten teleportiert.\n\n{name}, ich möchte, dass Ihr mit seiner Hilfe herausfindet, was sich dort oben befindet. Es scheint, als könne man sich mit dem Gerät auch wieder zurückbefördern, also müsstet Ihr nicht herunterspringen.\n\nMeinen Erwartungen nach wird sich ganz oben auf der Sognadel eine Art Apparat befinden, den es zu untersuchen gilt.\n\nIhr solltet den Teleporter benutzen können, solange Ihr Euch in den Gärten aufhaltet.", sourceObjective = "Geht zur Projektion auf der Sognadel über den Mondruhgärten, um sie zu untersuchen.\n\nKehrt anschließend mit den Informationen zum Abbild des Erzmagiers Aethas Sonnenhäscher in Agmars Hammer zurück.", completion = "Was Ihr beschreibt... hört sich wie eine Projektion des Arkanomikons an!\n\n<Nur kurz kommt die Sorge des Erzmagiers zum Vorschein, bis seine unerschütterliche Fassung wieder die Oberhand gewinnt.>\n\nDas Arkanomikon ist eine Karte all der Stellen auf der Welt, an denen sich die magischen Leylinien überkreuzen. Mit seiner Hilfe hat der blaue Drachenschwarm die 'Anker' der Leylinien entdeckt und zerstört, um die magische Energie wieder zurück zum Nexus zu leiten.\n\nNun stellt sich die Frage, weshalb sich der Zerstörungspfad nach Osten zieht, wenn er sich doch nach Westen ziehen sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[12062] = { id = 12062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beleidigt Coren Düsterbräu", description = "Coren Düsterbräu ist im nächsten Raum und gerade dabei, Dunkeleisenzwerge zu einem weiteren Angriff auf das Braufest aufzustacheln. Macht ihn nieder!\n\nGeht zu ihm hin und provoziert einen Streit. Sagt ihm, dass nicht einmal Säue sein Bier saufen würden.\n\nMacht Euch auf einen Kampf gefasst, wenn Ihr das sagt - das letzte Mal, als jemand über sein Gebräu herzog... warf man ihn Schreckensebern zum Fraß vor.", sourceObjective = "Geht und fangt Streit mit Coren Düsterbräu an.", completion = "Was? Was sagst du da? Du wagst es! Mein Bier kann sich mit dem Spülwasser, das sie auf dem Braufest ausschenken, allemal messen!\n\nDafür wirst du bezahlen, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[12063] = { id = 12063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisnebels Stärke", description = "<Großmutter Eisnebel verbeugt sich.>\n\nEs ist mir eine Ehre, Euch kennenzulernen, <mein Held/meine Heldin>. Es ist Euch zu verdanken, dass viele von uns heute hier versammelt und am Leben sind, bereit, gegen die Geißel in die Schlacht zu ziehen.\n\nIhr habt so viel für uns getan, dass es mich in Verlegenheit bringt, Euch ein weiteres Mal um Unterstützung zu bitten. Es geht um meinen einzigen Sohn Banthok. Ich sprach mich zwar des Öfteren dagegen aus, doch er verließ diesen Ort, um sich auf die Suche nach seinem Vater, Oberhäuptling Eisnebel, zu begeben. Als er das letzte Mal gesehen wurde, zog er in Richtung Westen nach Eisnebel. Ich bitte Euch: Findet Banthok. Ich wüsste weder ein noch aus, würde ich meinen Sohn verlieren.", sourceObjective = "Sucht in Eisnebel nach Banthok Eisnebel.", completion = "Mein Vater ist noch immer am Leben! Wir müssen ihn retten! Ich schaffe es nicht alleine, {race}. Ihr müsst mir helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12064] = { id = 12064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ketten der Anub'ar", description = "Sie haben meinen Vater mit magischen Ketten gefesselt und halten ihn in der Mitte von Eisnebel fest. Alles, was ich in Erfahrung bringen konnte, ist, dass drei mächtige Magier der Anub'ar dafür sorgen, dass er gefangen gehalten wird, und dass ein jeder einen Teil des Schlüssels in Händen hält.\n\nDurchsucht Eisnebel nach diesen Magiern, tötet sie und nehmt ihnen die Schlüsselfragmente ab. Sobald wir erst einmal alle drei Teile haben, werden wir meinen Vater befreien können. Und sobald er frei ist...\n\nVergeltung wird sie ereilen, ehe sie sich versehen.", sourceObjective = "Banthok Eisnebel in Eisnebel in der Drachenöde möchte, dass Ihr ihm Anok'ras Schlüsselfragment, Tivax' Schlüsselfragment und Sinoks Schlüsselfragment beschafft.", progress = "Bringt mir diese Schlüsselfragmente!", completion = "Ja, das wird funktionieren.\n\n<Banthok fügt die Schlüsselfragmente mit äußerster Geschicklichkeit zusammen.>\n\nSo, fertig. Mit diesem Schlüssel werden wir meinen Vater aus den Klauen der Anub'ar befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[12065] = { id = 12065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fokus am Strand", description = "Die Streitkräfte der Magierjäger operieren am Glimmerstrand südlich der Mondruhgärten. Ich vermute, Ihr werdet dort einen schwer bewachten Fokus samt zuständigem Hauptmann vorfinden.\n\nEs besteht kein Zweifel, dass der Hauptmann der Truppe so etwas wie eine Steuerung für das Gerät bei sich trägt. Beschafft Euch diese Steuerung und wendet sie auf den Fokus an.\n\nMit etwas Glück, können wir ein wenig mehr darüber erfahren, was sie dort draußen wirklich vorhaben.", sourceObjective = "Beschafft Euch den Steuerungsring des Leylinienfokus und verwendet ihn, um Informationen vom Leylinienfokus am Glimmerstrand zu erhalten.\n\nKehrt anschließend zum Abbild der Erzmagierin Modera in Sternenruh zurück.", completion = "Wie merkwürdig, dass Euch diese Informationen auf magische Art und Weise übertragen wurden.\n\nWir wissen jetzt nicht nur, dass sie den Energiefluss des Mondruhgartens umgeleitet haben, sondern auch, dass sie diese Energie absichtlich irgendwie manipulieren. Was haben sie bloß mit all dieser Magie vor?\n\nMir gefällt das alles nicht, {name}, ganz und gar nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[12066] = { id = 12066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fokus am Strand", description = "Die Streitkräfte der Magierjäger operieren am Glimmerstrand südlich der Mondruhgärten. Ich vermute, Ihr werdet dort einen schwer bewachten Fokus samt zuständigem Kapitän vorfinden.\n\nEs besteht kein Zweifel, dass der Hauptmann der Truppe so etwas wie eine Steuerung für das Gerät bei sich trägt. Beschafft Euch diese Steuerung und wendet sie auf den Fokus an.\n\nWenn Ihr es geschickt anstellt, können wir etwas mehr darüber erfahren, was sie dort draußen wirklich vorhaben.", sourceObjective = "Beschafft Euch den Steuerungsring des Leylinienfokus und verwendet ihn, um Informationen vom Leylinienfokus am Glimmerstrand zu erhalten.\n\nKehrt anschließend zum Abbild des Erzmagiers Aethas Sonnenhäscher bei Agmars Hammer zurück.", completion = "Wie merkwürdig, dass Euch diese Informationen auf magische Art und Weise übertragen wurden.\n\nWir wissen jetzt nicht nur, dass sie den Energiefluss des Mondruhgartens umgeleitet haben, sondern auch, dass sie diese Energie absichtlich irgendwie manipulieren. Was haben sie bloß mit all dieser Magie vor?\n\nMir gefällt das alles überhaupt nicht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12067] = { id = 12067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Brief an Zuhause", description = "Im Innenfutter ihrer Robe findet Ihr einen Brief, auf dem folgendes geschrieben steht:\n\n\"Vater,\n\nes tut mir leid, dass ich mich nicht gemeldet und du nicht gewusst hast, wo ich bin. Wenn du diesen Brief liest, dann bin ich schon tot.\n\nIch wurde dazu gezwungen, für Malygos' Armeen zu arbeiten, da sie mir gedroht haben, unsere Familie umzubringen, wenn ich mich weigern würde. Ich schäme mich so sehr dafür.\n\nIch bitte dich alles zu tun, was in deiner Macht steht, um sie zu bekämpfen. Und mach dir keine Sorgen um mich. Ich halte sie zum Narren und sabotiere sie nun von innen heraus.\n\nIch liebe dich, Papa!\n\nEm\"\n\nKommandantin Saia Azurstahl wird das hier sicherlich sehen wollen!", sourceObjective = "Liefert Hauptmann Malins Brief bei Kommandantin Saia Azurstahl in Sternenruh ab.", progress = "Ein Brief für mich?\n\n<Die Kommandantin liest einen Moment lang in Eurem Gesicht.>\n\nIch denke nicht... - müssen schlechte Nachrichten sein.", completion = "Oh nein... und wir haben Euch dorthin geschickt, um sie zu töten, stimmt's?\n\n<Die Kommandantin schüttelt den Kopf und seufzt.>\n\nEs tut mir leid. Ich werde mich darum kümmern, dass der Brief umgehend an ihren Vater Erzmagier Malin in Sturmwind geschickt wird. Macht Euch keine Sorgen; man wird Euch mit der Sache nicht in Verbindung bringen... Es war nicht Eure Schuld.\n\nVersucht es zu vergessen. Ihr hättet es auf keinen Fall wissen können, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12068] = { id = 12068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stimmen aus dem Staub", description = "<Drakuru platziert das Auge des Propheten über seiner Augenbraue und das Herz der Uralten auf seine Brust.>\n\nWir sind nah' dran, Mann, sehr nahe!\n\nWir müssen nur noch die Tafeln der Drakkari finden. Niemand weiß, wie alt sie sind oder was auf ihnen geschrieben steht, doch mithilfe des Auges und des Herzens kann Drakuru sie lesen. Sie befinden sich tief in der Krypta in Drakil'jin, östlich von hier.\n\nBesorg' dir heiliges Mojo von den Orakeln und Beschützern, nachdem du die Tafeln gefunden hast, und beschwör' mich. Sie sollten stolz sein, dafür sterben zu dürfen.", sourceObjective = "Drakuru möchte, dass Ihr in die Ruinen von Drakil'jin geht, dort die Tafeln der Drakkari sammelt und 5 Einheiten heiliges Mojo von den Orakeln und Beschützern der Drakkari sammelt. Geht danach zu Drakurus Kohlenbecken in den Ruinen, benutzt Drakurus Elixier und ruft sein Abbild herbei.", progress = "Gut, dich zu sehen, {name}.\n\nHaste die Tafeln gefunden?", completion = "Wir haben es vollbracht, {name}!\n\nWir haben alle Komponenten, die wir brauchen, um das Läuterungsritual durchzuführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12069] = { id = 12069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Oberhäuptlings", description = "<Banthok überreicht Euch den Gefängnisschlüssel.>\n\nIhr müsst Euch beeilen, {name}. Nehmt den Schlüssel und befreit meinen Vater aus dem Gefängnis der Anub'ar. Helft ihm anschließend dabei, ihren Anführer Unterkönig Anub'et'kan zu töten. Reißt dann ein Stück seines Chitinpanzers heraus und präsentiert es der Horde in Agmars Hammer als Trophäe. Agmar soll die Macht des Oberhäuptlings mit eigenen Augen sehen!", sourceObjective = "Befreit Oberanführer Eisnebel mit dem Gefängnisschlüssel von Anub'ar und helft ihm dabei, Unterkönig Anub'et'kan zu besiegen.\n\nNehmt Euch ein Bruchstück aus Anub'et'kans Panzer und bringt es zurück zu Oberanführer Agmar in Agmars Hammer in der Drachenöde.", progress = "Worum geht's, {name}? Ich bin äußerst beschäftigt.", completion = "Ihr seid ein mutiger {class}, {name}. Ihr habt den Oberanführer befreit und der Horde damit einen großen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12070] = { id = 12070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Kraft für die Truppen", description = "Die Söhne des Eisens haben ihre Runen benutzt, um viele meiner Brüder zu fesseln und benutzen sie dazu, die Belagerung von Thor Modan zu beenden. Ich wünschte, wir müssten sie nicht bekämpfen, aber wir haben keine andere Wahl.\n\nMeine Riesen werden ihnen nicht lange standhalten können.\n\nIch habe diesen irdenen Splitter mit einem Segen versehen, der unseren Verbündeten helfen wird. Nehmt ihn mit Euch in die Schlacht in den Felshügeln im Norden und benutzt ihn, um meinen Brüdern Vertrauen und Stärke einzuflößen. \n\nTötet alle Eisenzwerge, die sich Euch in den Weg stellen.", sourceObjective = "Benutzt den Splitter der Erde, um den Grizzlyhügelriesen, die in den Felshügeln kämpfen, neue Kraft einzuflößen. Tötet alle Eisenzwerge, die sich Euch widersetzen, und erstattet dann Kurun auf dem Hügel, der Thor Modan überblickt, Bericht.", progress = "Habt Ihr meinen Segen den Riesen meinen Segen übermittelt?", completion = "Ihr habt unseren Verbündeten die Kraft gegeben, weiterzukämpfen, und dafür danke ich Euch. Trotzdem müssen wir einen Weg finden, diese Schlacht zu beenden, bevor wir überrannt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12071] = { id = 12071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff aus der Luft!", description = "Sie haben gesehen, über welche Macht die Horde auf Land verfügt, nun müssen sie unsere Kraft aus der Luft zu spüren bekommen! Ich möchte, dass Ihr Euch umgehend bei Valnok Windzürner meldet! Er befindet sich hier, in Agmars Hammer.\n\nValnok wurde schon über die Einzelheiten Eurer Mission unterrichtet und erwartet Euch.", sourceObjective = "Sprecht mit Valnok Windzürner in Agmars Hammer.", completion = "<Valnok salutiert Euch.>\n\nIhr seid also das Ass, oder was?", sourceObjectiveStatus = "unverified-source-field" }
quests[12072] = { id = 12072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdammt sollen die Seuchenbestien sein!", description = "Ihr habt zweifellos die Armee der Seuchenbestien der Anub'ar gesehen, die in Eisnebel erschaffen wird. Die Anub'ar wollen diese Monster auf unsere Soldaten an der Pforte des Zorns hetzen - doch das darf nicht passieren!\n\nNehmt diese Leuchtpistole, geht nach Eisnebel im Westen und feuert sie ab, um einen meiner Kriegsreiter zu rufen. Sitzt auf und vernichtet mit seiner Hilfe die Seuchenbestien, die man vom Boden aus nicht erreichen kann!\n\nKehrt zu mir zurück, sobald Ihr ihre Luftstreitkräfte dezimiert habt, und holt Eure Belohnung ab!", sourceObjective = "Geht nach Eisnebel, benutzt Valnoks Leuchtpistole, um einen Kriegsreiter der Kor'kron zu rufen, setzt auf und tötet mit seiner Hilfe 25 Seuchenbestien der Anub'ar!\n\nKehrt anschließend wieder zu Valnok Windzürner in Agmars Hammer zurück, sobald Ihr diese Mission erfüllt habt.", completion = "<Valnuk salutiert.>\n\nUnd aus der Luft kam ihre Vernichtung! Vielleicht werdet Ihr schon bald nach Angrathar beordert, Held!", sourceObjectiveStatus = "unverified-source-field" }
quests[12073] = { id = 12073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Eisen bearbeiten", description = "Die Allianz ist nicht die einzige Macht, die sich uns in den Grizzlyhügeln entgegenstellt. Die Eisenzwerge halten die Ostküste unter ihrer Kontrolle, obwohl Thor Modan im Nordosten von Steinriesen belagert wird.\n\nEin fähiger Krieger nutzt die Schwäche seiner Gegner aus, und wir wären töricht, wenn wir die Verwundbarkeit der Eisenzwerge in Thor Modan ignorieren würden. Zeigt ihnen keine Gnade. Erschlagt alle und jeden, der sich Euch in den Weg stellt.\n\nDie 'Söhne des Eisens' werden die Horde schon fürchten lernen.", sourceObjective = "Tötet 10 beliebige Eisenzwerge in Thor Modan und kehrt dann zu Späher Vor'takh im Camp Oneqwah zurück.", completion = "<Späher Vor'takh lächelt.>\n\nThor Modan steht also kurz vor dem Fall?\n\nSehr gut. Dann können wir bald unsere Aufmerksamkeit auf Dun Argol richten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12074] = { id = 12074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein nützlicher Verbündeter", description = "Die alte Zwergenhauptstadt Thor Modan, weit im Nordosten, wird von einer mysteriösen Truppe, bestehend aus Steinriesen und Irdenen, belagert.\n\nWarum die Schöpfungen der Titanen gegeneinander Krieg führen, geht über meinen Horizont und liegt außerhalb des Interessengebietes der Horde. Jedoch haben wir hier eine Gelegenheit, einen gemeinsamen Feind zu schwächen.\n\nReist nach Thor Modan und sucht diesen 'Kurun', der die Riesen und die Irdenen befehligt. Macht mit ihm gemeinsame Sache und benutzt seine Streitkräfte, um die Eisenzwerge zu zermalmen.", sourceObjective = "Sprecht mit Kurun auf dem Hügel, der Thor Modan überblickt.", completion = "<Ihr stellt Euch Kurun vor.>\n\nSo sind die Söhne des Eisens also auch Eure Feinde?\n\nMeine Streitkräfte haben die Eisenzwerge in ihrer Stadt eingeschlossen, aber wir könnten Hilfe bei der Erstürmung gebrauchen. Werdet Ihr uns unterstützen?", sourceObjectiveStatus = "unverified-source-field" }
quests[12075] = { id = 12075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mageres Angebot", description = "Kalt hier draußen, findet Ihr nicht, {race}?\n\nKo'char hat sich geweigert, mich zu treffen. Es scheint, als hätte er dringlichere Dinge auf dem Herzen - nämlich Angriffe der Jormungar, die in der Höhle dort unten hausen. Vielleicht könntet Ihr mir dabei helfen, Ko'char davon zu überzeugen, dass ich einer der Guten bin.\n\nIch sah, wie einige der Würmer am Höhleneingang im Norden an einem der Riesen herumnagten... Mir ist es noch immer schleierhaft, weshalb die Würmer sie so leicht töten können. Bringt mir eine Probe seiner Wunden.", sourceObjective = "Beschafft eine Steinfleischprobe von der Eisriesenleiche am Höhleneingang nördlich von Zort in der Kristallschlucht und kehrt wieder zu ihm zurück, sobald die Aufgabe abgeschlossen ist. Er befindet sich in der Nähe des Zentrums der Schlucht.", progress = "Seid Ihr nun mit meiner Probe zurückgekehrt? Ich bin froh, dass Euch die Kälte nicht erwischt hat.", completion = "Das ist perfekt. Danke Euch, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12076] = { id = 12076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreckige Angelegenheit", description = "Sogar beim ersten Anblick lässt sich ganz deutlich erkennen, dass die von Euch gebrachte Probe Zeichen einer ätzenden Spucke aufweist. Logischerweise ist anzunehmen, dass die Würmer dieselbe Substanz, mit der sie sich durch die Erde graben, auch als wirksame Waffe gegen die Eisriesen einsetzen.\n\nNehmt diesen Schaber und fordert ein paar dieser Würmer zum Kampf heraus. Entfernt mit dem Schaber ihre Spucke, wenn Ihr davon getroffen wurdet, und bringt sie hierher.\n\nBeschafft mir eine ordentliche Menge - ich werde das Zeug als Basis für ein Elixier verwenden müssen.", sourceObjective = "Füllt 2 Phiolen mit ätzendem Speichel, indem Ihr den Schaber auf Euch anwendet. Bringt die Phiolen wieder zu Zort in der Kristallschlucht, wenn Eure Aufgabe abgeschlossen ist.", progress = "Da, auf Eurer Schulter scheint noch immer etwas Spucke zu kleben, {race}. Passt auf oder es wird sich glatt durch Eure Rüstung brennen.", completion = "Noch immer frisch. Einen Moment, ich werde das hier mit dem Rest des Elixiers vermischen, das ich vorbereitet habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[12077] = { id = 12077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei Mal am Tag anwenden", description = "Dieses Elixier sollte Schutz vor ihrer Spucke bieten. Würdet Ihr es Ko'char anbieten? Sagt ihm auch, dass es noch viel mehr davon gibt und er es haben kann, wenn er sich erkenntlich zeigen wird.", sourceObjective = "Bietet das von Zort zubereitete Elixier Ko'char dem Unbezwingbaren an.", progress = "Der Wicht möchte, dass wir für ihn kämpfen, nicht wahr? Wie bin ich überrascht.", completion = "Um ehrlich zu sein, mein Kleiner, traue ich dieser Mixtur nicht und werde sie auch nicht probieren. Behalte sie... Du hast vielleicht mehr Vertrauen in diesen naiven Wicht als ich und kannst sie besser gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12078] = { id = 12078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wurmcowboy", description = "So soll es sein. Vielleicht können wir diese Würmer zu irgendwas gebrauchen, wenn die Riesen uns schon nicht helfen wollen. Die Brutmutter in der Höhle dort oben hat sicherlich ihren Nachwuchs in der Nähe. Nehmt diesen Kasten, fangt mir 3 Exemplare ihres Nachwuchses und bringt sie anschließend zu mir.\n\nWo Diplomatie versagt, ist Versklavung eine absolut rentable Alternative.", sourceObjective = "Betretet die Höhlen in der Kristallschlucht und fangt mithilfe stabiler Kisten 3 Exemplare der Jormungarbrut. Achtet jedoch darauf, dass Ihr die Kisten einsteckt, sobald die Jormungarbrut gefangen ist!\n\nBringt sie dann zu Zort in der Kristallschlucht.", progress = "Ihr seid zurückgekehrt! Habt Ihr die Biester mitgebracht? Ich muss hier raus... Ich bin mir ziemlich sicher, dass mich Ko'char vor ein paar Minuten zertreten wollte.", completion = "Das dürfte reichen. Vielleicht werde ich diese Biester, sobald sie voll ausgewachsen sind, zurückbringen und sie eigenhändig mit den Riesen bekannt machen.\n\nEin Haufen unnützer Steine, wenn Ihr mich fragt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12079] = { id = 12079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Revier", description = "Sei gegrüßt, <mein Kleiner/meine Kleine>. Ich weiß zwar nicht, welcher Wahnsinn dich in die Kristallschlucht getrieben hat, doch du bist mir willkommen.\n\nDiese Eiswürmer... diese Jormungar haben Geschmack an meinen Brüdern gefunden. Dass meinesgleichen dir in irgendeiner Art und Weise wohlgesonnen sein werden, halte ich für unwahrscheinlich, doch wenn du uns dabei helfen willst, mit den Würmern fertig zu werden, dann hast du meine ungeteilte Aufmerksamkeit.\n\nWenn wir die Höhle wieder in unseren Besitz bringen wollen, müssen wir zuerst die Schlucht von diesen Jormungarfressern befreien. Steh unserem Kampf bei, {race}!", sourceObjective = "Ko'char der Unbezwingbare möchte, dass Ihr die Höhlen am nördlichen Ende der Kristallschlucht erforscht und 8 Eiskernjormungarfresser tötet.", completion = "Ein Gemetzel nach meinem Geschmack.", sourceObjectiveStatus = "unverified-source-field" }
quests[12080] = { id = 12080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mächtig großer Wurm", description = "In den Höhlen dort unten gibt es eine Brutmutter. Wir nennen sie Rüttelbohrer - ein Name, der Ihr von einem Abenteurer aus den Pestländern beschert wurde. Ich schlug gerade ihren ersten Angriff zurück, als ich sie für einen Moment zu Gesicht bekam. Sie ist groß genug, um selbst meine eisigen Knochen zum Zittern zu bringen. Wir werden die Höhle erst wieder in unseren Besitz bringen können, wenn sie beseitigt ist.\n\nHolt Eure Freunde zur Hilfe und setzt dem Ganzen ein Ende.", sourceObjective = "Betretet die Eiskernhöhlen und streckt Rüttelbohrer nieder. Benutzt Zorts schützendes Elixier, falls Ihr es noch besitzen solltet, um Euch vor dem ätzenden Speichel der Jormungar zu schützen.\n\nKehrt zu Ko'char dem Unbezwingbaren in der Kristallschlucht zurück, wenn die Aufgabe abgeschlossen ist.", completion = "Sie ist also tot - gut, so soll es sein. Du hast auf jeden Fall bewiesen, dass deine Absichten nobler sind als die des Wichts.\n\nÜber die nördliche Schlucht erreicht Ihr den Kristallsangwald. Es ist ein verfluchter und gefährlicher Ort, {race}. Sei auf der Hut, wenn das dein nächstes Ziel sein sollte.\n\nHier, nimm das als Belohnung für deine Mühen, mein Kleiner. Du hast meinen Segen. Gute Reise.", sourceObjectiveStatus = "unverified-source-field" }
quests[12081] = { id = 12081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gavrock", description = "Ohne Eure Hilfe wären wir nicht dazu in der Lage gewesen, das Blatt in der Schlacht um Thor Modan zu unseren Gunsten zu wenden. In dieser uralten Stadt tobt schon seit langem ein Kampf zwischen den Kräften der Erde und des Gesteins. Ich kann nur hoffen, dass wir die Situation eine zeitlang beruhigt haben.\n\nDie Eisenzwerge können noch immer ihre Magie dazu benutzen, um meine Brüder zu versklaven. Gavrock sucht nach einem Weg, wie wir die runenbeschriebenen Riesen befreien können. Ihr könnt ihn auf einer kleinen Inselgruppe namens Ruinen von Tethys finden. Diese Gruppe liegt vor dem zentralen Teil der Ostwindküste gen Süden.", sourceObjective = "Sprecht mit Gavrock in den Ruinen von Tethys.", completion = "Ich weiß, dass Kurun für Eure Hilfe dankbar ist. Der Sieg über Thor Modan wird eine große Errungenschaft für uns sein, doch unsere Brüder werden wir dadurch nicht befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[12082] = { id = 12082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dan-ta dan-ta dan-ta-dah!", description = "Hört zu, <Kleiner/Kleines>. Das hier ist kein Ort, an dem Ihr herumtollen solltet.\n\nIch mach' gleich den Abflug. Bleibt dicht hinter mir und ich hol' Euch hier raus.", sourceObjective = "Eskortiert Harrison aus den Ruinen von Drakil'jin, sprecht dann mit Harkor im gleichnamigen Lager.", completion = "Ihr habt also das kleine Abenteuer mit unserem guten Freund überlebt, hm?\n\nDas sollte Euch eigentlich schon Belohnung genug sein, aber hier - ich habe heute meinen großzügigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12083] = { id = 12083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über dem Waldland", description = "Ich bin davon überzeugt, dass es noch mehr von diesen Fokussen geben muss, von denen wiederum jeder die Leylinienenergien weiterleitet. Wir wissen allerdings immer noch nicht genau, was sie mit all der Energie anstellen wollen.\n\nIch schätze, dass sich ein weiterer auf dem höchsten Punkt des Waldlandes von Lothalor gen Süden befinden muss. Ihr werdet also wieder einmal herausfinden müssen, wer dort das Sagen hat, und ihm anschließend das Steuergerät abnehmen, da ich mir sicher bin, dass es für jeden Fokus ein spezielles Gerät geben muss.\n\nSeid auf der Hut, {name}, die Wälder sind voller Gefahren.", sourceObjective = "Beschafft Euch das Steuerungsamulett des Leylinienfokus und verwendet es, um Informationen vom Leylinienfokus in den Waldländern von Lothalor zu erhalten.\n\nKehrt anschließend zum Abbild der Erzmagierin Modera in Sternenruh zurück.", completion = "Sie erfüllen mithilfe des Fokus ihre Truppen mit Macht? Das ergibt keinen Sinn; so mächtig sind die Magierjäger nicht.\n\nDas muss also bedeuten, dass sie die Magie ausschließlich dort verwenden, wo auch immer sie die jeweilige Leylinie hinleiten.\n\nWir werden mehr Informationen benötigen, wenn wir sie finden und aufhalten wollen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12084] = { id = 12084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über den Waldländern", description = "Ich bin überzeugt, dass es mehr dieser Fokusse gibt - jeder von ihnen leitet die Energie der Leylinien um. Wir wissen jedoch noch nicht genau, was sie mit all dieser Energie anstellen.\n\nIch schätze, Ihr werdet einen weiteren hoch über den Waldländern im Süden finden. Ihr werdet erneut die zuständige Person finden müssen und die Steuerung, welche diese bei sich trägt, an Euch nehmen - ich bin mir sicher, dass jeder Fokus über eine eigene verfügt.\n\nBeeilt Euch bei Eurem Auftrag, {class} Ich spüre, dass uns die Zeit davonrinnt.", sourceObjective = "Beschafft Euch das Steuerungsamulett des Leylinienfokus und verwendet es, um Informationen vom Leylinienfokus in den Waldländern von Lothalor zu erhalten.\n\nKehrt anschließend zum Abbild des Erzmagiers Aethas Sonnenhäscher bei Agmars Hammer zurück.", completion = "Sie bündeln diese Energie in ihren Truppen? Aber das ergibt keinen Sinn - die Magierjäger sind nicht entsprechend mächtig.\n\nDas kann nur bedeuten, dass sie die Energie in Wirklichkeit nur am Endpunkt der Umleitung, die sie an den Leylinien vorgenommen haben, nutzen.\n\nWir werden weitere Informationen benötigen, wenn ich einen Plan ausarbeiten soll, um sie zu stoppen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12085] = { id = 12085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Brief an Zuhause", description = "Im Innenfutter seiner Robe findet Ihr einen Brief, auf dem folgendes geschrieben steht:\n\n\"Deino,\n\nTut Ta'zinni leid, dass er verschwunden ist. Wenn du diesen Brief liest, dann bin ich tot.\n\nDie haben mich gezwungen, für Malygos' Armeen zu malochen. Die haben mir gedroht, meine Familie umzumurksen, wenn ich mich weigern würde. Und Ta'zinni wollte das nicht zulassen!\n\nMach dir um mich keine Sorgen, pass nur gut auf deine Kinder auf. Ich hab die hier ausgetrickst und sabotiere sie jetzt von innen heraus.\n\nHab dich lieb, Schwester!\n\nTa'zinni\"\n\nOberanführer Agmar wird das hier sicherlich sehen wollen!", sourceObjective = "Liefert Leutnant Ta'zinnis Brief bei Oberanführer Agmar in Agmars Hammer ab.", progress = "Was soll das? Wollt Ihr etwa einen Brief verschicken?\n\nAlle Briefe gehen erst mal über mich. Hier gibt es nämlich Spione und Verräter!\n\n<Der Oberanführer mustert Euch kurz. Ihr fragt Euch, ob er nicht auf der Stelle die Wachen rufen und Euch umbringen lassen wird.>\n\nNun gut, aber macht schnell. Sollte mir jedoch nicht gefallen, was ich da geschrieben sehe, dann werde ich Euch an meine Worgs verfüttern.\n\n<Agmar grinst, als sich Gar'mak und Lak'tuk zu Euch umdrehen, mit einem Blick in ihren Augen, als wärt Ihr ihre nächste Mahlzeit.>", completion = "Ahahahaha... ach Herr je, wie rührend.\n\n<Der herablassende Ton im tiefen Gelächter des Oberanführers ist unüberhörbar.>\n\nWas habe ich gesagt? Verräter! Immerhin, es gab einmal eine Zeit, da kannte ich Deino. Zumindest ist sie ein Troll von Ehre!\n\nSie wird herausfinden, was mit ihrem Bruder geschehen ist - dafür werde ich sorgen. Und bei der Gelegenheit werde ich sogar vergessen ihr zu sagen, dass Ihr für seinen Tod verantwortlich seid.\n\n<Agmar starrt Euch an. Sein Blick wirkt berechnend.>\n\nDoch nun gehört Ihr mir, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[12086] = { id = 12086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karkuts Sohn", description = "Der Mann, nach dem Ihr sucht, ist weit nach Osten gegangen und hat einen Ort in Küstennähe jenseits von Unu'pe aufgesucht, den man Todeswehr nennt.\n\nSeid vorsichtig, wenn Ihr dorthin geht und nach ihm sucht, {name}. Er trug das Zeichen Karkuts... der über die Toten wacht.", sourceObjective = "Geht in Richtung Osten nach Todeswehr jenseits von Unu'pe.", completion = "Thassarian? Ja, er war hier... was ist mit ihm? Wir haben dringendere Probleme im Moment, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12088] = { id = 12088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thassarian der Todesritter", description = "Nun, {name}, Ihr habt uns also geholfen... deshalb ist es wohl nur angemessen, wenn wir Euch auch helfen.\n\nIhr sucht nach Thassarian? Er verschwand heute Morgen. Wir vermuten, dass er gen Norden zur klagenden Ziggurat gegangen ist. Wenn wir nicht Seite an Seite mit ihm gekämpft hätten, würden wir ihn sogar für einen Verräter halten.\n\nIhr müsst verstehen, er ist ein Todesritter... und ich weiß, dass diese auf unserer Seite sind und so weiter... aber vor nicht allzu langer Zeit waren diese Arthas' Diener.\n\nAber nicht Thassarian. Er ist ein guter Kerl. Geht zur klagenden Ziggurat und seht, ob er zurechtkommt.", sourceObjective = "Seht nach Thassarian im Inneren der klagenden Ziggurat nördlich von Todeswehr.", completion = "Leryssa... sucht nach mir? Ihr müsst mir helfen, {name}. Wir müssen dies zu Ende bringen, bevor ihr etwas zustößt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12089] = { id = 12089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Magister Keldonus", description = "Auf Erlass des Oberanführers Agmar:\n\nAngeklagter: Magister Keldonus\n\nVerbrechen: Verrat\n\nZustand: lebendig\n\nIm Namen der Horde ist Magister Keldonus, einstiger Magierkommandant von Agmars Hammer, auf der Stelle zu töten.\n\nGesichtet wurde Keldonus das letzte Mal, als er auf dem Weg nach Südwesten in Richtung der Mondruhgärten unterwegs war, um sich dort dem blauen Drachenschwarm und dem Feldzug gegen die Magie anzuschließen.\n\nKeldonus sollte mit Vorsicht begegnet werden. Ein Angriff ist nicht alleine durchzuführen!\n\nHauptmann Gort in Agmars Hammer ist für die Auszahlung aller Kopfgelder verantwortlich.", sourceObjective = "Erschlagt Magister Keldonus und kehrt anschließend zu Hauptmann Gort in Agmars Hammer in der Drachenöde zurück.", completion = "Nicht das Erste dieser Magierweicheier, das uns verraten hat, und sicherlich nicht das Letzte. Ist aber auch verdammt schade... Er war einer unserer besten Magier. Er konnte ein Büffet herzaubern, dass einem das Wasser im Munde zusammenlief und Herzen höher schlugen...\n\nBAH!", sourceObjectiveStatus = "unverified-source-field" }
quests[12090] = { id = 12090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Gigantaur", description = "Auf Erlass des Oberanführers Agmar:\n\nAngeklagter: Gigantaur\n\nVerbrechen: Angriffe auf die Horde; \"potthässlich\"\n\nZustand: lebendig\n\nDer Magnataurenfürst Gigantaur wird in Verbindung mit einer Reihe von Angriffen auf die Soldaten und Anlagen der Horde in der Drachenöde gesucht.\n\nZuletzt wurde Gigantaur in den Wäldern und auf den Straßen südlich und südöstlich von Agmars Hammer gesehen.\n\nGigantaur gilt als bewaffnet und extrem gefährlich. Ein Angriff sollte nicht alleine durchgeführt werden!\n\nHauptmann Gort in Agmars Hammer ist für die Auszahlung aller Kopfgelder verantwortlich.", sourceObjective = "Erschlagt Gigantaur und kehrt anschließend zu Hauptmann Gort in Agmars Hammer in der Drachenöde zurück.", completion = "Ihr habt dieses hässliche Pferdegesicht also erwischt, hm? Tja, eine Plage weniger, um die sich unsere Soldaten draußen auf den eisigen Weiten kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12091] = { id = 12091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Schreckensklaue", description = "Auf Erlass des Oberanführers Agmar:\n\nAngeklagter: Schreckensklaue\n\nVerbrechen: Angriffe gegen die Horde\n\nZustand: lebendig\n\nSchreckensklaue wird wegen zahlreicher Angriffe auf Karawanen der Horde, die entweder nach Gallgrimm oder von dort aus unterwegs waren, gesucht. Ihm sollte mit äußerster Vorsicht begegnet werden. Ein Angriff sollte nicht alleine durchgeführt werden!\n\nHauptmann Gort in Agmars Hammer ist für die Auszahlung aller Kopfgelder verantwortlich.", sourceObjective = "Erschlagt Schreckensklaue und kehrt anschließend zu Hauptmann Gort in Agmars Hammer in der Drachenöde zurück.", completion = "Wurde auch langsam mal Zeit, dass jemand der Metzelei dieser dreckigen Bestie ein Ende macht! Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12092] = { id = 12092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Urtumen Kraft verleihen", description = "Nicht nur Euer Volk ist von dem betroffen, was der blaue Drachenschwarm getan hat. Auch die Urtume der Wälder von Lothalor gen Südosten bekamen die Auswirkungen zu spüren.\n\nEinige fielen der Verderbnis anheim - diese müsst Ihr um jeden Preis meiden -, doch die meisten können noch immer gerettet werden. Die Treants in den Wäldern scheinen jedoch immun gegen die Magie zu sein, die durch das Land sickert und mit der auch die Wyrm kommen.\n\nBittet die Treants um Ihre Borke und gebt sie den Urtumen zu essen. Hoffentlich wird das genügen, um sie zu retten.", sourceObjective = "Benutzt die Borke der Wanderer und stärkt damit 3 Urtume von Lothalor. Kehrt anschließend zu Sarendryana in Sternenruh zurück.", progress = "Ein zusätzlicher Vorteil, der sich durch die Rettung der Urtume ergeben könnte, wäre, dass sie es in Erwägung zögen, die Allianz in ihrer Not zu unterstützen. Ungeachtet dessen, ist es das Richtige zu tun.\n\nWie vielen konntet Ihr nun Kraft verleihen, {class}?", completion = "Ich danke Euch, {race}! Wir haben schon so viel verloren. Ihr habt dafür gesorgt, dass uns die Majestätischsten von Nordends Kindern erhalten bleiben.\n\nIch werde bald gehen und mit den Urtumen sprechen, die Ihr gerettet habt. Mal sehen, ob sie uns in diesen Zeiten der Not nicht helfen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12093] = { id = 12093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runen des Zwangs", description = "Noch während Kurun Thor Modan angreift, wirken die Eisenzwerge ihre Magie gegen unsere Brüder. Indem sie unsere Brüder aus der Erde beschwören und sie mit Runen an sich binden, zwingen die Söhne des Eisens sie zum Kampf gegen die Kinder des Steins.\n\nEntlang der Ostwindküste verwenden sie Runen des Zwangs, um versklavte Riesen zu den Schlachtfeldern im Norden zu entsenden.\n\nFindet die vier Runen des Zwangs und zwingt ihre Aufseher zum Erscheinen, indem Ihr die Runenweber überwältigt, die jede Rune bemannen. Ohne die Aufseher sind die Runen nutzlos.", sourceObjective = "Gavrock in den Ruinen von Tethys möchte, dass Ihr die vier Runen des Zwangs ausschaltet, indem Ihr Aufseher Durval, Aufseher Korgan, Aufseher Lochli und Aufseher Brunon besiegt.", progress = "Habt Ihr die Runen an der Küste ausgeschaltet?", completion = "Gut. Nun müssen wir rasch handeln, bevor die Söhne des Eisens bemerken, dass ihre Runen wirkungslos geworden sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[12094] = { id = 12094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Latente Macht", description = "So lange die Runen des Zwangs nicht aktiv sind, besteht die Chance, dass wir die runenbeschriebenen Riesen freilassen können.\n\nIch werde Euch ein Stück des Steins geben, der schon seit meiner Erschaffung ein Teil von mir geblieben ist. Erfüllt man ihn mit der richtigen Kraft, so kann man mit seiner Hilfe die gefangenen Riesen befreien.\n\nZwischen dem Waldrand und dem Eisenpfad befinden sich Orte der Macht - Orte, die Euer Volk Leylinienknotenpunkte nennen würde - und dort gibt es auch zwei uralte Steinmarkierungen. Eine weitere Steinmarkierung befindet sich auf einer Insel am südlichen Ende dieser Ruinen. Ladet den Splitter bei jedem dieser Steine auf.", sourceObjective = "Ladet den Splitter von Gavrock am ersten, zweiten und dritten uralten Stein auf und kehrt anschließend zu Gavrock in den Ruinen von Tethys zurück.", progress = "Habt Ihr die uralten Steine gefunden?", completion = "Ich kann die Macht spüren, mit der Ihr den Splitter erfüllt habt, und ich hoffe, dass sie genügen wird, um die runische Magie zu bannen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12095] = { id = 12095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Drachenjägerposten", description = "Östlich von hier, im Herzen der Drachenöde, befindet sich ein Feld, auf dem sich nichts als Drachenknochen und Schnee befinden. Die Geißel hat mehrere Lager in der zentralen Tundra aufgeschlagen und ruft Frostwyrm wieder ins Leben, um sie dann auf unsere Streitkräfte an der Pforte des Zorns zu hetzen. Rokhan und seine Drachenjäger können zwar mit den meisten dieser Frostwyrm fertig werden, doch einer von ihnen erweist sich als problematisch.\n\nSucht Rokhan in Drachensturz im Nordosten auf. Helft ihm und seinen Männern Sarathstra niederzustrecken und Ihr werdet reichlich belohnt werden!", sourceObjective = "Sprecht mit Rokhan in Drachensturz in der Drachenöde.", completion = "Denkst du, dass du dort siegen kannst, wo Rokhan versagt?", sourceObjectiveStatus = "unverified-source-field" }
quests[12096] = { id = 12096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkt die Urtume", description = "Die Urtume des Waldlandes von Lothalor im Süden werden von Arkanwyrm verderbt... Wyrm, die direkt aus der Erde gekommen sind!\n\nDie schon Verderbten sind tödlich und nützen uns nichts, doch die meisten können noch immer gerettet werden. Zum Glück scheinen die Treants der Wälder immun gegen alles zu sein, was dort vor sich geht.\n\nBittet die Treants, Euch etwas von ihrer Rinde abzugeben, und verfüttert diese anschließend an die Urtume - das sollte sie stärken.\n\nNun lasst mich in Ruhe arbeiten! Ich muss ein Auge auf diese Apotheker werfen.", sourceObjective = "Benutzt die Borke der Wanderer, um 3 Urtume von Lothalor zu stärken, und kehrt anschließend zu Erdenwächter Graif in Agmars Hammer zurück.", completion = "Habt meinen Dank, {class}.\n\nSobald ich herausgefunden habe, was diese widerwärtigen Apotheker vorhaben, werde ich mich auf den Weg zu den Wäldern machen und sehen, ob ich die Urtume davon überzeugen kann, dass sie sich uns anschließen.\n\nZumindest sollte ich sie davon überzeugen können, ihre Retter in Frieden zu lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12097] = { id = 12097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sarathstra, Geißel des Nordens", description = "Meine Jäga sind tot oda eingefrostet, {name}. Deine einzige Hilfe sind die Leute, die du mitbringst, und du selbst, Mann. Noch imma Lust drauf? Ein Wort reicht und ich werde nochmal nach'm Drachen rufen.\n\nBring das gefrorene Herz vom Biest nach Agmars Hammer und gib es Gort. Er wiad dich ganz bestimmt dick belohnen, Mann.", sourceObjective = "Sprecht mit Rokhan, um den Frostwyrm Sarathstra herbeizurufen.\n\nTötet Sarathstra und liefert Sarathstras gefrorenes Herz bei Hauptmann Gort in Agmars Hammer ab.", progress = "<Gort hebt eine Braue.>\n\nSchon zurück?", completion = "HA! Ihr habt es geschafft! Die Soldaten an der Pforte des Zorns stehen in Eurer Schuld, {name}! Das wird einigen von ihnen sicherlich ein paar Tage mehr auf dieser Welt bescheren.", sourceObjectiveStatus = "unverified-source-field" }
quests[12098] = { id = 12098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchsucht Indu'le", description = "Ich bin mir sicher, dass Ihr den nächsten Leylinienfokus irgendwo in den Überresten von Indu'le im Südosten finden werdet. Das Problem ist nur, dass wir überhaupt keine Meldungen darüber erhalten haben, ob es dort einen gibt oder nicht.\n\nWenn Ihr das Dorf bitte nach irgendwelchen Hinweisen über den Fokus oder die Magierjäger und ihren Kommandanten in der Gegend durchsuchen würdet, wäre ich dankbar.\n\nVergesst nicht, auch im See nachzusuchen, wenn es sein muss.", sourceObjective = "Sucht in Indu'le und im Wasser von Indu'le nach dem Kommandanten der Magierjägertruppen.", completion = "An dieser Stelle findet Ihr die Leiche des Kommandanten der Magierjäger.\n\nNach seinem Aussehen und dem Zustand der Truppen um ihn herum zu urteilen, scheinen sie nicht ertrunken zu sein. Vielmehr erweckt die Szene den Eindruck, als hätten sie den Angriff der Elementare aus den Rissen im Seebett nicht erwartet.\n\nDem Anschein nach waren die Magierjäger für ihr eigenes Ableben verantwortlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[12099] = { id = 12099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich frei", description = "Der Steinsplitter, den Ihr mit Kraft erfüllt habt, sollte mächtig genug sein, um die runische Magie zu bannen, die meine Brüder gefangen hält.\n\nNehmt ihn mit und sucht nach den runenbeschriebenen Riesen, die im Norden die Ostwindküste entlang marschieren. Setzt die Macht, die im Stein gespeichert ist, frei und seht, was passiert.\n\nFalls er funktionieren sollte, dann müssten die Riesen wieder zur Besinnung kommen und den Befehlen der Eisenzwerge nicht mehr Folge leisten. Sollte der Stein nicht funktionieren, ist es möglich, dass die Riesen geschwächt werden und Euch angreifen. Doch haben wir überhaupt eine Wahl? Wenn wir es nicht versuchen, werden sie für immer versklavt bleiben.", sourceObjective = "Befreit mit Gavrocks Runenbrecher 4 runenbeschriebene Riesen und kehrt anschließend zu Gavrock in den Ruinen von Tethys zurück.", progress = "Konntet Ihr irgendeinen meiner Brüder befreien?", completion = "Das Ding ist also nicht zuverlässig? Ich wünschte, dass es keine Frage des Glücks wäre, doch zumindest sind wir auf dem richtigen Weg. Ohne Eure Hilfe, wäre dies nie möglich gewesen. Falls Ihr noch mehr über die Machenschaften der Eisenzwerge und deren Pläne bezüglich der Steinkinder herausfinden solltet, dann sucht uns auf und wir werden Euch anhören, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12100] = { id = 12100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verwesung Einhalt gebieten", description = "Die Geißel bringt Tod und Krankheit mit sich. Wir übersehen nur zu oft, dass die Tierwelt in den von der Geißel verseuchten Gegenden stark angeschlagen ist und durch die ansteckende Verwesung letztendlich ausgelöscht wird.\n\nFür die meisten einheimischen Tiere der Drachenöde ist es schon zu spät. Die Tiere sind schon mit der Krankheit der Geißel infiziert, deren Kennzeichen eitrige Pusteln sind - nun verwesen sie vor sich hin und sind von Tollwut befallen.\n\nGeht nach Westen zur Grube von Narjun und tötet die infizierten Tiere. Seht nach, ob sich in ihren Leichen ein gut erhaltenes Organ finden lässt, da wir eins brauchen, um ein Gegengift daraus herzustellen.", sourceObjective = "Soar Falkenzorn in Agmars Hammer in der Drachenöde möchte, dass Ihr 15 infizierte Wildtiere tötet und ein verwesungsresistentes Organ beschafft.", progress = "Tötet die Tiere, um die Verbreitung der Krankheit zu verhindern, und bringt mir ein verwesungsresistentes Organ.", completion = "Zwar schmerzt es mich, Tiere zu töten, jedoch müssen wir uns dieser Pflicht annehmen. Kommen wir nun zum nächsten Schritt: der Impfung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12101] = { id = 12101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gute Doktor...", description = "Die Verlassenen, unsere Verbündeten, haben die wichtigsten Mitglieder ihrer Apothekervereinigung hierher entsandt, um uns bei der Vernichtung der Geißel an der Pforte des Zorns zu unterstützen. Unter ihnen befindet sich jemand namens Doktor Sintar Malefius, ein Kenner, wenn es um die Fäulnis der Geißel und deren Verbreitung geht. Ich hatte zuvor mit ihm eine Einigung in Bezug auf die Impfung der betroffenen Tiere erzielt - seitdem wartet er auf ein Organ.\n\nLiefert dieses verwesungsresistente Organ bei Dr. Malefius ab und lasst ihn wissen, dass es von mir ist. Von ihm werdet Ihr auch Euren nächsten Auftrag erhalten.", sourceObjective = "Liefert das verwesungsresistente Organ bei Doktor Sintar Malefius in Agmars Hammer ab.", progress = "Was jetzt?", completion = "Der rüpelhafte Ochsenmensch konnte tatsächlich ein verwesungsresistentes Organ besorgen? Verflucht... ich war mir sicher, dass diese Aufgabe seinen missgebildeten Geist bis ins nächste Jahrtausend beschäftigen würde.\n\nNa gebt schon her, Junge. Ich habe ohnehin schon viel zu tun, auch wenn Eure schwächlichen Bedürfnisse mir nicht gerade im Weg stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12102] = { id = 12102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach dem rubinfarbenen Flieder", description = "Ein Glücksfall, dass der Rubindrachenschrein gleich im Osten liegt. Dort findet sich auch eine Blume, die man den rubinfarbenen Flieder nennt. Diese lebensspendende Pflanze ist alles, was ich brauche, um einen Impfstoff für die gesunden Tiere dieser Region herzustellen.\n\nGeht nach Osten und sucht im Rubindrachenschrein nach dem Flieder.\n\nEine Sache noch: Wie alle Drachenschreine in dieser verfluchten Einöde so wird auch dieser Drachenschrein von der Geißel heimgesucht. Passt also auf, wo Ihr hintretet. Wir wollen doch nicht, dass Ihr von einem Glutwyrm verschlungen werdet.\n\n<Sintar lacht.>", sourceObjective = "Doktor Sintar Malefius in Agmars Hammer in der Drachenöde möchte, dass Ihr 1 rubinfarbenen Flieder pflückt.", progress = "Habt Ihr den rubinfarbenen Flieder dabei?", completion = "Das war doch nicht so schwer, oder?\n\nNun gebt mir ein wenig Zeit, damit ich den Impfstoff herstellen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[12104] = { id = 12104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zu Soar zurück", description = "<Doktor Malefius gibt Euch eine Phiole, die mit einer trüben Flüssigkeit gefüllt ist.>\n\nBitte schön, {race}. Bringt das hier wieder zu diesem Rindvieh und lasst es wissen, dass damit alle Schulden beglichen sind. Wir sind nun ganz offiziell wieder quitt.\n\nLasst mich allein, bevor ich Jennings auf Euch loslasse.", sourceObjective = "Liefert Sintars Impfstoff bei Soar Falkenzorn in Agmars Hammer ab.", progress = "Habt Ihr den Impfstoff dabei?", completion = "<Soar hält die Phiole in die Höhe und überprüft seinen Inhalt.>\n\nBleibt nur noch eine Sache zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[12105] = { id = 12105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abstieg in die Dunkelheit", description = "Das Tagebuch wurde von einem Einwohner Silberwassers namens Mikhail geschrieben. Es beschreibt die Ankunft einer Gruppe von Schattenanbetern, die sich \"Wolfskult\" nannten.\n\nZunächst waren die Dorfbewohner zögerlich, sich dem Kult anzuschließen, aber mit der Zeit gab es mehr und mehr Sympathisanten unter der Bevölkerung.\n\nBeunruhigt dadurch, schickte Mikhail seine Tochter Dasha aus Silberwasser fort, und er versuchte, vernünftig mit den Dörflern zu reden.\n\nSein letzter Eintrag erwähnt eine Versammlung der Dorfoberen, um nicht näher beschriebene Ereignisse in der Hohlsteinmine zu diskutieren.", sourceObjective = "Bringt Mikhails Tagebuch zu Leutnant Dumont bei der Ammertannhütte.", progress = "Was habt Ihr da?", completion = "Ich dachte mir doch, dass es mehr damit auf sich hat, als lediglich ein isoliertes Dorf voller Feinde.\n\nWir haben ein paar Männer in der Nähe der Hohlsteinmine, vielleicht lohnt es sich ja, sich dort ein wenig umzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12106] = { id = 12106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchsucht Indu'le", description = "Ich bin mir sicher, dass Ihr den nächsten Leylinienfokus irgendwo in den Überresten von Indu'le im Südosten finden werdet. Das Problem ist nur, dass ich überhaupt keine Meldungen darüber erhalten habe, ob es dort einen gibt oder nicht.\n\nIch möchte, dass Ihr Euch im Dorf nach irgendwelchen Hinweisen über den Fokus oder die Magierjäger und ihren Kommandanten in der Gegend umseht.\n\nSucht auch im See nach, wenn es sein muss!", sourceObjective = "Sucht in Indu'le und im Wasser von Indu'le nach dem Kommandanten der Magierjägertruppen.", completion = "An dieser Stelle findet Ihr die Leiche des Kommandanten der Magierjäger.\n\nNach seinem Aussehen und dem Zustand der Truppen um ihn herum zu urteilen, scheinen sie nicht ertrunken zu sein. Vielmehr erweckt die Szene den Eindruck, als hätten sie den Angriff der Elementare aus den Rissen im Seebett nicht erwartet.\n\nDem Anschein nach waren die Magierjäger für ihr eigenes Ableben verantwortlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[12107] = { id = 12107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endstation", description = "In seinen Roben findet Ihr zwei Dinge von Interesse.\n\nZum einen handelt es sich um einen Talisman, der eindeutig zur Steuerung eines Fokus dient. Zum anderen um eine Sammlung mehrerer Befehle, die von jemand namens Sidragos ausgestellt wurden und letztendlich für den Anführer in den Mondruhgärten gedacht waren.\n\nLaut Anordnung auf dem nassen Pergament, soll Goramosh all seine Magierjägertruppen nach Osten zum Azurdrachenschrein beordern.\n\nVielleicht solltet Ihr so viel wie möglich von dem Fokus erfahren und dann nach Osten gehen, um den Drachenschrein von der westlichen Seite her beobachten zu können.", sourceObjective = "Benutzt den Steuerungstalisman des Leylinienfokus, um Informationen vom Leylinienfokus unter dem Wasser von Indu'le zu erhalten. Geht anschließend nach Osten zum Azurdrachenschrein, der sich vom Zentrum der Drachenöde aus gesehen weiter südlich befindet, und beobachtet das dortige Vorgehen vom westlichen Felsvorsprung aus.\n\nKehrt danach zum Abbild der Erzmagierin Modera in Sternenruh zurück.", completion = "WAS?!\n\n<Einen Augenblick lang verzerrt sich das Abbild vor Euch, während die Erzmagierin versucht, ihre Fassung wiederzugewinnen.>\n\nAber natürlich, wir hätten eigentlich wissen müssen, dass sie das die ganze Zeit über vorhatten. Schnell, es gibt keine Zeit zu verlieren.\n\nWyrmruh muss gewarnt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[12108] = { id = 12108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mikhails Grab", description = "Der Erdhaufen ist in Wahrheit ein hastig gebuddeltes Grab. Der darin befindliche Körper ist nicht mehr erkennbar, aber Ihr findet eine Notiz, die ihn als Mikhail identifiziert.\n\nDie Notiz erwähnt erneut die Holhsteinmine. Vielleicht kennt sich bei der Ammertannhütte jemand in der Gegend aus.", sourceObjective = "Bringt Mikhails Notiz zum Kartografen Tobias bei der Ammertannhütte.", sourceObjectiveStatus = "unverified-source-field" }
quests[12109] = { id = 12109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch bei Gryan Starkmantel... schon wieder", description = "Die Jungs von Westfall wurden nach Osten geschickt, um einen Weg in die nördlichen Territorien zu finden. Ihr zweites Missionsziel ist das Sicherstellen von strategisch wichtigen Ressourcen - ich bin mir also sicher, dass es ihnen nichts ausmachen würde, eine Mine zu untersuchen.\n\nSucht nach dem Lager der Westfallbrigade weit im Nordosten und sucht nach Gryan Starkmantel. Ihr werdet Euch vielleicht noch an ihn erinnern können, wenn Ihr jemals schon in Westfall gewesen seid. Sagt ihm auf jeden Fall, dass ich Euch geschickt habe.\n\nEr wird Euch nur zu gerne erlauben, eine intakte Mine für den König in Besitz zu nehmen.", sourceObjective = "Sprecht mit Hauptmann Gryan Starkmantel im Lager der Westfallbrigade.", completion = "Dumont hat Euch geschickt? Schön. Sehen wir einmal, was Ihr für uns tun könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12110] = { id = 12110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endstation", description = "In seinen Roben findet Ihr zwei Dinge von Interesse.\n\nZum einen handelt es sich um einen Talisman, der eindeutig zur Steuerung eines Fokus dient. Zum anderen um eine Sammlung mehrerer Befehle, die von jemand namens Sidragos ausgestellt wurden und letztendlich für den Anführer in den Mondruhgärten gedacht waren.\n\nLaut Anordnung auf dem nassen Pergament, soll Goramosh all seine Magierjägertruppen nach Osten zum Azurdrachenschrein beordern.\n\nVielleicht solltet Ihr so viel wie möglich von dem Fokus erfahren und dann nach Osten gehen, um den Drachenschrein von der westlichen Seite her beobachten zu können.", sourceObjective = "Benutzt den Steuerungstalisman des Leylinienfokus, um Informationen vom Leylinienfokus unter dem Wasser von Indu'le zu erhalten. Geht anschließend nach Osten zum Azurdrachenschrein, der sich vom Zentrum der Drachenöde aus gesehen weiter südlich befindet, und beobachtet das dortige Vorgehen vom westlichen Felsvorsprung aus.\n\nKehrt danach zum Abbild des Erzmagiers Aethas Sonnenhäscher in Agmars Hammer zurück.", completion = "WAS?!\n\n<Einen Augenblick lang verzerrt sich das Abbild vor Euch, während der Erzmagier versucht, seine Fassung wiederzugewinnen.>\n\nAber natürlich, wir hätten eigentlich wissen müssen, dass sie das die ganze Zeit über vorhatten. Schnell, es gibt keine Zeit zu verlieren.\n\nDer Wyrmruhtempel muss gewarnt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[12111] = { id = 12111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo die wilden Tiere wohnen", description = "In dieser Packung befinden sich mehrere Phiolen mit dem von Sintar hergestellten Gegengift. Nun möchte ich, dass Ihr die Wälder in der Nähe nach Schneewehenelchen und arktischen Grizzlys absucht. Werft, wenn Ihr eines der Tiere gefunden habt, eine Phiole in deren Nähe. Die Phiole wird zerspringen und ein dünnes Gas freisetzen, das als Impfstoff dienen wird. Die Tiere müssen lediglich in die Gaswolke hineingehen, um geimpft und letztendlich gerettet zu werden.\n\nVerabreicht den Impfstoff so vielen Tieren wie nur möglich und kehrt anschließend zu mir zurück.", sourceObjective = "Soar Falkenzorn in Agmars Hammer in der Drachenöde möchte, dass Ihr mithilfe der Packung mit Impfstoffen 5 Schneewehenelche und 5 arktische Grizzlys impft.", completion = "Ihr habt etwas Ehrenhaftes getan, {name}. Ich bitte Euch, sucht Euch eine Belohnung aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[12112] = { id = 12112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstarrte Verhandlungen", description = "Nun, es scheint, als hättet Ihr Euch letztendlich doch ein wenig nützlich gemacht. Meiner Erfahrung nach, gibt es nicht viele Eures Volkes, die das von sich behaupten können.\n\nWir haben hier keine Verwendung mehr für Euch. Geht zur Kristallschlucht und seht nach, ob mein Bruder Zort ein helfendes Händchen gebrauchen könnte. Er wollte die Riesen davon überzeugen, ob sie nicht ihr Leben lassen wollen, damit wir's nicht tun müssen. In unserer Familie galt er nicht gerade als der Klügste.", sourceObjective = "Geht zum Zentrum der Kristallschlucht und sucht Zort auf.", completion = "Ich lass mir was einfallen, wie Ihr Euch nützlich machen könnt - bleibt noch ein Weilchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12113] = { id = 12113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohne Fleisch kein Preis", description = "Guten Tag, {class}! Wollt Ihr Euch nicht an mein Feuer setzen?\n\nIch würde Euch zwar eine gute, heiße Mahlzeit anbieten, nur habe ich keine. Ich sitze hier fest und warte auf einen Kumpanen, ansonsten würde ich mich selbst um die Sache kümmern.\n\nIhr scheint mehr als genug Zeit übrig zu haben und in dieser Gegend gibt es eine Menge Fleisch. Was würdet Ihr davon halten, wenn Ihr mir helfen und etwas zu Essen beschaffen würdet?", sourceObjective = "Harkor in Harkors Lager möchte, dass Ihr 10 Stück feinfasriges Worgfleisch von den streunenden Grauheulern und 10 Schaufelhornsteaks von den Langhufgrasfressern beschafft.", progress = "Mein Bauch knurrt, {race}. Konntet Ihr etwas zu Essen beschaffen?", completion = "Ausgezeichnet!\n\nNichts schmeckt besser zum Bier als ein heißes Stück Fleisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[12114] = { id = 12114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Therapie", description = "Trolle… Ich hass'se alle! <Harkor spuckt.>\n\nIch hab's ja mal geschafft, so 'ner Bande von Bestien in die Hände zu fallen… War so nah dran, mir meinen Kopf schrumpfen zu lassen!\n\nMeine Freunde sagen mir, ich solle einfach weitermachen und das alles hinter mir lassen, aber das geht einfach nich'.\n\nWollt Ihr wissen, was mich glücklich machen würde, {race}? 'Nen Haufen ihrer Leichen zu sehen, so hoch, dass er die Sonne verdunkelt! Ich hab' gutes Gold für Euch, wenn Ihr das möglich macht.", sourceObjective = "Harkor in Harkors Lager möchte, dass Ihr 10 Drakkaribeschützer und 10 Drakkariorakel außerhalb der Ruinen von Drakil'jin tötet.", completion = "Habt Dank, {class}.\n\nWenn es die Zeit erlaubt, werd' ich aufsteh'n und mal ein bisch'n herumschauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12115] = { id = 12115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koltira und die Sprache des Todes", description = "Es gibt einen, der sich vor Kurzem unserer Sache verschrieben hat, jemanden, der diesen Folianten womöglich entschlüsseln kann. Ein freier Todesritter hat sich vorübergehend hier in Agmars Hammer niedergelassen. Einst stand er im Dienste von Arthas und war ein Mitglied der Geißel - vielleicht ist er dazu imstande, die Sprache der Toten zu übersetzen.\n\nNehmt den fleischgebundenen Folianten, bringt ihn zu Koltira und bittet ihn, die Seiten zu übersetzen.", sourceObjective = "Bringt den fleischgebundenen Folianten zu Koltira Todesweber.", progress = "Was ist, {race}?", completion = "Es gibt nur zwei Dinge im Leben, die mich interessieren, Peon, und einen Folianten der Geißel für Euch zu übersetzen, gehört nicht dazu.\n\nJedoch... vielleicht könnte sich ja was arrangieren lassen, das uns beiden zugute kommt.\n\n<Koltira zieht sein Schwert aus der Scheide.>\n\nDas ist meine Runenklinge Bifrost - und Bifrost durstet es nach dem Blut des Lichkönigs und seiner Diener; doch zuerst muss ich Runen der Macht auf seine Klinge einprägen: Symbole des Frosts, des Blutes und des Unheiligen. Bringt mir die passenden Quellen der Macht und ich werde Euren Folianten übersetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12116] = { id = 12116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Man braucht schon einen starken Magen...", description = "Seid gegrüßt, {class}. Nett von Euch, anzuhalten und Euch Kraz' Geschichte anzuhören.\n\nSeit vielen Jahren bemüht sich Kraz, die Geister zu hören und ihre Wünsche zu erfüllen.\n\nIn letzter Zeit hat Kraz viele Stimmen aus diesen Ruinen rufen gehört. Sie streben nach Frieden, den sie alleine nicht finden können.\n\nWenn Ihr den Geistern derer, die zuvor gekommen sind, helfen wollt, so betretet die Gruft und sammelt etwas, das einst diesen gequälten Seelen gehörte.", sourceObjective = "Kraz in Harkors Lager möchte, dass Ihr Euch in die Ruinen von Drakil'jin begebt und 5 Drakkarikanopen einsammelt.", progress = "Was habt Ihr in der Gruft für Kraz gefunden, {class}?", completion = "Innereien? Eine interessante Wahl, {race}.\n\nKraz soll mal sehen, was man alles von ihnen lernen kann. Danke, dass Ihr Euch in die Tiefen dieses Ortes gewagt und der Gefahr getrotzt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12117] = { id = 12117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reist zum Hafen Moa'ki", description = "{race}, gerade erhielten wir Kunde aus dem Hafen Moa'ki. Heute Morgen ist dort etwas sehr schreckliches passiert!\n\nIhr wart uns hier eine große Hilfe. Würdet Ihr auf das Boot steigen und in Richtung Drachenöde reisen?\n\nSo wie sich die Dinge anhören, könnte Ältester Ko'nani mit Sicherheit Eure Hilfe gebrauchen.", sourceObjective = "Reist zum Hafen Moa'ki in der Drachenöde und sprecht mit dem Ältesten Ko'nani.", completion = "Was sagt Ihr, {race}? Hotawa hat Euch geschickt?\n\nGut, gut... es gibt viel zu tun. Wir können jede Hilfe, die man uns anbietet, gebrauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12118] = { id = 12118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reist zum Hafen Moa'ki", description = "{race}, gerade erhielten wir Kunde aus dem Hafen Moa'ki. Heute früh ist dort etwas sehr Schreckliches passiert!\n\nIhr wart uns hier eine große Hilfe. Wäre es denkbar für Euch, auf das Boot zu steigen und in Richtung Drachenöde zu reisen?\n\nSo wie sich die Dinge anhören, könnte Häuptling Ko'nani mit Sicherheit Eure Hilfe gebrauchen.", sourceObjective = "Reist zum Hafen Moa'ki in der Drachenöde und sprecht mit Häuptling Ko'nani.", completion = "Was sagt Ihr mir da, {race}? Anuniaq hat Euch geschickt?\n\nGut, gut... es gibt viel zu tun. Wir können jede Hilfe, die sich uns bietet, gebrauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12119] = { id = 12119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Audienz erhalten", description = "{name}, Ihr müsst so schnell, wie Ihr könnt, zum Wyrmruhtempel reisen und dem Bediensteten Tariolstrasz diesen Brief überreichen.\n\nDer Tempel liegt im Zentrum der Drachenöde. Folgt der Straße in östliche Richtung bis zu ihrem Ende und durchquert die Dracheneiswüste, um dorthin zu gelangen.\n\nWenn der Bedienstete Euer Vorstellungsschreiben erst einmal gesehen hat, wird er Euch sicherlich eine Audienz bei Königin Alexstrasza beschaffen, denke ich. Wir können nur darauf hoffen, dass es nicht schon zu spät ist.\n\nIch danke Euch für all das, was Ihr für uns getan habt. Gute Reise!", sourceObjective = "Geht zum Wyrmruhtempel und liefert das Vorstellungsschreiben bei Tariolstrasz ab.", progress = "Ja? Was kann ich für Euch tun, {race}?", completion = "Ein Vorstellungsschreiben und Gesuch um ein Treffen mit der Königin? Zeigt einmal her.\n\nWas auch immer Euer Anliegen auch sein mag, ich hoffe es ist wichtig. Der Himmel wimmelt heute nur so von angreifenden Blauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12120] = { id = 12120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlaghammer von Drak'aguul", description = "Verderbnis...\n\nKraz hatte sie sogar schon spüren können, bevor Ihr die Töpfe brachtet. Die Verderbnis erfüllt die uralten Drakkarigeister mit großer Angst und hält sie davon ab, die Ruhe zu finden, nach der es sie verlangt.\n\nKraz wird nicht lügen, {class}. Diesen Ort zu reinigen wird ein großes Opfer abverlangen, doch darüber werden wir ein anderes Mal sprechen.\n\nUnter den Lebenden hier befindet sich einer, der den Schlüssel zu seiner Läuterung in Händen hält. Sucht Drak'aguul auf und bringt Kraz seinen Schlaghammer.", sourceObjective = "Kraz in Harkors Lager möchte, dass Ihr Drak'aguul außerhalb der Ruinen von Drakil'jin tötet und mit dem Schlaghammer von Drakil'jin zurückkehrt.", progress = "Habt Ihr den Schlaghammer gefunden, {name}?", completion = "So weit, so gut, {name}, doch nun kommt die wahre Prüfung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12121] = { id = 12121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir sehen uns auf der anderen Seite wieder", description = "Diese Drakkari sind Euch eindeutig mit barbarischer Feindschaft begegnet. Ihr schuldet ihnen gar nichts. In der Tat sind es nur Wenige, welche die Aufgabe, die Kraz heute von Euch verlangt hat, ausführen würden.\n\nUm diesen Ort zu reinigen und die Geister ihrer letzten Ruhe zu übergeben, müsst Ihr sie im Reich des Todes wiedertreffen.\n\nIn der Krypta ist jemand, der Euch auf der anderen Seite erwartet. Er hat die Informationen, die wir benötigen, {name}.\n\nSchlagt die Gongs mit dem Hammer. Der Geist dessen, der diesen Ort verdirbt, wird Euch mit Sicherheit in die Geisterwelt befördern.\n\nKraz erwartet Eure Wiederkehr.", sourceObjective = "Kraz in Harkors Lager möchte, dass Ihr den Schlaghammer von Drakil'jin auf die Gongs außerhalb der Ruinen von Drakil'jin anwendet. Ihr sollt die Ruinen betreten, sobald Ihr erschlagen wurdet, und mit dem Geist von Gan'jo sprechen, solange Ihr tot seid.", completion = "Euer Kommen wurde vorhergesagt, {class}. Es ist gut, dass Ihr gekommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[12122] = { id = 12122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Audienz erhalten", description = "{name}, Ihr müsst so schnell wie Ihr könnt zum Wyrmruhtempel reisen und dem Bediensteten Tariolstrasz diesen Brief überreichen.\n\nDer Tempel liegt im Zentrum der Drachenöde. Folgt der Straße in östliche Richtung bis zu ihrem Ende und durchquert die Dracheneiswüste, um dorthin zu gelangen.\n\nWenn der Bedienstete Euer Vorstellungsschreiben erst einmal gesehen hat, wird er Euch sicherlich eine Audienz bei Königin Alexstrasza beschaffen, denke ich. Wir können nur darauf hoffen, dass es nicht schon zu spät sind.\n\nIch danke Euch für all das, was Ihr für uns getan habt. Gute Reise!", sourceObjective = "Geht zum Wyrmruhtempel und liefert das Vorstellungsschreiben bei Tariolstrasz ab.", progress = "Ja? Was kann ich für Euch tun, {race}?", completion = "Ein Vorstellungsschreiben und Gesuch um ein Treffen mit der Königin? Zeigt einmal her.\n\nWas auch immer Euer Anliegen auch sein mag, ich hoffe, es ist wichtig. Der Himmel wimmelt heute nur so von angreifenden Blauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12123] = { id = 12123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Königin verständigen", description = "<Der Drachenwächter zieht Euer Vorstellungsschreiben aus dem Ärmel.>\n\nJa... ja, ich meine, dass Ihr jetzt zur Königin gehen könnt.\n\nSagt mir Bescheid, wenn Ihr bereit seid, und ich werde dafür sorgen, dass einer dieser Drachen Euch sicher zur obersten Etage des Tempels bringen wird. Ihr werdet Euren Brief persönlich an Königin Alexstrasza überreichen müssen.", sourceObjective = "Liefert Euer Vorstellungsschreiben bei Alexstrasza der Lebensbinderin im Wyrmruhtempel ab.", progress = "Schön, Euch endlich persönlich kennenzulernen, {name}. Ich kannte Euch schon, da wart Ihr noch nicht geboren.", completion = "Ihr habt viel Mut, uns diese Informationen zu bringen. Ich habe mich schon gewundert, weshalb der blaue Drachenschwarm einen so waghalsigen Angriff auf den Tempel selbst eingeleitet hat. Nun wissen wir, dass sie riesige Mengen genau der Magie verwenden, die ihrer Ansicht nach eine Bedrohung für Azeroth darstellt.\n\n<Die Königin schüttelt ihren Kopf, scheinbar vor Ratlosigkeit.>\n\nScheinheilig, aber was soll's. Wenn Malygos nicht wieder zur Vernunft kommt, haben wir keine andere Wahl, als auf ihren Angriff Taten folgen zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12124] = { id = 12124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Königin verständigen", description = "<Der Drachenwächter zieht Euer Vorstellungsschreiben aus dem Ärmel.>\n\nJa... ja, ich meine, dass Ihr jetzt zur Königin gehen könnt.\n\nSagt mir Bescheid, wenn Ihr bereit seid, und ich werde dafür sorgen, dass einer dieser Drachen Euch sicher zur obersten Etage des Tempels bringen wird. Ihr werdet Euren Brief persönlich an Königin Alexstrasza überreichen müssen.", sourceObjective = "Liefert Euer Vorstellungsschreiben bei Alexstrasza der Lebensbinderin im Wyrmruhtempel ab.", progress = "Schön, Euch endlich persönlich kennenzulernen, {name}. Ich kannte Euch schon, da wart Ihr noch nicht geboren.", completion = "Ihr habt viel Mut, uns diese Informationen zu bringen. Ich habe mich schon gewundert, weshalb der blaue Drachenschwarm einen so waghalsigen Angriff auf den Tempel selbst eingeleitet hat. Nun wissen wir, dass sie riesige Mengen genau der Magie verwenden, die ihrer Ansicht nach eine Bedrohung für Azeroth darstellt.\n\n<Die Königin schüttelt ihren Kopf, scheinbar vor Ratlosigkeit.>\n\nScheinheilig, aber was soll's. Wenn Malygos nicht wieder zur Vernunft kommt, haben wir keine andere Wahl, als auf ihren Angriff Taten folgen zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12125] = { id = 12125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Dienste des Blutes", description = "Einst stillte das Blut Unschuldiger den Durst der Klinge - doch leider bietet sich mir diese Möglichkeit nicht mehr.\n\n<Koltira hält inne und denkt nach.>\n\nWir müssen improvisieren. Südlich von hier, oben auf den hohen Klippen befindet sich das Tuskarrdorf Indu'le. Erst kürzlich wurde es vom blauen Drachenschwarm mit seiner chaotischen Magie überrannt, was die dort heimischen Tuskarr in den Wahnsinn trieben.\n\nNehmt diese Blutgemme hier und wendet sie auf die geistig verwirrten Dorfbewohner an. Wenn ich das Blut Unschuldiger schon nicht haben kann, dann soll mir das Blut der Sanftmütigen gehören!", sourceObjective = "Koltira Todesweber in Agmars Hammer in der Drachenöde möchte, dass Ihr die Blutgemme auf die verstörten Bewohner von Indu'le anwendet und sie gefüllt wieder zu ihm zurückbringt.", progress = "Bringt mir das Blut der Sanftmütigen.", completion = "Eine simple Aufgabe für jemanden so simpel, wie Ihr es seid. Ihr habt meine Erwartungen erfüllt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12126] = { id = 12126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Dienste des Unheiligen", description = "Die Macht des Unheiligen ist unter meinesgleichen begehrt. Sie ist Grundlage unserer Existenz und gewährt jenen den Tod, die es wagen sollten, sich darüber zu mokieren! Glücklicherweise gibt es einen Quell, der mich in Zeiten der Not mit Energie versorgt.\n\nNehmt diese unheilige Gemme und macht Euch auf den Weg zum östlich gelegenen Rubindrachenschrein. Dort werdet Ihr auch Fürst Vallenhal, einen von Arthas' Todesrittern, finden. Schwächt ihn im Kampfe und entfesselt dann die Macht der Gemme. Sie wird ihm den Rest geben und ihm seine unheilige Energie nehmen!", sourceObjective = "Koltira Todesweber in Agmars Hammer in der Drachenöde möchte, dass Ihr die unheilige Gemme auf Fürst Vallenhal anwendet und sie gefüllt wieder zu ihm zurückbringt.", progress = "Füllt die Gemme mit unheiliger Macht!", completion = "<Koltira macht große Augen.>\n\nBeeindruckend. Ihr habt einen von Arthas' Todesrittern besiegt... Sicherlich wart Ihr nicht allein... doch immerhin...", sourceObjectiveStatus = "unverified-source-field" }
quests[12127] = { id = 12127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Dienste des Frosts", description = "Die beißende Kälte beschützt den Todesritter und hält seine Feinde fern. Er beherrscht die Macht des Frosts, bringt Chaos und Zerstörung!\n\nNehmt diese Frostgemme und durchquert die Tundra der Drachenöde, bis Ihr den Spiegel der Morgenröte östlich des Wyrmruhtempels erreicht. Dort, auf dem zugefrorenen See, werdet Ihr Euch Legionen von Eisklagegeistern stellen müssen und ihnen die Essenz des Frosts abnehmen. Bedient Euch der Macht der Gemme, sobald sie geschwächt sind, {name}!", sourceObjective = "Koltira Todesweber in Agmars Hammer in der Drachenöde möchte, dass Ihr die Frostgemme auf die Eisklagegeister anwendet und sie gefüllt zu ihm zurückbringt.", progress = "Hier in Nordend stehen wir alle im Dienste des Frosts.", completion = "Ich spüre, {name}, wie mich die Kälte durchströmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12128] = { id = 12128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seht mal nach Raegar", description = "Bei all der Aufregung um die Armee, die versucht, durch Thor Modan zu ziehen, hätte ich Raegars Truppe unten beim Prospektorat beinahe vergessen.\n\nIch habe Raegar und seine Assistenten gemeinsam mit einem Bergsteigerfreund dorthin geschickt, um einen kleinen Posten in der Nähe von Dun Argol am südlichen Zipfel der Ostwindküste zu errichten.\n\nSie wollten die Eisenzwerge ausspionieren, die sich in den südlichen Hügeln aufhalten, doch ich habe noch nichts von ihnen gehört. Könntet Ihr einmal nachsehen, ob es ihnen gut geht, wenn Ihr schon in diese Richtung unterwegs seid?", sourceObjective = "Sprecht mit Raegar Brechbraue im Prospektorat.", completion = "Hmm... Ihr seht zwar nicht wie ein Forschungsassistent aus, doch das macht nichts. Die Eisenzwerge bereiten sich auf einen Krieg vor und mein Forschungsteam ist noch nicht zurückgekehrt. Wir könnten hier etwas Hilfe gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12129] = { id = 12129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der perfekte Plan", description = "Die Eisenzwerge machen keinen Hehl daraus, dass sie Kriegsvorbereitungen treffen. Mit ihren Riesen, Golems und Blitzelementaren haben sie den technologischen Vorteil gegenüber der Westfallbrigade. Sollte es ihnen nicht rechtzeitig gelingen, einen Weg in den Norden zu finden, könnten die Eisernen sie überraschen.\n\nWir müssen sie hier halten und ich weiß auch genau den richtigen Weg dafür. Dun Argol ist voller Runenschmiede, die am Fließband Kriegsgolems produzieren. Sie tragen die Pläne für die spezifischen Teile bei sich, also müsst Ihr alle Stücke finden und zusammensetzen.", sourceObjective = "Bringt Raegar Brechbraue im Prospektorat die kompletten Blaupausen für einen Kriegsgolem.", progress = "Ist es Euch gelungen, die Pläne von den Runenschmieden zu bekommen?", completion = "Ihr habt sie alle? Exzellent! Ich kann es kaum abwarten, den Ausdruck auf ihren Gesichtern zu sehen, sobald der Golem fertig ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[12130] = { id = 12130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieber requirieren als produzieren", description = "Wir haben die Blaupausen, aber ohne entsprechende Bauteile können wir nichts damit anfangen! Wir haben keinen Zugang zu einer Schmiede, zu Materialien noch viel weniger. Aber es gibt in Dun Argol eine ganze Ladung Materialien.\n\nEuer Job?\n\nGebt ihnen ein neues Zuhause.\n\nVermutlich sind sie um die Gebäude, in denen die Eisenrunenschmiede arbeiten, herum verteilt. Würde mich nicht wundern, wenn die Runenschmiede ein wenig gereizt reagieren, wenn Ihr ihnen die Früchte ihrer harten Arbeit stehlt. Je mehr Ihr bringen könnt, desto besser wird dieser Golem.", sourceObjective = "Bringt 8 Teile eines Kriegsgolems zu Raegar Brechbraue im Prospektorat.", progress = "Ich sehe, dass Ihr es in einem Stück da raus geschafft habt. Habt Ihr die Teile?", completion = "<Raegar wischt sich mit der Handfläche über die Stirn.>\n\nOh, nein. Das wird härter, als ich dachte. Diese Dinger haben keine Seriennummern oder ähnliches, wie?\n\nWann immer man einen Gnom braucht, ist keiner da…", sourceObjectiveStatus = "unverified-source-field" }
quests[12131] = { id = 12131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir haben die Macht", description = "Wir sind fast da, doch der Kriegsgolem will ohne Energie nicht funktionieren. Den Informationen nach, die ich in Argul sammeln konnte, bevor wir entdeckt wurden, erschaffen Runenschmied Durar und Runenschmied Kathorn jeweils eine Energiezelle.\n\nWir werden eine Energiezelle von jedem Runenschmied benötigen, um unseren Golem zum Laufen zu kriegen.\n\nDie Runenschmiede sollten in ihren Werkstätten auf der zentralen Ebene von Dun Argol zu finden sein.", sourceObjective = "Bringt Durars Energiezelle und Kathorns Energiezelle zu Raegar Brechbraue im Prospektorat.", progress = "Nun, habt Ihr diese Energiezellen dabei?", completion = "<Raegar nimmt Euch die Batterien ab.>\n\nAusgezeichnet! Wir sollten jetzt loslegen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12132] = { id = 12132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht zu Zerstören...", description = "Ihr habt zwar schon viel für mich getan, doch eine Sache bleibt noch.\n\nNeben der Euch bekannten Welt existiert eine zweite, die Welt der Schatten, die Welt meiner Peiniger - von wo aus sie mich beständig angreifen. Nun bin ich meinen eigenen Dämonen gegenüber machtlos, doch Ihr könntet ihrer Herrschaft des Schreckens ein Ende setzen. Ihr besitzt die Stärke, ich habe es mit meinen eigenen Augen gesehen.\n\nBegebt Euch in die Welt der Schatten und stellt Euch den Dämonen, die mich quälen!\n\nTut dies und ich werde den Folianten wie versprochen übersetzen.", sourceObjective = "Koltira Todesweber in Agmars Hammer in der Drachenöde möchte, dass Ihr die Welt der Schatten betretet und 6 schattenhafte Peiniger besiegt.\n\nSprecht mit Koltira Todesweber, solltet Ihr die Welt der Schatten wieder betreten müssen.", completion = "Die Macht, die ich besitze hat ihren Preis, {name}. Viele Ritter, ob des Lichts oder der Dunkelheit, ließen in der letzten Schlacht bei der Kapelle des hoffnungsvollen Lichts ihr Leben. Die Zukunftsaussichten sehen schlecht aus, doch zumindest weiß ich jetzt, was mich erwartet. Der Lichkönig wird mich nie gänzlich aus seinem Griff entlassen und für das allein muss er sterben!", sourceObjectiveStatus = "unverified-source-field" }
quests[12133] = { id = 12133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zermatsch den Kürbis", description = "Diese große Kürbislaterne befindet sich im Zentrum des Dorfes. Ihre Augen betrachten jeden, der sie ansieht, und verraten, dass eine dunkle Bedrohung dahinter lauert.\n\nWenn man den Kürbis zermatscht, wird ein altes, versengtes, heiliges Symbol offenbart.", sourceObjective = "Bring das versengte, heilige Symbol zur kostümierten Waisenmatrone.", progress = "Ja, {name}?", completion = "Ihr habt das in der Kürbislampe des kopflosen Reiters gefunden? Es ist ein altes Symbol des Lichts. Es muss einst dem Reiter gehört haben, bevor er verflucht und zu dem Monster wurde, das er heute ist. Habt Dank, {name}. Dieses Symbol gehört in Paladinhände. Ich werde sicherstellen, dass sie es erhalten.\n\nOh, und das hätte ich fast vergessen! Ihr habt einen stillen Bewunderer...\n\n Eines der Kinder wollte, dass Ihr dies erhaltet. Sie war zu schüchtern, es Euch selbst zu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12134] = { id = 12134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sashas Jagd", description = "Dieses Ding... dieser Fluch... der sich auf Silberwasser und Julheim auswirkt... er verwandelt mein Volk in Bestien.\n\nMein Vater hat versucht, sie zu warnen, doch stattdessen hörten sie alle lieber auf den Wolfskult.\n\nSie sind nun schon zu lange verwandelt - es ist Zeit, sie auszuschalten... um ihrer selbst willen.", sourceObjective = "Sasha möchte, dass Ihr nach Julheim geht und dort 12 Jäger von Julheim tötet.", completion = "Diese Monster zu töten, wird meinen Vater nicht zurückbringen... doch das spielt jetzt keine Rolle, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[12135] = { id = 12135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Lasset die Feuer kommen!\"", description = "Ihr müsst uns helfen! Der kopflose Reiter wird das Dorf jede Sekunde angreifen. Überall werden Feuer brennen! Die Kinder sind nicht mehr in Sicherheit!\n\nBitte, {name}, stellt Ihr Euch den Feuern des kopflosen Reiters entgegen? Wenn er kommt, müsst Ihr Euch der Brandwache anschließen. Schnappt Euch einen Eimer Wasser und löscht die Feuer damit. Ihr könnt den Eimer auch an einen Freund weitergeben, der näher an den Flammen steht. Wenn Ihr alle Feuer löscht, sind wir vielleicht schon gerettet!", sourceObjective = "Die kostümierte Matrone bittet um Eure Hilfe. Sie möchte, dass Ihr alle Feuer im Dorf löscht, nachdem der kopflose Reiter diese entzündet hat. Sprecht noch einmal mit der kostümierten Matrone, sobald alle Feuer erloschen sind.", completion = "Oh, vielen Dank! Möge das Licht Eure guten Taten segnen, gutherziger Herr. Der kopflose Reiter wirft zwar noch immer seinen bedrohlichen Schatten voraus, aber das Dorf ist jetzt erst einmal vor seinen Flammen sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[12136] = { id = 12136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der übersetzte Foliant", description = "Hier ist es, {name}. Ich habe alles, was auf den Seiten des Folianten geschrieben steht, übersetzt. In seinem Inneren befindet sich eine Liste, auf der die Namen aller Anhänger des Kults der Verdammten geschrieben stehen, die es auf diesem Kontinent gibt.\n\nIhr Netzwerk an Spionen und Agenten ist gelinde gesagt beeindruckend.\n\nLebet wohl, <mein Freund/meine Gute>. Möge das Buch Euch und Eurem Volke gut dienen.", sourceObjective = "Liefert den übersetzten fleischgebundenen Folianten bei Hauptmann Gort in Agmars Hammer ab.", progress = "Es wurde auch langsam Zeit! Wo seid Ihr nur gewesen?", completion = "<Gort nimmt Euch den Folianten ab und fängt an zu lesen.>\n\nWAS! Das kann nicht stimmen. Ein paar dieser Orcs kenne ich nun schon seit Jahren!\n\nLasst mich alleine, {name}. Ich habe viel Arbeit zu tun und viele Verräter hinzurichten.\n\nNehmt einen dieser Gegenstände als Entschädigung für den Ärger, der Euch bereitet wurde. Ihr habt der Horde heute einen großen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12137] = { id = 12137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ganz ruhig, Mann", description = "Is', wie die Prophezeiung sagte, Mann. <Ein/Eine:r> {race} kommt, um unsre Geister zur Ruhe zu bring'. Wir warten schon lange Zeit jetzt!\n\nDie Drakkari sind'n verlor'nes Volk geworden, grimmig und wild.\n\nAber es is' allein unsre Schuld, Mann. Dieser Ort muss geläutert werd'n und nur die Lebenden könn' das machen.\n\nRed' wieder mit mir, wenn du bereit bist, in deinen Körper zurückzukehren. Nimm dann den Schnee aus der Truhe hier neben mir un' bring meine Brüda in den Schlaf.\n\nBring ihre Überreste zu deinem Geisterführer, der weiß, was als nächstes zu tun is'.", sourceObjective = "Gan'jo möchte, dass Ihr den Schnee des ewigen Schlafes von seiner Kiste in den Ruinen von Drakil'jin nehmt.\n\nIhr müsst den Schnee bei den dortigen uralten Drakkarigeistern einsetzen und anschließend die Partikel der Drakkarigeister zurück zu Kraz in Harkors Lager bringen.", progress = "Habt Ihr Eure Aufgabe in der Krypta erledigt, {class}?", completion = "Gute Arbeit.\n\nBitte, setzt Euch und hört zu. Es gibt viele Dinge, die wir besprechen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12138] = { id = 12138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "... oder vielleicht auch nicht", description = "Man könnte meinen, dass die Jungs, die diese Energiezellen hergestellt haben, auch daran gedacht hätten, sie aufzuladen - aber nein, sie müssen die Sache komplizierter machen.\n\nNun gut, wir werden diese Zellen auf die schwierige Art und Weise aufladen. In ihnen ist zwar genug Energie gespeichert, um den Golem für kurze Zeit zum Laufen zu bringen, doch erwartet nicht von ihm, dass er auch gut im Kämpfen ist.\n\nKönnt Ihr die Blitzwachen sehen, die von den Eisenzwergen an der Grenze von Dun Argol postiert wurden? Nehmt den Golem mit, geht nah an sie heran, zerstört die Wachen und lasst den Golem ihre Energie absorbieren.", sourceObjective = "Ladet Euren Kriegsgolem mit der Energie von 10 Blitzwachen auf und kehrt anschließend zu Raegar Brechbraue im Prospektorat zurück.", completion = "Endlich ist er bereit. Ich hoffe nur, dass er so lange zusammenhält, bis die Arbeit getan ist. Wenn wir den in Dun Argol kommandierenden Than nicht ausschalten, dann wird Hauptmann Gryan eine böse Überraschung erleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12139] = { id = 12139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Lasset die Feuer kommen!\"", description = "Der kopflose Reiter wird das Dorf jede Sekunde angreifen. Überall werden Feuer brennen!\n\nBitte, {name}, stellt Ihr Euch den Feuern des kopflosen Reiters entgegen? Wenn er kommt, müsst Ihr Euch der Brandwache anschließen. Schnappt Euch einen Eimer Wasser und löscht die Feuer damit. Ihr könnt den Eimer auch an einen Freund weitergeben, der näher an den Flammen steht. Wenn Ihr alle Feuer löscht, sind wir vielleicht schon gerettet!", sourceObjective = "Die maskierte Matrone bittet um Eure Hilfe. Sie möchte, dass Ihr alle Feuer im Dorf löscht. Sprecht noch einmal mit der maskierten Matrone, sobald alle Feuer erloschen sind.", completion = "Die Feuer sind erloschen! Ihr wart mit Eurer Brandwache erfolgreich! Hah!\n\nDer Angriff des kopflosen Reiters ist fehlgeschlagen, aber solange er und sein Kopf nicht vernichtet werden, wird er wieder zurückkehren.\n\nLasst uns bis dahin Trost in der Sicherheit finden, die Ihr uns und unseren Kindern beschert habt. Es war mir eine Ehre, heute Zeuge Eurer Taten zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[12140] = { id = 12140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hoch auf Roanauk!", description = "Wie die Tauren, die Verlassenen, Trolle und Blutelfen, so brauchen auch die Taunka einen Anführer, der von ihrem eigenen Blute abstammt. Der eine, den Ihr aus Eisnebel befreit habt - Roanauk -, wird dieser Anführer sein.\n\n<Oberanführer Agmar überreicht Euch ein Pergament.>\n\nIch gebe Euch etwas, das Ihr schon kennt - auf ihm steht der Blutschwur der Horde geschrieben.\n\nBringt das Pergament zu Roanauk Eisnebel und nehmt ihn als Anführer der Taunka in die Horde auf.\n\nLassen wir ihn nicht warten.\n\n<Agmar nickt Euch zu.>", sourceObjective = "Geht nach Agmars Hammer, sucht Roanauk Eisnebel auf und macht ihn zu einem Mitglied und Anführer der Hordestreitkräfte.\n\nKehrt anschließend mit dem Blutschwur der Horde zu Oberanführer Agmar zurück, sobald Ihr diese Aufgabe abgeschlossen habt.", completion = "Ein so mächtiger Schamane wird uns an der Pforte des Zorns sicherlich den Sieg bescheren!", sourceObjectiveStatus = "unverified-source-field" }
quests[12141] = { id = 12141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine diplomatische Mission", description = "Ich sehe, dass Ihr sehr begierig drauf seid, zu helfen, {name}. Ihr seid nicht den ganzen Weg nach Nordend gereist, damit Ihr Euch in einer Stadt verkriecht! Ich hab genau die richtige Aufgabe für Euch... etwas, das Euch weit weg von hier bringt.\n\nWir haben lange versucht, uns das Wohlwollen der in Nordend heimischen Tuskarr zu sichern. Neulich kam ein junger Tuskarr zu uns und ersuchte Hilfe, etwas, womit wir zu dieser Zeit nicht dienen konnten.\n\nJetzt, da Ihr da seid, könnt Ihr ihm vielleicht zur Hand gehen. Sucht nach Karuk in der Nähe des Strandes der Peitschennarbe südwestlich von hier und schaut, was Ihr für ihn tun könnt.", sourceObjective = "Sprecht mit Karuk am Strand der Peitschennarbe südwestlich der Valianzfeste.", completion = "Ihr seid gekommen, um mir zu helfen? Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12142] = { id = 12142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seuchenkontrolle", description = "Uhh! Als wir uns um den letzten Drachen gekümmert haben, hat einer dieser kleinen Schneeboldwichte unser Lager verwüstet. Jedes Mal, wenn wir ihnen den Rücken kehren, bereiten sie uns irgendwelchen Ärger... Ich hab's satt!\n\nDie Schneebolde gen Süden verstecken sich hinter den örtlichen Magnatauren - hängen an ihren Rockzipfeln sozusagen. Geht und schlachtet sie nieder.\n\nUnd falls die Magnatauren für ihre Sklaven eintreten sollten, dann tötet sie auch.", sourceObjective = "Duane bei der Front der 7. Legion möchte, dass Ihr 10 Schneebolde der Schneeebene und 3 Magnatauren der Drachenöde in den Lagern um den Wyrmruhtempel herum tötet.", progress = "Habt Ihr diese Schädlinge beseitigt?", completion = "Ein Glück, dass wir sie los sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[12143] = { id = 12143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd durch die Schluchten", description = "Ich kann es nicht fassen! Gerade wollte noch so eine Bande von diesem Gezücht mit unseren Vorräten abhauen. Sie machen sich in Richtung der nördlichen Schlucht davon. Verfolgt sie und kümmert Euch um ihren Anführer!", sourceObjective = "Duane möchte, dass Ihr die Schneebolde im Canyon nordöstlich der Front der 7. Legion verfolgt und Euch anschließend um deren Anführer kümmert.", completion = "Kühlhauer, wie? Ich hab' den Namen schon mal gehört. Richtig gute Arbeit, {class}. Hoffentlich können wir jetzt wieder unsere Aufmerksamkeit den Drachen zuwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12144] = { id = 12144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seuchenkontrolle", description = "Ai, Mann! Ein von dene kleine rattige Schneebolds hat bei die letzte Drachenangriff unsere Lager auf'n Kopp gestellt, Mann. Die sin' uns imma auf'n Fersen, sobald wir ihn' den Rücken zudreh'n. Un' ich hab genug! \n\nIm Osten vastecke'n die sich unter die Röcke von 'nen paar Magnataur'n, die hia leben. Geht un tut sie abschlacht'n. Un' wenn die Magnataur'n sich da für ihre Sklaven reinhäng'n tun, tötet sie auch, Mann.", sourceObjective = "Kontokanis in Drachensturz möchte, dass Ihr 10 Schneebolde der Schneeebene und 3 Magnatauren der Drachenöde in den Lagern um den Wyrmruhtempel herum tötet.", completion = "Nich' schad' um die, Mann.", sourceObjectiveStatus = "unverified-source-field" }
quests[12145] = { id = 12145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd durch die Schluchten", description = "Ich kann das nich' glauben! Noch 'ne Bande von dem Gezücht wollt' grad mit mea von unsere Vorräte abhau'n! Die flitzen grad runta in die Schlucht, lauft ihn' nach un' kümmat Euch um den ihr Chef!", sourceObjective = "Kontokanis möchte, dass Ihr die Schneebolde in der Schlucht südlich von Drachensturz verfolgt und anschließend ihren Anführer beseitigt.", completion = "Eisfaust, ai? Den Namen hab ich schon mal gehört. Das war mal gute Arbeit, Mann. Jetz' können wir Dunk'lspea uns hoff'ntlich wieda um die Drach'n kümman.", sourceObjectiveStatus = "unverified-source-field" }
quests[12146] = { id = 12146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beunruhigende Hinweise", description = "Die untere Seite des Horns schmückt ein Siegel, das einen Hammer und einen Blitz zeigt. Irgendetwas an diesem Horn wirkt bei einem Magnataur vollkommen fehl am Platze.\n\nGeht nach Süden den Pfad der Titanen entlang, bringt das Horn zum Wyrmruhtempel und sucht jemanden auf, der an diesen bedrohlichen Hinweisen Interesse haben könnte.", sourceObjective = "Bringt das geschmückte Kriegshorn zum Wyrmruhtempel und sucht dort nach jemandem, der die drohende Gefahr einschätzen kann.", progress = "Ja, {race}?", completion = "Es ist für einen Magnatauren in der Tat seltsam, so einen Gegenstand bei sich zu tragen... und sehr beunruhigend. Ich bin froh, dass Ihr es mir gezeigt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12147] = { id = 12147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beunruhigende Hinweise", description = "Die untere Seite des Horns schmückt ein Siegel, das einen Hammer und einen Blitz zeigt. Irgendetwas an diesem Horn wirkt bei einem Magnataur vollkommen fehl am Platze.\n\nGeht nach Osten, durchquert die Dracheneiswüste und bringt das Horn zum Wyrmruhtempel. Sucht dort jemanden auf, der an diesen bedrohlichen Hinweisen Interesse haben könnte.", sourceObjective = "Bringt das geschmückte Kriegshorn zum Wyrmruhtempel und sucht dort nach jemandem, der die drohende Gefahr einschätzen kann.", progress = "Ja, {race}?", completion = "Es ist für einen Magnataur in der Tat seltsam, so einen Gegenstand bei sich zu tragen... und sehr beunruhigend. Ich bin froh, dass Ihr es mir gezeigt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12148] = { id = 12148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzigartig", description = "So ein seltsames Siegel bei einem Magnatauren... das lässt auf ungewöhnlich viel Organisation schließen.\n\nEs kommt nur selten vor, dass Magnatauren ihr aggressives Naturell beiseitelegen, um miteinander zu kooperieren. Ich vermute, dass sie ihre Aufmerksamkeit darauf gerichtet haben, einen Überfall auf eine große Siedlung zu starten.\n\nIch bezweifle sehr, dass dieses Horn einzigartig ist - Ihr müsst mich also vom Gegenteil überzeugen. In der Schlucht gen Nordwesten des Azurdrachenschreins befindet sich Knochenkracher. Geht, fordert ihn heraus und bringt mir irgendwelche Informationen, die meine Befürchtungen bestätigen könnten.", sourceObjective = "Findet und tötet Knochenkracher in der Nähe der Schlucht nordwestlich des Azurdrachenschreins. Bringt jegliche Informationen zurück zu Aurastrasza im Wyrmruhtempel.", progress = "Habt Ihr irgendwas herausfinden können?", completion = "Es ist also wahr? Sie hätten sich für solch einen Angriff keinen besseren Zeitpunkt aussuchen können... zwischen der Geißel und dem blauen Drachenschwarm - es ist unwahrscheinlich, dass es sonst noch irgendjemand bemerkt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[12149] = { id = 12149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die mächtigen Magnatauren", description = "Magnatauren sind furchtbar gewalttätige Kreaturen... das ist der eigentliche Grund dafür, weshalb man nie größere Ansammlungen von ihnen zu Gesicht bekommt, ohne dass sie sich gerade gegenseitig abschlachten. Irgendwo gibt es einen neuen mächtigen Anführer unter ihnen. Wir müssen ihm nachstellen, wenn wir dieser Bedrohung ein Ende setzen wollen.\n\nIch werde mich einmal umhören und möchte, dass Ihr sie in der Zwischenzeit so gut wie möglich ablenkt.\n\nÖstlich von hier wurden 3 Fackeln aufgestellt, in deren Nähe sich 3 dominante Magnatauren befinden. Schaltet sie aus und beschafft uns ein wenig Zeit, damit wir diesen Anführer zur Strecke bringen können.", sourceObjective = "Bringt Blutschmaus, Eisberster und Drachenblut, die sich östlich des Wyrmruhtempels befinden, zur Strecke.\n\nBlutschmaus wohnt im südöstlichen Bereich der Dracheneiswüste, gleich nördlich des Smaragddrachenschreins. Eisberster patrouilliert an der nördlichen Grenze des Spiegels der Morgenröte. Drachenblut wandert am Fuße der Klippen westlich des Bronzedrachenschreins umher.\n\nKehrt zu Aurastrasza im Wyrmruhtempel zurück, sobald Ihr die Magnatauren erschlagen habt.", completion = "Ausgezeichnete Arbeit. Niemand konnte mir zwar sagen, wer dieser Anführer nun sein könnte, doch ich habe den Namen von jemandem herausfinden können, der ihn uns verraten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[12150] = { id = 12150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der zurückgezogene Runenmeister", description = "Dregmar Runenbrand ist ein magnataurischer Runenmeister... eine Seltenheit unter seinesgleichen. Er verbringt zwar die meiste Zeit allein, ist jedoch dafür bekannt, schon seit einiger Zeit mit den mächtigeren und einflussreicheren Magnatauren der Drachenöde zu verkehren. Er wird schon wissen, wer dieser neue Anführer sein soll.\n\nEs ist eher unwahrscheinlich, dass wir von ihm in irgendeiner Form Hilfe in Bezug auf die wachsende Bedrohung durch die Geißel und den blauen Drachenschwarm erwarten können, also möchte ich, dass Ihr alles Notwendige unternehmt, um die Informationen von Dregmar zu beschaffen.\n\nMir wurde gesagt, dass er sich auf den Klippen am Spiegel der Morgenröte aufhält.", sourceObjective = "Sucht Dregmar Runenbrand auf. Er befindet sich in der Nähe seiner Höhle auf dem Weg zu den Klippen am Spiegel der Morgenröte. Fordert ihn heraus und tut, was notwendig ist, um den Namen des magnataurischen Anführers herauszufinden. Kehrt zu Aurastrasza im Wyrmruhtempel zurück, sobald Ihr die Information erhalten habt.", completion = "Grom'thar der Donnerbringer. Gut. Lasst uns also dieser Magnataurenbedrohung hier und jetzt ein Ende setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12151] = { id = 12151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rücksichtsloser Kriegsherr", description = "Es gibt keinen Grund daran zu zweifeln, dass Dregmars Worte wahr sind. Ob nun Grom'thar Euch unterliegt oder Ihr von ihm besiegt werdet... Es macht keinen Unterschied: Er wird sich seine Hände reinwaschen können.\n\nFolgt seinen Anweisungen... nehmt das Horn, das Ihr mir zuvor gebracht habt, geht zum Fackelring südlich des Azurdrachenschreins und stoßt zum Zeichen der Herausforderung hinein.\n\nTötet anschließend Grom'thar den Donnerbringer und bringt mir seinen Kopf.", sourceObjective = "Geht zum Fackelring südlich des Azurdrachenschreins und stoßt in das geschmückte Kriegshorn. Besiegt Grom'thar den Donnerbringer und bringt seinen Kopf zurück zu Aurastrasza im Wyrmruhtempel.", progress = "Habt Ihr diese Gefahr endgültig aus der Welt schaffen können?", completion = "Wirklich beeindruckend.\n\nNun da Grom'thar der Donnerbringer nicht mehr ist, können wir die restlichen Magnatauren sich gegenseitig bekämpfen lassen und unsere Aufmerksamkeit größeren Gefahren zuwenden.\n\nBeeindruckende Arbeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12152] = { id = 12152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jin'arraks Ende", description = "Es ist gut, Euch wieder unter den Lebenden begrüßen zu dürfen. Viele von denen, die auf dem Weg der Toten wandeln, kehren nicht zurück, um davon zu berichten.\n\nWährend Ihr weg wart, hatte Kraz eine Vision, die ihm offenbarte, was noch zu tun ist.\n\nIn der Gruft liegt noch irgendwo eine heilige Opfergabe. Nehmt diesen Seelenstaub, der aus den von Euch gesammelten Überresten gewonnen wurde und benutzt ihn auf der Opfergabe.\n\nDie mit dem Staub bedeckte Opfergabe wird dem verderbten Kriegsherren ein Ende bereiten und viele gepeinigte Seelen erlösen.\n\nMögen Euch die Geister Euch in Euren Handlungen leiten, {name}.", sourceObjective = "Kraz in Harkors Lager möchte, dass Ihr die heilige Drakkariopfergabe aus den Ruinen von Drakil'jin holt und den Drakkariseelenstaub darauf benutzt. Benutzt die beseelte Drakkariopfergabe bei den Gongs außerhalb der Ruinen von Drakil'jin.", completion = "Es ist vollbracht.\n\nEure Selbstlosigkeit hat vielen Seelen ewigen Frieden gebracht und Äonen der Qual beendet.\n\nMöge diese Tat Eure eigene Seele erleuchten und die Bürden, die Ihr tragt, leichter machen, denn ich sehe, dass Ihr noch viele Gefahren bestehen müsst.\n\nLebt wohl, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12153] = { id = 12153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Eisenthan und sein Amboss", description = "Nun, da Ihr Euren Kriegsgolem aufgeladen habt, werden wir all diese Energie einer guten Sache zuführen. Aktiviert den Golem innerhalb von Dun Argol, um ihn zu kontrollieren.\n\nWir haben Informationen, dass Dun Argols Anführer, Eisenthan Zornhammer, von seinem Leibwächter rund um die Uhr beschützt wird.\n\nDieser Leibwächter ist das Konstrukt, mit dem er reist. Er wird der Amboss genannt. Setzt das Konstrukt außer Gefecht und sein Schutz wird vernichtet.\n\nDer Than befindet sich in dem Gebäude an der obersten Stelle Dun Argols und überwacht vom untersten Geschoss aus die Produktion.", sourceObjective = "Setzt die Fähigkeiten Eures Kriegsgolems ein, besiegt den Eisenthan Zornhammer und kehrt dann zu Raegar Brechbraue im Prospektorat zurück.", completion = "Es hat funktioniert?\n\n<Raegar räuspert sich.>\n\nIch meine… Natürlich hat es funktioniert! Das ist unglaublich!\n\nIn Zukunft werden Initianden der Forscherliga die Geschichte hören, wie Raegar Brechbraue, {name} und ein Blechkasten von einem Golem den Than von Dun Argol besiegten!", sourceObjectiveStatus = "unverified-source-field" }
quests[12154] = { id = 12154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stromausfall", description = "In der großen Halle an der Spitze von Dun Argol befindet sich die Energieversorgung für das ganze Gebiet. Wenn Ihr den Kraftkern zerstören könnt, wird es Dun Argol für einige Zeit lahm legen.\n\nKeine Energie bedeutet keine Golems, keine Wachposten und keine Blitzwaffen mehr.\n\nAls wir hier heraufgeschickt wurden, sagte man uns, dieser Sprengstoff sei für Ausgrabungen gedacht, aber dank Eisenthan Zornhammer musste die Forschung ja eingestellt werden. Wir können ihn vielleicht dennoch verwenden - er ist das einzig verfügbare Mittel, mit dem wir den Kraftkern zerstören können.", sourceObjective = "Benutzt Raegars Sprengstoff, um den Runenkraftkern in Dun Argol zu zerstören, und erstattet anschließen Bericht bei Raegar Brechbraue im Prospektorat.", completion = "<Raegar nickt anerkennend.>\n\nIch kann's nicht mit ansehen, wie Sprengstoff auf den Müll wandert, und so erteilt er unseren Feinden sicher einen herben Rückschlag.", sourceObjectiveStatus = "unverified-source-field" }
quests[12155] = { id = 12155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zermatsch den Kürbis", description = "Diese große Kürbislaterne befindet sich im Zentrum des Dorfes. Ihre Augen betrachten jeden, der sie ansieht, und verraten, dass eine dunkle Bedrohung dahinter lauert.\n\nWenn man den Kürbis zermatscht, wird ein altes, versengtes, heiliges Symbol offenbart.", sourceObjective = "Bring das versengte, heilige Symbol zur maskierten Waisenmatrone.", progress = "Ja, {name}?", completion = "Ihr habt das in der Kürbislampe des kopflosen Reiters gefunden? Es ist ein altes Symbol des Lichts. Es muss einst dem Reiter gehört haben, bevor er verflucht und zu dem Monster wurde, das er heute ist. Habt Dank, {name}. Dieses Symbol gehört in Paladinhände. Ich werde sicherstellen, dass sie es erhalten.\n\nOh, und das hätte ich fast vergessen! Ihr habt einen stillen Bewunderer...\n\n Eines der Kinder wollte, dass Ihr dies erhaltet. Sie war zu schüchtern, es Euch selbst zu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12156] = { id = 12156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ABGELEHNT", description = "Ich hätte eigentlich vor ungefähr einer Stunde in Richtung Nordwesten, nach Silberwasser, aufbrechen sollen. Meine Militäreskorte scheint sich zu verspäten.\n\nIch werde nicht zulassen, dass diese diplomatische Mission in Verzug gerät, nur weil ein neuer Rekrut verschlafen hat.\n\nWir verhandeln gerade ein Abkommen mit den Einheimischen und Pünktlichkeit ist von größter Bedeutung. Was meint Ihr? Wenn Ihr mich begleitet, so werdet Ihr fürstlich entlohnt werden für Eure Mühen.", sourceObjective = "Eskortiert den Gesandten der Allianz ins Dorf Silberwasser. Erstattet Leutnant Dumont bei der Ammertannhütte Bericht, sobald Ihr Eure Aufgabe abgeschlossen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12157] = { id = 12157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Kurier", description = "Wir können uns glücklich schätzen, es bis hierher geschafft zu haben, {name}. Wir wurden von der Geißel aus dem Hinterhalt angegriffen, als wir anlandeten.\n\nWie sich herausstellte, war einer meiner Männer ein Spion des Kults der Verdammten. Thassarian scheint mehr Beweise über die Infiltration durch die Kultisten zu haben. So wie es aussieht, zieht sich das ganze bis in die Spitze.\n\nIch habe einen meiner besten Kuriere auf den Weg zu unserem Außenposten in der westlichen Drachenöde geschickt, doch er ist noch nicht zurückgekehrt. Werdet Ihr in die Drachenöde reisen und nach ihm suchen? Kurier Lanson ist sein Name.", sourceObjective = "Sprecht mit Kurier Lanson in Sternenruh in der Drachenöde.", completion = "Als ich die Brücke überquerte, die in die Drachenöde führte, wurde ich aus dem Hinterhalt von einer Gruppe Anub'ar angegriffen! Ich war umzingelt! Diese Scheusale wussten, dass ich kommen würde. Ich konnte gerade noch meine Haut retten. Diese Liste, die ich in Händen halte, muss nach Wintergarde gebracht werden, doch meine Wunden sind zu schwer, als dass ich die Reise schaffen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[12158] = { id = 12158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hohlsteinmine", description = "Ich wollte eigentlich ein paar unserer Jungs losschicken, um nach der Hohlsteinmine zu sehen. Hatten aber noch keine Gelegenheit - alle Hände voll zu tun mit der Horde im Westen und den Eisenzwergen im Osten.\n\nWenn allerdings Dumont Euch gesandt hat, kann ich Euch wenigstens in die richtige Richtung schicken.\n\nIhr findet den Eingang zur Mine nicht weit von hier im Nordwesten. Versucht einzuschätzen, ob es sich lohnt, dort zu operieren. Wir könnten die zusätzlichen Ressourcen gut gebrauchen, solange unsere Mine in Fernhain geschlossen ist.", sourceObjective = "Sucht nach Hinweisen in der Hohlsteinmine, nordwestlich vom Lager der Westfallbrigade.", completion = "Ihr seid gekommen, um mir zu helfen, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[12159] = { id = 12159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelenunfrieden", description = "<Petrov wirkt zutiefst verstört, atmet schwer und lässt seinen Blick nervös über die Mine schweifen.>\n\nMeine Kameraden... wir müssen ihren Seelen Frieden gewähren! Ich töte sie und töte sie, aber... sie kommen einfach zurück!\n\nErst hatte ich ja eine Idee, aber ich denke nicht, dass ich den Mut habe, sie selbst auszuführen.\n\nVielleicht könnt Ihr das für mich tun? Nehmt diese Laterne und verbrennt mit ihrem Öl die Leichen, damit sie nicht wieder aufstehen.\n\nIch beantworte Eure Fragen später. Helft erst meinen Freunden!", sourceObjective = "Petrov bei der Hohlsteinmine möchte, dass Ihr mit der Minenarbeiterlaterne die Leichen von 8 Minenarbeitern der Hohlsteinmine verbrennt.", progress = "Habt Ihr meinen Freunden Frieden gewährt, {name}?", completion = "Ruhet in Frieden, Freunde! Seid unbesorgt - ich erzähle allen, dass wir niemals aufgegeben haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[12160] = { id = 12160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Name aus der Vergangenheit", description = "Es hat funktioniert! Es hat funktioniert! Meine Kameraden können endlich ihre wohlverdiente Ruhe genießen. Wir, die Bergleute von der Hohlsteinmine, bringen immer unsere Arbeit zu Ende - wir geben niemals auf!\n\nAus diesem Grund hat Arugal an uns auch ein Exempel statuiert. Wir wollten uns nicht fügen, müsst Ihr wissen. Wir wollten uns nicht seinem Wolfskult anschließen!", sourceObjective = "Kehrt zu Hauptmann Gryan Starkmantel im Lager der Westfallbrigade zurück.", completion = "Verflucht soll unser Glück sein. Wir finden die einzige Mine auf dieser Seite der Hügel, die noch intakt ist, und sie ist voller Diener der Geißel.\n\nNichts für ungut, mein Freund. Doch es hört sich so an, als sei der Überlebende, den Ihr gefunden habt, durch den Verlust seiner Freunde ein wenig verstört. Arugal ist schon seit Jahren tot... Ich habe einst sogar sein Grab gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12161] = { id = 12161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruuna die Blinde", description = "He, Ihr. Ich habe zufällig gehört, was Ihr da dem Hauptmann erzählt habt und wollte Euch nur sagen… Die Dinge sind nicht ganz so einfach in Nordend.\n\nNur weil jemand tot ist, heißt das nicht, dass er ganz verschwindet.\n\nSüdwestlich von hier, in der Nähe des Vordrassilpasses, lebt eine blinde Frau, die unter dem Namen Ruuna die Blinde bekannt ist. Man sagt, dass sie mit den Toten spricht und Visionen von der Vergangenheit und der Zukunft hat.\n\nIch habe nicht alles von Eurer Geschichte mitbekommen, aber es hört sich an, als könnte sie für Euch von Interesse sein.", sourceObjective = "Sprecht mit Ruuna der Blinden in Ruunas Lager in der Nähe des Vordrassilpasses.", completion = "Euch verlangt es nach Wissen, das Ihr nicht selbst erlangen könnt, deswegen seid Ihr zu mir gekommen. Doch muss ich Euch warnen, Fremder, womöglich wird es Euch nicht gefallen, was ich zu sagen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[12162] = { id = 12162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Julheim" }
quests[12163] = { id = 12163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Böse lauert am Meeresgrund" }
quests[12164] = { id = 12164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stunde des Worg", description = "Es ist wohl Zeit, {name}. Arugal muss besiegt werden.\n\nNehmt ein paar Leute mit, denen Ihr vertrauen könnt, und geht zur Blutmondinsel gleich hier im Osten vor der Küste.\n\nWir werden schnell zuschlagen. Schaltet Arugals Leutnants aus - ich komme dann zu Euch, wenn es Zeit ist, das Monster höchstpersönlich zu erlegen.", sourceObjective = "Sasha im Handelsposten Weißkiefer möchte, dass Ihr zur Blutmondinsel geht und Selas, Varlam, Blutschlund und den Schatten von Arugal tötet.", completion = "Wir haben ihn gut erwischt, {name}. Doch nicht gut genug.\n\nEine Sache ist jedoch sicher... In dieser Gegend werden wir ihn nicht mehr zu Gesicht bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12165] = { id = 12165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein faszinierender Plan", description = "Ausgrabungsleiter Rokar hat sich entschieden, uns zu helfen. Er hat einen Plan erarbeitet, die Stärke der Eisenzwerge gegen sie zu wenden.\n\nIch muss zugeben, dass unser 'Freund' einsichtiger ist, als ich ihm zugetraut hätte. Er hat Recht, wenn er sagt, dass wir zu wenige sind, um einen direkten Angriff wagen zu können.\n\nReist nach Dun Argol, in die verschneiten Regionen im Südosten, und stehlt alle Blaupausenteile für ihre Kriegsgolems von den Runenschmieden dort. Bringt die vollständige Blaupause zu Rokar und wir werden sehen, ob sein Plan Wert hat.", sourceObjective = "Bringt die vollständige Blaupause für die Kriegsgolems zu Ausgrabungsleiter Rokar in Camp Oneqwah.", progress = "Habt... habt Ihr die Blaupausen, die ich brauche?", completion = "Also will Tormak den Plan in die Tat umsetzen? Ich vermute, er hätte Euch nicht geschickt, wenn er das nicht wollte.\n\nOh Mann… wie kriege ich bei all dem Druck nur heraus, wie das Ganze zusammengesetzt werden muss?", sourceObjectiveStatus = "unverified-source-field" }
quests[12166] = { id = 12166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das flüssige Feuer Elunes", description = "Werdet Ihr mir beistehen, {race}?\n\nDie Geißel ist weiter nach Norden vorgedrungen, nach Eisnebel. Wohin auch immer sie ziehen, sie verbreiten ihr Übel und alle Kreaturen leiden.\n\nNehmt diese Phiole, sie ist mit dem flüssigen Feuer Elunes aus dem Mondbrunnen gefüllt. Bitte, nutzt dieses Elixier und läutert die Kadaver der toten Wildtiere, die ihr findet.", sourceObjective = "Aufseherin Jodi Mondweise in Sternenruh hat Euch gebeten, das flüssige Feuer Elunes zu nutzen, um die Kadaver von 6 verseuchten Elchen und 6 tollwütigen Grizzlys zu läutern.", completion = "Wir haben für die Kreaturen dieses Landes getan, was möglich war. Jetzt müssen wir direkte Schritte gegen jene unternehmen, die das alles verursacht haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[12167] = { id = 12167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet die Kultisten", description = "Die Kultisten der Anub'ar sind indirekt für die Verseuchung der Tiere hier verantwortlich und wir müssen dem ein Ende setzen!\n\nDie Dämpfe, die aus den Anzügen der Kultisten quellen durchsickern alles, dem sie sich nähern, vergiften und verderben ihre Umgebung.\n\nIhr müsst nach Eisnebel im Norden gehen und sie töten. Bringt mir all die Anzüge, die Euren Angriff unbeschadet überstehen, und ich werde mich darum kümmern, dass diese fachgerecht entsorgt werden.", sourceObjective = "Sammelt für Aufseherin Jodi Mondweise 5 funktionstüchtige Kultistenanzüge und bringt sie zu ihr nach Sternenruh.", progress = "Diese Kultisten sind eine der Geißeln der Schöpfung!", completion = "Gut gemacht.\n\nIch werde diese widerwärtigen Kleider im Mondbrunnen waschen und sie mit der Macht der Mondgöttin vernichten!", sourceObjectiveStatus = "unverified-source-field" }
quests[12168] = { id = 12168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zangus Ehrengabe", description = "Eine Inschrift auf der Rückseite der Ehrengabe gibt kund:\n\n\"Gewidmet meinem Lieblingsschüler,\n\nSolltest du weiterhin derart vielversprechende Talente zeigen, werde ich dich Wunder lehren, die deine kühnsten Träume übersteigen.\n\nSolltest du nicht, werde ich deine Entsorgung in Auftrag geben.\n\nMit den besten Wünschen,\n\nHochkultist Zangus\"\n\nOhne Zweifel wird die Aufseherin in Sternenruh die Ehrengabe sehen wollen.", sourceObjective = "Bringt Zangus Ehrengabe zu Aufseherin Jodi Mondweise in Sternenruh.", progress = "Etwas Verderbtes ist nah, ich spüre es.\n\nIhr tragt dieses Unheil mit Euch! Was ist es, {name}?", completion = "So, der Anführer der Kultisten hat sich also selbst entlarvt. Wir haben einen Namen.\n\nEitelkeit und Stolz werden sein Untergang sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[12169] = { id = 12169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hochkultist", description = "Ich habe bereits von Zangus geträumt, doch ohne den Kontext, den Ihr mir hier liefert, wusste ich nicht, was es zu bedeuten hat. Ihr habt Klarheit in die Vision gebracht, mit der mich die Göttin segnete und ich weiß nun, dass wir ihn im Norden, in der Grube von Narjun finden werden.\n\nIhr kennt unser Ziel, {name}. Wenn wir dem Leiden des Landes ein Ende setzen wollen, muss der Hochkultist sterben!", sourceObjective = "Aufseherin Jodi Mondweise in Sternenruh hat Euch gebeten, Hochkultist Zangus zu töten.", progress = "Ich spüre, dass Hochkultist Zangus noch am Leben ist.\n\nIst etwas nicht in Ordnung, {name}? Vielleicht müsst Ihr Euch erst ausruhen?", completion = "Nun, da der Hochkultist vernichtet ist, kann der Rest seiner Streitkräfte von diesem Landstrich gefegt werden und die Tiere werden sich erholen.\n\nVielen Dank, {name}. Möge die Göttin Eure Pfade erhellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12170] = { id = 12170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keilerei in Schwarzwasser", description = "Kurz nachdem wir angekommen sind, hat die Venture Company ihren Betrieb eingestellt. Sie hatten ganz klar Angst davor, was wir mit Raffzähnen wie ihnen machen würden.\n\nNun da sie weg sind, sind ihre Holzfällerlager verlassen. Unsere Kriegsmaschinerie ist ein hungriges Biest... Ohne unsere Vorräte aufzustocken, werden wir es nicht zur Eiskrone schaffen.\n\nLeider scheint die Allianz denselben Gedanken zu haben und wir müssen sicherstellen, dass wir diejenigen sind, die obsiegen. Macht Euch auf den Weg zum Holzfällerlager und helft uns, den Allianzabschaum zu bekämpfen.", sourceObjective = "Räuberhauptmann Kronn möchte, dass Ihr 10 Einheiten oder Spieler der Allianz beim Holzfällerlager von Schwarzwasser tötet.", progress = "Habt Ihr die Hunde der Allianz umgelegt? Wir müssen siegen!", completion = "Gut gemacht, {name}. Wir haben zwar noch nicht die volle Kontrolle über das Holzfällerlager, aber dank Euch sind wir dem Ziel, die Allianzwürmer zu zertreten, einen Schritt näher gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12171] = { id = 12171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Verrätern und Verrat", description = "Die Liste, die in meinem Besitz ist, muss zu Oberkommandant Halford Wyrmbann gebracht werden. Er befehligt die 7. Legion, die in der Feste Wintergarde an der östlichen Grenze der Drachenöde.\n\nFalls einige der Verräter auf dieser Liste in Wintergarde stationiert sind... könnte das katastrophale Folgen haben.\n\nBeeilung, {name}. Zeigt Palena Silberwolke hier in Sternenruh das Dokument und erklärt ihr Eure Mission. Sie wird Euch auf ihrem schnellsten Hippogryph zur Feste Wintergarde schicken!", sourceObjective = "Zeigt Palena Silberwolke in Sternenruh das Schreiben der Allianz.", progress = "Hallo, {race}.", completion = "<Palena liest die Notiz.>\n\nIhr werdet meinen schnellsten Hippogryph nehmen, {race}! Diese Informationen müssen unverzüglich Oberkommandant Wyrmbann übergeben werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[12172] = { id = 12172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abstimmung auf Dalaran", description = "Willkommen, <Magier/Magierin>.\n\nIhr müsst Euch mittlerweile schon gefragt haben, wo Dalaran ist und wie man dorthin kommt. Nun, ich werde Euch helfen.\n\nDoch bevor ich Euch beibringen kann, wie man sich zu unserer glorreichen Stadt hinteleportiert, müsst Ihr Euch auf Nordends Leylinien abstimmen - sonst würdet Ihr nämlich vernichtet werden.\n\nHier, nehmt diesen Abstimmungskristall und verwendet ihn in der Grube unter der Sognadel in den Mondruhgärten gen Westen; dann werdet Ihr bereit sein, den Zauberspruch zu lernen.", sourceObjective = "Das Abbild der Erzmagierin Modera in Sternenruh möchte, dass Ihr Euch auf Nordends Leylinien abstimmt.", completion = "Nun gut. Wenn Ihr bereit seid, dann bin ich es auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[12173] = { id = 12173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abstimmung auf Dalaran", description = "Grüße, <Magier/Magierin>.\n\nIhr müsst Euch mittlerweile schon gefragt haben, wo Dalaran ist und wie man dorthin kommt. Nun, ich kann Euch in der Sache helfen, wenn Ihr einen einfachen Test überstehen könnt.\n\nDoch bevor ich Euch beibringe, wie man sich zu unserer glorreichen Stadt teleportieren kann, müsst Ihr Euch auf Nordends Leylinien abstimmen - andernfalls würdet Ihr Euch nämlich selbst vernichten!\n\nHier, nehmt diesen Abstimmungskristall und verwendet ihn in der Grube unter der Sognadel in den Mondruhgärten gen Südwesten; dann werdet Ihr bereit sein, Euch meine Lehre anzueignen.", sourceObjective = "Das Abbild des Erzmagiers Aethas Sonnenhäscher in Agmars Hammer möchte, dass Ihr Euch auf Nordends Leylinien abstimmt.", completion = "Also gut. Wenn Ihr denkt, dass Ihr bereit seid, dann lasst uns nicht viel mehr von meiner Zeit verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12174] = { id = 12174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oberkommandant Halford Wyrmbann", description = "<Palena gibt Euch das Schreiben zurück.>\n\nSchneesturm wird Euch zur Feste Wintergarde bringen, {name}. Ich versichere Euch, dass das der schnellste Ritt wird, den Ihr je unternommen habt. Geht jetzt!", sourceObjective = "Überbringt Oberkommandant Halford Wyrmbann das Schreiben der Allianz. Er befindet sich in der Feste Wintergarde im Osten der Drachenöde.", progress = "Was habt Ihr da, Soldat?", completion = "<Der Oberkommandant liest das Schreiben durch und knüllt es dann zusammen.>\n\nWisst Ihr, wo die Leute auf dieser Liste jetzt sind? Seht mal nach draußen, neben dem Eingangstor. Sie hängen von den Bögen.\n\nGhulköder...", sourceObjectiveStatus = "unverified-source-field" }
quests[12175] = { id = 12175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Graue Worgbälge", description = "Lass mich dir was sagen, Mann: Wenn du dafür verantwortlich bist, die Armeen der Horde auszurüsten, dann brauchst du 'ne Menge Bälge!\n\nEroberin Krenna, die Wölfin, die diesen Ort hier leitet, hat mir 'ne knappe Frist gesetzt. Wenn ich ihr gesamtes Regiment nicht bis Ende der Woche ausgerüstet hab', dann kann ich mit den Bären in der Grube spielen.\n\nHilf mir aus und ich zahle dir einen Spitzenpreis. Ich brauche Bälge von Graunebeljägern.\n\nDu findest sie in Gruppen überall im Norden, auf der Jagd nach Hirschen. Denk dran, Mann: Spitzenpreis!", sourceObjective = "Balghändler Jun'ik möchte, dass Ihr ihm 3 graue Worgbälge von Graunebeljägern in den nördlichen Wäldern bringt.", progress = "Hast du die Bälge, Mann?", completion = "Du hast mein Leben gerettet, Bruder. Falls du an mehr Arbeit interessiert bist: Es gibt noch mehr, wo das herkam.", sourceObjectiveStatus = "unverified-source-field" }
quests[12176] = { id = 12176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleiner Ersatz", description = "Krenna wird Worgbälge für die ganzen Kleider brauchen. Für ihre Armee wird es jedoch nicht genug von den Bälgen geben - jetzt nicht und auch in Zukunft nicht.\n\nDiese Worgs - die sind dünn, Mann! Okay, ich sag dir, was wir machen... sofern du ein Geheimnis für dich behalten kannst.\n\nIm Osten von Voldrune gibt es Grizzlybären so fett wie Oger. Diese großen Bälge - die können wir benutzen!\n\nBeeil dich, <Bruder/Schwester>. Krenna ist nicht gerade für ihre Geduld bekannt.", sourceObjective = "Balghändler Jun'ik möchte, dass Ihr ihm 6 Grizzlybälge bringt.", progress = "Hast du die Bälge dabei, Mann?", completion = "Ich steh' in deiner Schuld, Mann. Nimm dies als Bezahlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12177] = { id = 12177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jun'iks Vertuschung", description = "Ah, wir ham ein kleines Problem. Grizzlyfelle... sin' braun, Mann!\n\nDenk nach... Denk nach!\n\nIch hab's, Mann! Es is' doch so: Grau is' schwarz und weiß durcheinander vermischt. Du besorgst mir ein bisch'n Kohle und ein bisch'n Mehl, ich werd' das alles mahlen und bestäub' die Felle damit. Das wird keinem auffallen!\n\nKohle gibt's in der Schmiede zum Verhütten und Mehl krichst du beim Versorger.", sourceObjective = "Bringt dem Balghändler Jun'ik in der Burg Siegeswall in den Grizzlyhügeln 1 Kohlestück und 5 Portionen herkömmliches Mehl.", progress = "Hast du den Kram, Mann?", completion = "Hoffen wir das Beste, Mann.", sourceObjectiveStatus = "unverified-source-field" }
quests[12178] = { id = 12178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung für Krenna", description = "Das is' es, Mann. Lass uns diese Felle zu Krenna bringen und gucken, ob sie den Test besteh'n.\n\nHoffen wir, dass Krenna nix bemerkt, um unserer beider willen.", sourceObjective = "Nehmt das Bündel Felle und bringt es zu Krenna in Burg Siegeswall.", progress = "Habt Ihr eigentlich irgendeine Ahnung, mit wem Ihr sprecht?", completion = "Für wen haltet Ihr mich eigentlich? Diese Felle riechen nach Mehl!\n\nDies ist eine echte Beleidigung der Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[12180] = { id = 12180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefangenen Ausgrabungsleiter", description = "Raegar hat ein Team von Ausgrabungsleitern nach Dun Argol gesandt, um nach Artefakten und Informationen über die Geschichte der Siedlung zu suchen. Raegars Team hätte nie gedacht, dass so viele Feinde dort sein würden.\n\nSie werden gefangen gehalten, während die Eisenzwerge zum Krieg rüsten. Wir haben nicht genug Männer, um sie da herauszuboxen, und Raegar ist so sehr in seine Phantasien zur Vernichtung der Eisenzwerge versunken, dass er keine große Hilfe wäre.\n\nSomit liegt es an Euch, {name}. Jeder der Eisen oder ihrer Diener könnte den Schlüssel zu den Zellen, in denen unsere Männer gefangen gehalten werden, bei sich tragen.", sourceObjective = "Befreit die Ausgrabungsleiter Gann, Torgan und Varana, dann kehrt zu Gebirgsjäger Kilian im Prospektorat zurück.", completion = "<Gebirgsjäger Kilian hört Euch zu, als Ihr erzählt, was die entführten Ausgrabungsleiter zu berichten hatten.>\n\nSie erwähnten Loken und einen Krieg gegen Steinriesen? Seid Ihr sicher?\n\nAlso waren Raegars Instinkte richtig. wir müssen einen Weg dort hinein finden und mehr über ihre Pläne herausbekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12181] = { id = 12181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebt dem Zeugs einen Namen", description = "Du meine Güte, wie lange ist es her? Wie lange arbeiten wir nun schon an dieser verdammten Seuche? Wir haben eine halbe Ewigkeit mit Fehlschlägen verbracht und wurden nun endlich mit Perfektion gesegnet. Dieses Zeugs... Es hat noch nicht einmal einen richtigen Namen! Diese Pest... wie Dunst - Hauch... Das ist es: PESTHAUCH! Dieser Pesthauch wird das Gewebe des Lebens selbst zersetzen!\n\n<Harris reicht Euch eine Phiole.>\n\nNun gut, findet den Fledermausführer Tobias und zeigt ihm diese Probe. Er wird Euch nach Gallgrimm bringen.", sourceObjective = "Zeigt Tobias Sarkhoff in Neu-Agamand die Pesthauchprobe.", progress = "Eine Lieferung extrem tödlichen Giftgases nach Gallgrimm? Kommt nur näher!", completion = "Ähm, ja, Ihr könnt die Phiole bei Euch behalten. Ihr habt mein Vertrauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12182] = { id = 12182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Gallgrimm!", description = "Für dich habe ich eine spezielle Fledermaus aufgetrieben, <Kumpel/Süße>. Auf ihr wirst du den schnellsten und sanftesten Ritt haben, den ich dir bieten kann. Sie wird dich direkt nach Gallgrimm bringen - und das mit Stil.\n\nÜbergib dann einfach die Phiole an den obersten Seuchenfürsten Middleton, nachdem du gelandet bist.", sourceObjective = "Liefert die Pesthauchprobe beim obersten Seuchenfürsten Middleton ab. Er befindet sich in Gallgrimm im Osten der Drachenöde.", progress = "Ihr spielt also den Lieferjungen?", completion = "Oh, was für ein wundervoller Tag! Und seht, dort, gleich hinter dem Berg im Nordosten gibt es haufenweise Diener der Geißel, die wir ausradieren können!", sourceObjectiveStatus = "unverified-source-field" }
quests[12183] = { id = 12183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überzeugende Verkleidung", description = "Wenn, wie Ausgrabungsleiterin Varana behauptet, manche Eisenzwerge mit diesem Loken kommunizieren können, dann sind es bestimmt die Vorarbeiter, denen dieses Privileg zukommt.\n\nWir müssen Euch da reinbekommen, damit Ihr rausfindet, was es damit auf sich hat, aber das wird nicht leicht. Zunächst braucht Ihr die richtige Uniform.\n\nDanach machen wir uns über das richtige Make-up Gedanken.\n\nFindet einen der Vorarbeiter in Dun Argol, tötet ihn und nehmt seine Uniform mit. Wenn Blut daran klebt, dann ist es Eure eigene Schuld.", sourceObjective = "Bringt eine Aufseheruniform zu Gebirgsjäger Kilian im Prospektorat.", progress = "Habt Ihr die Uniform bekommen?", completion = "<Kilian nimmt Euch die Uniform ab.>\n\nDamit sollte es klappen. Es bleibt keine Zeit, noch ein Namensschild mit '{name}' anzunähen, aber wenn wir mit Euch fertig sind, sollte jeder, der Euch aus der Nähe betrachtet, Euch für einen echten Vorarbeiter halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12184] = { id = 12184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fotosafari", description = "Nun, da wir die Uniform haben, brauchen wir noch einige Informationen, um Eure Verkleidung perfekt zu machen.\n\nRaegar hat diese Kamera mitgebracht, um die Entdeckungen des Teams zu dokumentieren, aber ich habe eine andere Verwendung im Sinn. Ich möchte, dass Ihr sie mit nach Dun Argol nehmt und mit ihr Bilder von den Eisenzwergen macht.\n\nNatürlich werden Eure Modelle nicht sonderlich kooperativ sein, daher müsst Ihr sie eventuell zunächst, ähm... \"beruhigen\". Bringt die Kamera mit den Bildern zurück, wenn Ihr fertig seid.", sourceObjective = "Benutzt Kilians Kamera, um Bilder von 8 Eisenzwergen in Dun Argol aufzunehmen. Dann kehrt zu Gebirgsjäger Kilian im Prospektorat zurück.", progress = "Habt ihr die Schnappschüsse gemacht?", completion = "Gut, das sollte ausreichen. Nun werde ich eine Verkleidung anfertigen können, die Euch zu einem waschechten Eisenzwerg machen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[12185] = { id = 12185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt Eure beste Miene auf für Loken", description = "Mithilfe der Bilder, die Ihr gemacht habt, habe ich alles zusammenbekommen, was Ihr für Eure Aufseherverkleidung braucht. Ihr werdet einen feinen Eisenzwerg abgeben, wenn ich das mal sagen darf.\n\nNehmt die Verkleidung mit nach Dun Argol, verkleidet Euch damit und geht zum östlichsten Gebäude in der breiten mittleren Ebene der Stadt.\n\nDort solltet Ihr ein Podest sehen, wo der Than und die Vorarbeiter ihre Befehle von Loken erhalten. Aktiviert es, während Ihr verkleidet seid und erfahrt so viel wie möglich aus der Kommunikation.", sourceObjective = "Verkleidet Euch als Eisenrunenaufseher, fangt die Nachricht von Loken ab und kehrt dann zu Gebirgsjäger Kilian im Prospektorat zurück.", completion = "Könnte es sein, dass Loken tatsächlich nicht übertreibt? Die Steine der Titanen und die Eisensöhne kämpfen gegeneinander um die Kontrolle der antiken Stadt Ulduar. Das ist Wahnsinn, {name}, und es könnte unsere einzige Chance, die wahre Geschichte über das Volk der Zwerge zu erfahren, zunichte machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12188] = { id = 12188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seuche der Verlassenen und du: Wie man nicht stirbt", description = "Wie genau nun die Seuche funktioniert, ist wohl kaum wichtig. Alles, was Ihr wissen müsst, ist, dass sie genau das macht, für was sie geschaffen wurde. Ich habe es zuwege gebracht, einen inaktiven Erregerstamm der Seuche künstlich herzustellen.\n\n<Middleton entkorkt die Phiole, setzt sie an die Nase und atmet ein.>\n\nSeht, mein Körper ist - zumindest größtenteils - unversehrt. Würdet Ihr das nun mit einem Agens vermischen, wären wir alle nichts weiter als ein Haufen klebriger Masse.\n\nAm Strand südlich von hier befinden sich die lächerlichen Geister einstiger Soldaten der Allianz. Zerstört sie und bringt mir ihre ektoplasmischen Überreste.", sourceObjective = "Oberster Seuchenfürst Middleton in Gallgrimm in der Drachenöde möchte, dass Ihr ihm 10 ektoplasmische Überreste bringt.", progress = "Die Überreste werden als Agens zur Aktivierung der Seuche dienen!", completion = "Das wird reichen, {name}. Haben sich diese lächerlichen Welpen Euch gestellt oder haben sie Euch lediglich mit geisterhaften Sorgentränen überschüttet?\n\nAh, sie sind so ergreifend...", sourceObjectiveStatus = "unverified-source-field" }
quests[12189] = { id = 12189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwachköpfe, wo man nur hinsieht!", description = "Die Lieferung aus Neu-Agamand hätte schon letzte Woche in Gallgrimm ankommen und nach ein paar einfachen Feldversuchen bei mir abgeliefert werden sollen. Hierbei handelt es sich um etwas, das für die Horde unerlässlich ist - um den letzten Teil des \"Siegesmosaiks\" sozusagen.\n\n<Sintar seufzt.>\n\nEs ist ziemlich entmutigend, nur von Schwachköpfen und Trotteln umgeben zu sein!\n\nGeht nach Gallgrimm gleich an der östlichen Grenze der Drachenöde. Findet diesen Kasper Middleton und lasst ihn wissen, dass ich auf das Paket warte.", sourceObjective = "Reist nach Gallgrimm in der Drachenöde und sprecht mit dem obersten Seuchenfürsten Middleton.", completion = "Wir sind auf ein kleines Problem gestoßen - ist auch NUR nebensächlich. Jeder, der mit der Seuche arbeiten wollte, ist einfach verdampft. Wir arbeiten gerade daran, die Formel ein klein wenig anzupassen, damit sie einen nicht gleich umbringt, wenn man auch nur einen Blick darauf werfen sollte. Die gute Neuigkeit ist, dass ich schon fast fertig bin!", sourceObjectiveStatus = "unverified-source-field" }
quests[12190] = { id = 12190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sagt hallo zu meinem kleinen Freund", description = "Harkor wird hin und weg sein, wenn er diese erstklassig'n Zutat'n sieht. Das Einzige, was es noch zu tun gibt, is', sie zu ihm zu bringen.\n\nEr hat sein Lager anner östlichen Küste inner Nähe dieser spukenden Ruinen - Drakil'jin werd'nse genannt. Ihr werdet wahrscheinlich eher dort ankommen, weil ich mich um diese Leichen hier kümmern muss... außer, Ihr möchtet Euer Glück lieber beim Einbalsamieren versuch'n.", sourceObjective = "Prigmon möchte, dass Ihr Harkors Zutaten zu Harkor in Harkors Lager bringt.", progress = "Was kann ich für Euch tun?", completion = "Nun denn! Der gute alte Prigmon hat Euch geschickt, nich' wahr?\n\nDas sollte genug für ein mächtig leck'res Essen sein. Fehlen nur noch ein paar Kleinigkeiten...", sourceObjectiveStatus = "unverified-source-field" }
quests[12191] = { id = 12191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haut weg das Zeug!", description = "Diese lästigen Dunkeleisenzwerge sind wieder da! Wir müssen sichergehen, dass Ihr Euch im Falle eines Falles verteidigen könnt. Noch viel wichtiger ist, wir müssen sichergehen, dass Ihr unser Eigentum verteidigen könnt!\n\nA.L.K. hier wartet auf ein bisschen Action, wie sieht es bei Euch aus? Trinkt aus dem Freibierkrug und werft ihn dann auf A.L.K.! Trefft das Ziel fünfmal und sprecht dann wieder mit mir.", sourceObjective = "Benutzt den Freibierkrug, um A.L.K. fünfmal zu treffen, und sprecht dann mit Bissel Schnellhub.", progress = "Ext den Krug und werft ihn dann auf A.L.K.! Ich denke, die Schläge machen ihr nichts aus. Sonst hätte ich sie ja nicht gestoh... äh... gebaut.", completion = "Wow... A.L.K. ist nicht kaputt gegangen... Hm... Wer hätte das gedacht?\n\nIch meine, hey, Ihr habt es geschafft! Eure Zielfertigkeit ist gut, zumindest gut genug, um bei der Verteidigung des Lagers zu helfen. Ich glaube, Ihr seid nun bereit, den Dunkeleisenzwergen gegenüberzutreten, wenn sie wieder aufkreuzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12192] = { id = 12192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dieses eine Mal, als ich betrunken war...", description = "Die Dunkeleisenzwerge haben einstecken müssen! Als sie zurück zum Grimmigen Säufer rannten, fiel ein Teil ihrer Ladung herunter. Was jedoch noch viel wichtiger ist: Dank Euch ist das Lager außer Gefahr... zumindest für heute.\n\nGeht zu Bissel und erzählt ihm von Eurem heldenhaften Sieg über die Dunkeleisenzwerge.", sourceObjective = "Sprecht mit Bissel Schnellhub im Braufestlager.", completion = "Ihr konntet die Dunkeleisenzwerge also aufhalten... und wart dazu noch betrunken? Genau das ist es, {class}, worum es beim Braufest geht! Und wo wir schon mal dabei sind: Denke mal, dass Ihr Eure Biermarken haben wollt.\n\nDanke für Eure Hilfe, {name}. Weiterhin noch viel Spaß auf dem Braufest.", sourceObjectiveStatus = "unverified-source-field" }
quests[12193] = { id = 12193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sagt mal, es gibt dieses Jahr nicht zufällig ein Souvenir?", description = "Beim Braufest geht es nicht nur um Widderrennen, sondern auch ums Trinken! Solltet Ihr einen Moment Zeit haben, dann bringt diesen Gutschein zu Belbi Blitzknips. Sie hält sich irgendwo im hinteren Teil des Braufestlagers auf. Falls Ihr sie nicht sehen könnt, keine Sorge, sie wird Euch mit Sicherheit entdecken.\n\nNaja, bringt Ihr auf jeden Fall diesen Gutschein für Euren kostenlosen Braufestkrug. Sie kümmert sich außerdem um alle sonstigen Braufestgeschäfte.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Belbi Blitzknips im Braufestlager ein.", progress = "Was ist los, Schätzchen? Habt Ihr etwas für mich?", completion = "Ooch, es ist nur ein Gutschein für einen Braufestkrug... vielleicht gebt Ihr Euch ja auch nur so unnahbar. So, hier habt Ihr den diesjährigen Krug.\n\nIch nehme an, dass ich Euch noch öfter hier sehen werde. Denn wenn Ihr Eure Braufestmarken einlösen möchtet, dann bin ich Euer Mädel hier...\n\noder vielleicht seins...  \n\nooohhh.... oder seins...", sourceObjectiveStatus = "unverified-source-field" }
quests[12194] = { id = 12194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sagt mal, es gibt dieses Jahr nicht zufällig ein Souvenir?", description = "Wir versorgen nicht nur jedermann mit Gebräu, sondern wir haben auch Krüge zu vergeben! Wunderschöne Andenken, die auf die legalste Weise überhaupt erworben wurden! Hier habt Ihr einen Gutschein.\n\nSprecht mit Blix, er hält sich irgendwo hinten beim Braufestlager auf. Er ist ziemlich seltsam, vor allem weil er jetzt immer diese Brille trägt. Er wird Euren Gutschein entgegennehmen und kümmert sich auch sonst um alle Braufestgeschäfte.", sourceObjective = "Löst Euren Gutschein für einen Braufestkrug bei Blix Fixtand im hinteren Teil des Braufestlagers ein.", progress = "Was ist los, Schätzchen? Habt Ihr etwas für mich?", completion = "Was ist das? Ein Gutschein für einen Braufestkrug? Ihr trinkt also gerne? Großartig! Sobald Ihr den Krug habt, solltet Ihr Euch ein paar Schluck gönnen... und noch ein paar mehr... und mehr... Dann, und das ist wichtig, kommt wieder hierher zu mir.\n\nIch weiß doch, dass Ihr wieder hierherkommt. Wenn Ihr Eure Braufestmarken einlösen möchtet, dann müsst Ihr hierher zu mir.\n\nNa ja, hier ist der Krug. Vergesst nicht, später noch einmal mit mir zu sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12195] = { id = 12195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein unerwarteter \"Gast\"", description = "Eine kürzlich zurückgekehrte Jagdexpedition hat mehr als nur Wild ins Lager gebracht.\n\nSie sind auf einen verwundeten Zwerg gestoßen, der vor den Eisenzwergen aus der Feste von Dun Argol geflohen war. Er könnte Informationen haben, die wir gegen unseren uralten Feind verwenden können, aber bevor er von Nutzen für uns sein kann, müssen wir sein Fieber in den Griff bekommen.\n\nDie Geweihe des Silberfellhirschs, der in den nahen Wäldern zu finden ist, werden seit Langem zur Herstellung von Heilpackungen verwendet. Bringt mir genügend Geweihe, dann sehen wir mal, ob meine Heilpackung unseren 'Gast' wieder auf die Füße bekommt.", sourceObjective = "Bringt 5 ausgewachsene Hirschgeweihe zu Tormak dem Vernarbten in Camp Oneqwah.", progress = "Habt Ihr die Geweihe dabei?", completion = "Das sollte reichen. Schauen wir mal, ob es funktioniert.", sourceObjectiveStatus = "unverified-source-field" }
quests[12196] = { id = 12196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Grund auf", description = "Es bleibt nicht mehr genug Zeit, die Teile selbst zu schmieden, aber die Gießereien drüben in Dun Argol, südöstlich von hier, arbeiten Tag und Nacht und stellen Golemteile am laufenden Band her.\n\nIch glaube, Ihr solltet dorthin zurückgehen und genug davon einpacken, damit ich nach diesen Blaupausen einen Golem herstellen kann.\n\nVermutlich liegen sie um die Gebäude herum verstreut, in denen die Eisenrunenschmiede arbeiten.\n\nBitte beeilt Euch, {name}. Dieser Tormak wartet nur darauf, seine Drohung wahrmachen zu können!", sourceObjective = "Bringt Ausgrabungsleiter Rokar im Camp Oneqwah 8 Teile eines Kriegsgolems.", progress = "H-habt Ihr d-diese Golemteile mitgebracht?", completion = "<Rokar wischt sich mit dem Handrücken über die Stirn.>\n\nOh, dem Licht sei Dank. Er hat mir angedroht, mir kein Essen zu geben, bis Ihr zurück seid. Lasst uns diesen Stapel Teile sortieren und sehen, was wir daraus machen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12197] = { id = 12197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir haben die Macht", description = "Gut, nun haben wir die Hülle eines Golem, aber das reicht Tormak noch nicht. Er sieht nicht ein, dass diese Dinge sich nicht einfach von selbst zusammensetzen und magisch zu funktionieren anfangen! Wir brauchen Energiezellen, um ihn zum Leben zu erwecken.\n\nAls ich in Dun Argol war, ist mir aufgefallen, dass die Runenschmiede Durar und Kathorn diejenigen waren, die die Zellen angefertigt haben. Wir brauchen je eine Zelle von beiden, um unseren Golem aufzuladen.\n\nIhr solltet die Runenschmiede in ihren Werkstätten in der zentralen Ebene von Dun Argol finden.", sourceObjective = "Bringt Durars Energiezelle und Kathorns Energiezelle zu Ausgrabungsleiter Rokar im Camp Oneqwah.", progress = "Habt Ihr diese Energiezellen?", completion = "<Rokar nimmt Euch die Batterien ab.>\n\nSie sind fast leer, aber es wird ausreichen, um den Golem aufzuladen. Damit ist er aber noch lange nicht bereit für einen Kampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[12198] = { id = 12198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "... oder vielleicht doch nicht", description = "Die Zellen des Golems haben gerade genug Energie, um auf unterster Stufe zu laufen, doch für die Kampfsysteme reicht es nicht.\n\nDie gute Nachricht ist, dass die Umgebung von Dun Argol von Blitzwachen bewacht wird. Mit deren Hilfe sollten wir in der Lage sein, die Waffensysteme des Golems aufzuladen.\n\nNehmt den Golem mit, bringt ihn nah an sie heran, wenn die Wachen sterben, wird er ihre Energie absorbieren.", sourceObjective = "Ladet Euren Kriegsgolem mit der Energie von 10 Blitzwachen auf und kehrt dann zu Ausgrabungsleiter Rokar in Camp Oneqwah zurück.", progress = "Habt Ihr den Golem aufgeladen? Tormak wird wieder ungeduldig...", completion = "Nun kann sich Tormak nicht mehr beschweren. Mehr kann ich an dem Golem nicht mehr machen.\n\nSobald Ihr mit ihm eine Schneise durch Dun Argol geschlagen habt, wird mich diese zu groß geratene Kuh wohl gehen lassen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12199] = { id = 12199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nieder mit dem Eisenthan!", description = "Da der Golem nun vollständig aufgeladen ist, kann er gegen den Anführer in Dun Argol eingesetzt werden.\n\nAls ich Eisenthan Zornhammer observiert habe, wurde er stets von einem persönlichen Golem beschützt, der ihn von jeglicher Gefahr ferngehalten hat.\n\nDiese Konstruktion namens \"der Amboss\" kann sabotiert werden, so dass er seinen Schild fallen lässt. Benutzt die EMP-Fähigkeit Eures Golems, um genau das zu tun. Ihr solltet Euren Golem innerhalb Dun Argols aktivieren und kontrollieren können.\n\nDer Than hält sich oben im Hauptgebäude auf und überwacht von dort aus die Produktion unten.", sourceObjective = "Besiegt den Eisenthan Zornhammer mithilfe Eures Kriegsgolems und kehrt dann zu Tormak dem Vernarbten im Camp Oneqwah zurück.", completion = "Also hat der Ausgrabungsleiter sein Versprechen wahr gemacht? Gut. Ich habe mich schon gefragt, ob all dies Schnorren von Metallstücken und Klauen von Baumaterial zu irgendwas führen würde.\n\nEs ist eine Schande, dass er uns nicht mehr nützlich sein wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[12200] = { id = 12200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smaragddrachentränen", description = "Da nun das träge Exemplar des Seuchenpräparats fertiggestellt und wir das Aktivierungsagens in Händen halten, fehlt uns nur noch eine passende Hülle für die Komponenten.\n\nSüdwestlich von hier an der zentralen Küste der Drachenöde liegt der Smaragddrachenschrein. Im Inneren des Schreins findet Ihr die hart gewordenen Überreste der Träne eines grünen Drachens. Ich kenn' zwar nicht die ganze Geschichte, aber anscheinend weinen sie sehr viel, bevor sie sterben - stellt Euch vor.\n\nGeht zum Smaragddrachenschrein und sammelt Tränen.", sourceObjective = "Oberster Seuchenfürst Middleton in Gallgrimm in der Drachenöde möchte, dass Ihr 8 Smaragddrachentränen sammelt.", progress = "Glücklicherweise befindet sich ein Ort in der Nähe, in dem es mehr als genug Smaragddrachentränen gibt. Ansonsten hätte ich Euch nach Feralas schicken müssen.", completion = "Ich glaube, dass wir die Seuche jetzt einem Feldversuch unterziehen können. Zufälligerweise wird die Feste Wintergarde gerade von der Zitadelle des Schreckens Naxxramas belagert. Nun kommen die lebenden Toten aus genau dem Boden hervor, auf dem Wintergarde erbaut wurde - begierig darauf, Kel'Thuzads Befehle auszuführen.\n\nDie Allianz ist, wie könnte es anders sein, zahlenmäßig und an Waffenkraft unterlegen. Die Leute, die im Mausoleum von Wintergarde ihre letzte Ruhe gefunden haben, wachen von Neuem auf und es verlangt ihnen nach Fleisch!\n\nVielleicht sollten wir ihnen mal eine Kostprobe unserer Seuche bescheren, was meint ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[12201] = { id = 12201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Aufsehers Schatten", description = "Hört sich an, als sei dieser Loken der Drahtzieher hinter den plötzlichen Kriegsvorbereitungen der Eisenzwerge.\n\nNur die höchstrangigen Eisenzwerge haben für gewöhnlich Zugang zu ihm, deshalb müssen wir Euch wohl zu einem Aufseher machen, um herauszufinden, was dort vor sich geht.\n\nIch habe einen Plan dafür, jedoch brauchen wir ein paar Sachen.\n\nSucht einen der Eisenrunenaufseher in Dun Argol im Südosten und nehmt ihm seine Uniform ab.", sourceObjective = "Bringt eine Aufseheruniform zu Späher Vor'takh in Oneqwah.", progress = "Habt Ihr die Uniform besorgt?", completion = "Das sollte funktionieren, jedoch bleibt da noch die Frage nach dem Rest der Verkleidung. Selbst diese verblödeten Metallzwerge erkennen einen Schwindler in einer gestohlenen Uniform.", sourceObjectiveStatus = "unverified-source-field" }
quests[12202] = { id = 12202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fotosafari", description = "Jetzt müssen wir nur noch letzte Handgriffe anlegen, um Euch genauso abstoßend hinzukriegen, wie es die Eisenzwerge sind.\n\nAm ehesten schaffen wir das, indem wir Eure Verkleidung an den Visagen der echten Eisenzwerge ausrichten.\n\nAls Tormaks Jagdgruppe diesen missratenen Ausgrabungsleiter gefunden hat, haben sie ihm gleich mal die Kamera, die er dabei hatte, abgenommen. Jetzt ist wohl die Zeit gekommen, sie zu benutzen.\n\nNehmt sie mit nach Dun Argol, tötet einige Eisenzwerge und bannt ihre Visagen auf dieses Gerät. Bringt es zurück, sobald Ihr genügend Exemplare habt.", sourceObjective = "Benutzt Rokars Kamera, um in Dun Argol die Bilder von 8 Eisenzwergen aufzunehmen und kehrt dann zu Späher Vor'takh im Camp Oneqwah zurück.", progress = "Habt Ihr diese Schnappschüsse?", completion = "Das sollte reichen. Bei Garrosh, sind diese Kreaturen abstoßend!", sourceObjectiveStatus = "unverified-source-field" }
quests[12203] = { id = 12203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lokens Befehle", description = "Ich habe auch alles Andere, was Ihr für Eure Aufseherverkleidung benötigt, hergestellt. Bitte, versucht nicht zu würgen, wenn Ihr sie anlegt.\n\nNehmt die Sachen mit, wenn Ihr in den Südosten nach Dun Argol geht, benutzt sie, um Euch zu verkleiden, und geht dann zu dem Gebäude im äußersten Osten auf der breiten mittleren Ebene der Stadt.\n\nDort solltet Ihr ein Podest sehen, auf welchem der Than und die Aufseher ihre Befehle von Loken erhalten. Aktiviert es, während Ihr verkleidet seid, und sammelt so viele Informationen wie möglich.", sourceObjective = "Verkleidet Euch als Eisenrunenaufseher, fangt die Nachricht von Loken ab und erstattet dann Späher Vor'takh im Camp Oneqwah Bericht.", completion = "Er hat also vor, einen Bürgerkrieg zwischen den verschiedenen titanischen Schöpfungen heraufzubeschwören? Warum bedeutet ihm die Titanenstadt Ulduar so viel? Ich nehme an, dass es dies ist, was Kurun und seine Riesen zu verhindern hoffen.\n\nNun ja, ich bezweifle, dass wir die Riesen davon abhalten können, einander zu bekämpfen, aber möglicherweise finden wir einen Weg, dies zu unserem Vorteil zu nutzen. Ich muss sofort unseren Anführern Bericht erstatten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12204] = { id = 12204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Lokens Namen", description = "Die Eisenzwerge sind einer der erbittertsten und organisiertesten Gegner in Nordend. Wo auch immer wir hingekommen sind, haben sie uns mit dem Namen Lokens auf den Lippen bekämpft.\n\nWir müssen herausbekommen, wer dieser Loken ist und was er vorhat. Die Einheimischen könnten uns weiterhelfen.\n\nIm Nordosten, im Handelsposten von Rotholz, bietet ein Mensch namens Hugh Glass seine Waren feil. Weiter östlich, bei den Ruinen von Tethys, findet Ihr einen Steinriesen, der Gavrock genannt wird. Fragt sie nach diesem Loken. Sie müssen einfach irgendwelche brauchbaren Informationen haben.", sourceObjective = "Redet Mit Hugh Glass und Gavrock über Loken und übermittelt Eure Erkenntnisse Späher Vor'takh im Camp Oneqwah.", completion = "Also ist er der Strippenzieher bei den Eisenzwergen? Wir müssen herausfinden, was er den Eisenzwergen von Dun Argol befohlen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[12205] = { id = 12205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Der Scharlachrote Ansturm", description = "Auf Befehl des Hochexekutors Zürner sind alle Mitglieder der illegalen Organisation genannt \"der Scharlachrote Ansturm\" auf der Stelle zu töten.\n\nIhnen ist keine Gnade zu gewähren. Diejenigen, die aufgrund dieses Erlasses zur Tat schreiten werden, sollten darüber im Klaren sein, dass der Tod noch das Mildeste ist, was man erwarten kann, sollte man von den Menschen gefangen genommen werden!\n\nUm es in den Worten des Hochexekutors auszudrücken: \"Färbt den Schnee rot mit ihrem Blut!\"", sourceObjective = "Tötet 20 Mitglieder des Scharlachroten Ansturms und meldet Euch anschließend bei Hochexekutor Zürner in Gallgrimm.", completion = "Sehr gut gemacht, {race}. Ich vertraue einmal darauf, dass Ihr mit viel Geschick zu Werke gegangen seid.\n\nDann lasst uns mal sehen, wie viel die Toten - ähm - ich meine, wie viel die Truhen Euch einbringen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12206] = { id = 12206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verseuchte letzte Riten", description = "Habt Ihr den Steckbrief gelesen? Was denkt sich der Hochexekutor nur?!\n\n<Vicky sieht sich um und fährt mit gedämpfter Stimme fort.>\n\nWir können doch wohl nicht zulassen, dass diese Idioten vom Scharlachroten Ansturm von ihren Priestern wiedererweckt werden oder - schlimmer noch - als Diener der Geißel wieder auferstehen, nicht wahr?\n\nNein, ich stimme Euch völlig zu, wir müssen etwas gegen die Leichen unternehmen.\n\nIch hab' genau das nötige Werkzeug. Nehmt dieses Fläschchen an Euch, in ihm befindet sich die erst kürzlich von uns hergestellte Seuche, und testet dessen Inhalt an dem Gefangenen in dem Käfig hier aus.\n\nKeine Aufregung, einfach zurücklehnen und zugucken - und siehe da: keine Feinde, die wieder auferstehen können.", sourceObjective = "Apothekerin Vicky Levine in Gallgrimm möchte, dass Ihr das Seuchenfläschchen an dem Gefangenen des Scharlachroten Ansturms austestet.", progress = "Habt Ihr es getan?\n\nHe, ich hab' vergessen, Euch zu sagen, dass Ihr Euch lieber nicht mit dem Zeug voll kleckern solltet! Es ist gefährlich und die Flecken lassen sich nicht entfernen - ganz zu schweigen von dem Spaß, den Ihr dabei hättet, die Stellen wieder zu heilen, an denen Euch das Fleisch vom Körper fiel.", completion = "WAS?! Das ist unmöglich! Wir haben die Seuche perfektioniert. Sie ist zu hundert Prozent tödlich.\n\n<Die Apothekerin ringt die Hände - Besorgnis steht in ihrem untoten Gesicht geschrieben. Sie ist ganz offensichtlich frustriert und mit Zorn in ihrer Stimme fährt sie fort.>\n\nDas ist einfach nur seltsam. Reicht mir das Fläschchen, {class}. Ich werde auf keinen Fall die Apothekerin sein, die alles zum Scheitern brachte!", sourceObjectiveStatus = "unverified-source-field" }
quests[12207] = { id = 12207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordrassils Fall", description = "Vor langer Zeit pflanzten mächtige Druiden einen Baum nordöstlich von hier.\n\nEr wurde Vordrassil genannt und sollte zu einem Weltenbaum erwachsen. Es ist nicht bekannt warum, aber nachdem der Baum vollständig ausgewachsen war, entschieden die Druiden, dass er zerstört werden müsse.\n\nSeit dem Moment, an dem wir hier angekommen sind, hat die Erde zu mir gesprochen, {name}. Ihre Schmerzenslaute kommen von den Orten, an dem Vordrassils Überreste den Boden berührten.\n\nFauliger Schlamm ist dort zu finden. Bringt mir Proben davon, sodass wir damit beginnen können, dieses Land zu heilen.", sourceObjective = "Windseherin Grauhorn in Burg Siegeshall möchte, dass Ihr zu Vordrassils Ast, Vordrassils Herz oder Vordrassils Tränen geht und 6 Schleimproben des entropischen Schlamms besorgt.", progress = "Habt Ihr die Proben sammeln können, {name}?", completion = "Dieser Schleim stinkt nach einer Finsternis, die viel älter ist, als ihre weltliche Form einen annehmen lassen würde. Das Land selbst erinnert sich an dieses Böse, seitdem es existiert.\n\nWir müssen mehr herausfinden, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12208] = { id = 12208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute Trolljagd", description = "Diese nichtsnutzigen Mistkerle!\n\nSie hätten es einfacher haben können. Wir haben ihnen die Hand zum Frieden gereicht. Alles, was sie hätten tun müssen, ist, uns den Durchgang durch Drak'Tharon zu gewähren, und wir hätten sie in Ruhe gelassen.\n\nDoch nein, die hochmütigen kleinen Eistrolle wollen es anscheinend auf die harte Tour. Wir werden so oder so durch ihre kostbare Festung marschieren, um nach Zul'Drak zu gelangen. Doch nun werden sie vernichtet werden.\n\nWir haben eine Bande angeheuert, die für uns Trolle einfangen soll. Sprecht mit Samir, wenn Ihr bei der Sache mitmischen wollt. Ihr könnt ihn nordwestlich von hier, südlich von Zeb'Halak finden.", sourceObjective = "Unteroffizier Thurkin möchte, dass Ihr mit Samir am Granitquell sprecht.", completion = "Ihr seid hier, um bei der Kopfgeldangelegenheit mitzumischen, wie?", sourceObjectiveStatus = "unverified-source-field" }
quests[12209] = { id = 12209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsbeute", description = "Ah gut, Frischfleisch. Wollt Ihr Euch bewähren, Frischfleisch?\n\nDer Scharlachrote Ansturm, die fanatischste und rassistischste Gruppe des Scharlachroten Kreuzzuges, steht vor unserer eigenen Haustüre - im Süden. Wenn wir sie bekämpfen wollen, werden wir mehr Rüstungen und Waffen benötigen, als ich in so kurzer Zeit überhaupt herstellen kann.\n\nWieso schnappen wir uns nicht einfach ihre Waffen?\n\nGenauer gesagt: Wieso schnappt IHR EUCH nicht einfach ihre Waffen?", sourceObjective = "Quartiermeister Bartlett in Gallgrimm möchte, dass Ihr 8 Rüstungen des Scharlachroten Ansturms und 8 Waffen des Scharlachroten Ansturms stehlt.", progress = "Ich nehme, was auch immer Ihr mir an Rüstungen und Waffen besorgen könnt, Frischfleisch.\n\nQualitativ gesehen werden sie zwar nicht an das heranreichen, was ich hier herstellen kann, doch sie sind besser als gar nichts.", completion = "So frisch riecht Ihr gar nicht mehr, Frischfleisch.\n\nNun gut, das wird wohl reichen. Wie soll ich Euch nun nennen, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[12210] = { id = 12210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollsaison!", description = "Ihr, {race}! Was für eine Verschwendung, hier herumzustehen, während es dort draußen noch Arbeit zu tun gibt!\n\nDie Feste Drak'Tharon ist der direkteste Weg nach Zul'Drak. Wir MÜSSEN sie einnehmen, um dafür zu sorgen, dass die Allianz dort sicher ankommt. Doch bis wir die nötigen Leute für einen Angriff zusammenhaben, müssen wir uns damit begnügen, die Reihen der Eistrolle zu lichten und Informationen zu sammeln.\n\nFür letzteres haben wir eine Bande von Rohlingen eingezogen, die lebendige Trolle einfangen und dann zwecks Vernehmung hierher bringen sollen. Reist nach Nordwesten und sprecht mit Samir am Granitquell. Er wird Euch sagen, wie es weitergeht.", sourceObjective = "Leutnant Dumont bei der Ammertannhütte möchte, dass Ihr mit Samir am Granitquell sprecht.", completion = "Ihr seid hier, um bei der Kopfgeldangelegenheit mitzumischen, oder was?", sourceObjectiveStatus = "unverified-source-field" }
quests[12211] = { id = 12211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst sie nicht wieder auferstehen!", description = "Ich verstehe es einfach nicht. Es sollte mit der Seuche doch eigentlich funktionieren.\n\nAber Jammern hat keinen Sinn.\n\n<Aus irgendeinem Grund wirkt die Apothekerin erleichtert.>\n\nObwohl es merkwürdigerweise beim Ansturm nicht zu wirken scheint, müssen wir nach wie vor ihre Priester davon abhalten, sie wiederzuerwecken.\n\nIch habe eine andere Idee - eine, vor der Ihre Leichname keinen Schutz haben sollten.\n\nNehmt einen Behälter mit Ratten, {name}, und lasst sie auf jede Leiche des Scharlachroten Ansturms los, die ihr finden könnt. Ich habe das Gezücht hungern lassen - also sollten sie besonders garstig sein!", sourceObjective = "Apothekerin Vicky Levine aus Gallgrimm hat Euch gebeten, Ihr Behältnis voller Ratten zu benutzen, um 15 Leichen von Anhängern des Scharlachroten Ansturms in Neuherdweiler zu beseitigen.", completion = "Sehr gut! Einen Moment lang dachte ich schon, ich müsste die Ratten an jemandem ausprobieren, um sicherzustellen, dass sie nicht defekt sind.\n\nEndlich ein Fortschritt!", sourceObjectiveStatus = "unverified-source-field" }
quests[12212] = { id = 12212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Lagerhaus auffüllen", description = "Guten Tag, {class}.\n\nDer gute Leutnant hier meint, dass die Horde unser Lagerhaus geplündert hätte, wodurch unser Essensvorrat nun gefährlich klein geworden sei.\n\nDiese Schwachköpfe werden dafür auf jeden Fall büßen, doch zuerst müssen wir unsere Aufmerksamkeit darauf richten, unsere Vorräte wieder aufzufüllen. Meine Männer tun alles, was in ihrer Macht steht, doch wir werden jeden benötigen, der etwas beitragen kann, wenn wir eine Krise verhindern wollen.\n\nEs sollte keine Schwierigkeiten darstellen, die Hirsche in dieser Gegend zu erlegen, um an deren Fleisch heranzukommen. Frohe Jagd!", sourceObjective = "Förstermeister Anderhol bei der Ammertannhütte möchte, dass Ihr Großhornhirsche tötet und 8 Stück saftiges Wildbret sammelt.", progress = "Wie läuft die Jagd, {race}?", completion = "Das ist doch mal feinstes Fleisch!", sourceObjectiveStatus = "unverified-source-field" }
quests[12213] = { id = 12213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dunkelheit darunter", description = "Etwas… Dunkles… ist dem Baum Vordrassil zugestoßen. Nachdem die Druiden beschlossen hatten, ihn zu zerstören, bohrten seine hohlen Überreste ihre Wurzeln tief in den Boden.\n\nIch möchte, dass Ihr zu den drei Orten im Nordosten geht, wo der Stamm gesplittert ist und, so weit Ihr könnt, in den Untergrund vordringt.\n\nBenutzt diese Kugel, sobald Ihr eingetroffen seid, um die Spuren der Energie, welche die Gegend umgibt, anzeigen zu können. Dies könnte aufzuklären helfen, was mit Vordrassil damals passiert ist und warum er es nicht geschafft hat, ein Weltenbaum zu werden.", sourceObjective = "Windseherin Grauhorn möchte, dass Ihr zu Vordrassils Herz, Vordrassils Tränen und Vordrassils Ast geht und die Kugel des Geomanten in den Tiefen unter der Erdoberfläche anwendet.", completion = "Diese Kugel… sie wurde von einer... abgrundtief bösen Macht befleckt.\n\nWas ich auch sonst noch durch weitere Untersuchungen herausfinden werde, eines ist sicher: Ich muss die Kugel so bald als möglich zerstören. Ihre verderbende Macht ist einfach zu groß.", sourceObjectiveStatus = "unverified-source-field" }
quests[12214] = { id = 12214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ersatzpferde", description = "Hallo, <mein Herr/meine Dame>. Ich bin Hänsel. Schön, Euch kennenzulernen\n\nDer Hochexekutor kam zu mir und meinte: 'Hänsel, ich möchte, dass du uns ein paar neue Pferde beschaffst.'\n\nWas meint er denn, wo Schreckensrösser herkommen? Aus dem Boden?\n\n<Hänsel flüstert.> Auf Pferdefriedhöfen tun sie das sogar.\n\nNur gibt es hier keinen, also müsst Ihr nach Neuherdweiler im Süden gehen, die Ritter töten, ihnen die Reitgerten abnehmen und ihre Schlachtrösser stehlen.\n\nWäre gut, wenn Ihr dann mit dem Pferd zu mir reitet und mir die Zügel gebt.", sourceObjective = "Hänsel Bauer in Gallgrimm möchte, dass Ihr 3 Kriegspferde des Ansturms stehlt, sie anschließend bei ihm abliefert und ihm dann auch die Zügel übergebt.", progress = "Ich bin richtig erleichtert, dass Ihr hier aufgetaucht seid. Ich hatte schon Angst, dass ich die Sache selbst in die Hand nehmen muss.", completion = "Ah, gute Arbeit - nichts ist schöner als das.\n\nIhr habt Gallgrimm einen großen Dienst damit erwiesen, diese Pferde zu besorgen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12215] = { id = 12215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie oder wir!", description = "Als ob wir nicht schon genug hätten, das uns Sorgen bereitet...\n\nAufgrund der jetzigen Essenskrise befinden wir uns mit den hiesigen Worgs im Nahrungsstreit. Die Situation wird immer schlimmer und ich befürchte, dass es schon bald nichts mehr zu jagen geben wird, wenn wir uns nicht sofort diesem Problem zuwenden.\n\nDurchkämmt den Wald, {race}. Tötet alle Graunebeljäger, die Ihr finden könnt. Jüngste Berichte sprechen von einer Ansammlung dieser Wesen am anderen Ufer des westlich gelegenen Flusses.", sourceObjective = "Anderhol bei der Ammertannhütte möchte, dass Ihr in den Grizzlyhügeln nach 6 Graunebeljägern sucht und sie tötet.", completion = "Gute Arbeit, {class}.\n\nDas sollte uns dabei helfen, sicherzustellen, dass die Tiere in dieser Gegend auch dort landen, wo sie hingehören - nämlich auf dem Rost über unseren Feuern.", sourceObjectiveStatus = "unverified-source-field" }
quests[12216] = { id = 12216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bärenhatz!", description = "Wir haben hart gearbeitet und so langsam sehen wir auch die Früchte dieser Arbeit, aber wir sind noch immer weit davon entfernt, unser Ziel zu erreichen. Wir brauchen viel mehr Fleisch als wir haben und die Hirschpopulation hier wird alleine nicht ausreichen.\n\nIch fürchte, Ihr müsst Eure Aufmerksamkeit etwas gefährlicherer Beute zuwenden... den Grizzlys, die dieser Gegend den Namen geben. Es gibt sie Zuhauf und sie sind wohlgenährt von den ganzen Fischschwärmen in diesen Gewässern.\n\nGebt auf Euch acht, {class}!", sourceObjective = "Anderhol bei der Ammertannhütte möchte, dass Ihr 8 Grizzlyflanken von den Grizzlybären in den Grizzlyhügeln ergattert.", progress = "Der mächtige {class} ist zurückgekehrt!", completion = "Hervorragend!\n\nUnser Vorratslager ist nun fast wieder voll. Ihr habt euren Beitrag dazu geleistet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12217] = { id = 12217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adleraugen", description = "Nun, {name}, wir haben herausgefunden, wie die Horde unsere verborgenen Nahrungslager lokalisieren konnte.\n\nOffensichtlich war ihre Sicht an die der arglosen Adler gebunden, die hier über den Bäumen kreisen. Mit der Sicht der Adler war es ihnen tatsächlich möglich, jede unserer Handlungen zu beobachten.\n\nAuf Befehl des Leutnants sollen wir diese majestätischen Vögel erlegen, um unserem Feind einen Strich durch die Rechnung zu machen.", sourceObjective = "Anderhol bei der Ammertannhütte möchte, dass Ihr 5 Kaiseradler tötet und ihm anschließend Bericht erstattet.", completion = "Eine düstere Aufgabe, ich weiß. Aber wir können uns wieder sicherer fühlen, jetzt, da wir wissen, dass die Augen des Feindes nicht länger auf uns ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12218] = { id = 12218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbreitet die guten Neuigkeiten", description = "Bevor ich Euch mit den guten Neuigkeiten zu Doktor Malefius schicken kann, werdet Ihr einen einfachen Feldversuch der von mir modifizierten Seuche durchführen müssen.\n\nDie hungernden Toten strömen aus den Überresten von Altwintergarde. Beschlagnahmt eines der Gefährte am Osttor und fahrt mit ihm nach Nordosten durch den Pass der Vergeltung bis Ihr die Zwillingstürme in der südöstlichen Ecke von Wintergarde erreicht. Feuert die Seuchenbombe auf die Untoten ab, von denen es in der Gegend nur so wimmelt. Meldet Euch anschließend mit den Resultaten wieder bei mir zurück!", sourceObjective = "Oberster Seuchenfürst Middleton in Gallgrimm in der Drachenöde möchte, dass Ihr in den Seuchenverbreiter der Verlassenen steigt, zu den Randgebieten der Aasfelder fahrt und dort mithilfe der Seuchenbombe 30 hungernde Tote vernichtet.", completion = "So sehr es mich verärgert, dass wir der Allianz womöglich geholfen haben, erkläre ich hiermit den Feldversuch für erfolgreich! Nächster Halt: Agmars Hammer!", sourceObjectiveStatus = "unverified-source-field" }
quests[12219] = { id = 12219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der eingegangene Weltenbaum", description = "Meine Urahnen pflanzten einst einen Baum in der Mitte der Grizzlyhügel.\n\nVordrassil wurde er genannt und sollte ein Weltenbaum werden.\n\nAus Gründen, die schon lange in Vergessenheit geraten sind, beschlossen sie, den Baum zu zerstören, nachdem er seine volle Größe erreicht hatte. Seine Splitter befinden sich an drei verschiedenen Orten in der Gegend im Norden.\n\nDort, wo der Baum den Boden berührte, tauchte fauliger, lebendiger Schlamm auf. Bringt mir ein paar Schleimproben, damit ich mit meiner Arbeit beginnen und die Erde heilen kann.", sourceObjective = "Hierophant Thayreen bei der Ammertannhütte möchte, dass Ihr zu Vordrassils Ast, Vordrassils Herz oder zu Vordrassils Tränen geht und 6 Schleimproben des entropischen Schlamms beschafft.", progress = "Habt Ihr die Proben gesammelt, {name}?", completion = "Der Schleim ist nicht natürlich, {name}. Er ist von Natur aus verderbt und... boshaft.\n\nWir müssen noch mehr darüber herausfinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12220] = { id = 12220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein dunkler Einfluss", description = "Als der Baum Vordrassil fiel, bohrten seine hohlen Überreste ihre Wurzeln tief in den Boden.\n\nIch möchte, dass Ihr nach Norden geht, die drei Orte aufsucht, wo der Stamm gesplittert ist, und so tief wie möglich in den Untergrund vordringt. Sie liegen westlich von Grauschlund.\n\nBenutzt diese Kugel, sobald Ihr eingetroffen seid, um die Spuren der Energie, welche die Gegend umgibt, anzeigen zu können. Wenn wir das Land heilen wollen, müssen wir zunächst herausfinden, was dazu geführt hat, dass Vordrassil vor all diesen Jahren als Weltenbaum versagt hat.", sourceObjective = "Hierophant Thayreen bei der Ammertannhütte will, dass Ihr zu Vordrassils Herz, Vordrassils Tränen und Vordrassils Ast geht und die Kugel des Geomanten in den Tiefen unter der Erdoberfläche anwendet.", completion = "Die Energie in der Kugel ist… überwältigend… \n\nEine dunkle Macht hat den Boden bei Vordrassils Überresten befleckt. Wir müssen dies weiter untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12221] = { id = 12221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seuche der Verlassenen", description = "Ich habe ein Paket vorbereitet, das an Doktor Sintar Malefius in Agmars Hammer geschickt werden muss. Der Inhalt des Pakets besteht aus der fertigen Pesthauchprobe, zusammen mit der Herstellungsanleitung und Proben des Aktivierungsagens.\n\nIhr findet Agmars Hammer im Westen der Drachenöde. Haltet einfach nach den schwarzen, gezackten Metallgebäuden der Orcs Ausschau - das wird dann Agmars Hammer sein.", sourceObjective = "Liefert die Seuche der Verlassenen bei Doktor Sintar Malefius in Agmars Hammer ab.", progress = "Wurde auch langsam Zeit!", completion = "<Doktor Malefious wirft einen kurzen Blick auf den Inhalt des Pakets.>\n\nHerrlich! Genau nach Angabe!\n\nHier ist Eure Bezahlung, {name}. Behaltet das, was Ihr gesehen und getan habt, für Euch. Die Sache ist streng geheim - Informationen werden bei Bedarf weitergegeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12222] = { id = 12222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Flammenbinder", description = "Während wir versuchen, die Horde zurückzuschlagen, sammelt sich der Stamm der Drachenschinder in ihrem Dorf Voldrune, in der Nähe der Küste im Süden.\n\nDen mächtigsten Kriegern im Dorf werden flammenerfüllte Talismane gewährt, die ihnen die Fähigkeit geben, mächtige, wilde Protodrachen zu kontrollieren. Wenn es uns gelänge, die Kontrolle über einen dieser Drachen zu übernehmen, dann könnten wir ihn vielleicht dazu nutzen, die Gefahr, die von Voldrune ausgeht, zu neutralisieren.\n\nDie Flammenbinder der Drachenschinder erschaffen die Talismane und erfüllen sie mit Macht. Tötet sie und nehmt die Talismane.", sourceObjective = "Bringt dem Förster Drach bei der Ammertannhütte 3 flammenerfüllte Talismane.", progress = "Habt Ihr diese Talismane bekommen?", completion = "Mit diesen Talismanen in der Hand wird der Drache keine andere Wahl haben, als Euch zu gehorchen. Ich kann es kaum abwarten, den Gesichtsausdruck des Thans zu sehen, wenn er feststellt, dass Ihr das Kommando über seinen Protodrachen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12223] = { id = 12223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reihen lichten", description = "In Voldrune gen Süden geht es richtig zu. Thane Torvald Eriksson und seine Huscarls bereiten sich auf den Krieg vor. Ammertann wird verwundbar sein, da sich die meisten unserer Männer draußen im Feld befinden und sich um die verräterische Horde kümmern.\n\nReist nach Voldrune nahe der Südküste und zeigt diesen Drachenschindern, dass mit uns nicht zu spaßen ist.\n\nErschlagt so viele Huscarls, wie Ihr nur finden könnt. Sie sollen es sich zweimal überlegen, bevor sie unseren Konflikt mit der Horde ausnützen, um uns in den Rücken zu fallen.", sourceObjective = "Tötet 12 Huscarls der Drachenschinder und kehrt anschließend zu Förster Drach in der Ammertannhütte zurück.", completion = "Gut gemacht, {name}. Nun müssen wir die Sache nur noch zu Ende führen und uns den Vorteil zu Nutze machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12224] = { id = 12224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Vorposten der Kor'kron!", description = "Gut gemacht, <Bruder/Schwester>. Ihr habt Euch allen Herausforderungen wie ein Champion der Horde gestellt: habt die verseuchten Anub'ar von Azjol-Nerub unter Euren Füßen zerquetscht! - habt die mutigen und mächtigen Taunka zu neuen Mitgliedern der Horde gemacht! - habt unsere neue Superwaffe gegen die Geißel getestet und perfektioniert!\n\nDie Zeit ist nun reif, der Moment ist gekommen: Unsere Elitesoldaten an der Pforte des Zorns brauchen Euch. Der Sohn von Saurfang im Vorposten der Kor'kron erwartet Eure Ankunft. Geht jetzt - auf nach Nordosten zur Pforte des Zorns.", sourceObjective = "Meldet Euch bei Saurfang dem Jüngeren im Vorposten der Kor'kron.", completion = "Lok'tar Ogar! Ich habe schon viel von Euch gehört, {name}. Die Narben aus Euren Schlachten sind tief - ein Zeichen Eurer Hingabe und Macht!\n\nDa der Lichkönig unsere West- und Ostflanke vernichtend geschlagen hat, bleibt nur noch unsere Streitmacht an der Pforte des Zorns übrig. Jeden Tag gewinnen wir an Boden und schon bald werden wir durch diesen Wall brechen und zur Eiskrone gelangen!\n\nSobald den Skelettdrachen Einhalt geboten wurde, werden Hochlord Fordragon und ich ins Feld ziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12225] = { id = 12225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mmm... Bernsteinsamen!", description = "Euer Magen knurrt, als der starke Geruch herzhafter Nüsse Eure Aufmerksamkeit auf den mit Samen gefüllten Eimer zieht.\n\nIrgendeine aufmerksame Seele hat diese Gratisleckerbissen offensichtlich hier gelassen, um erschöpfte Besucher wieder frisch und munter zu machen. Dankbar tut Ihr Euch an den paar verbliebenen gütlich.\n\nDer Geschmack der Samen enttäuscht nicht. Ihr wollt noch mehr und macht Euch also auf den Weg, um herauszufinden, woher sie kommen...", sourceObjective = "Sprecht mit Förstermeister Anderhol in der Ammertannhütte.", completion = "Ihr habt was getan?!!\n\nDas waren Bernsteinsamen! Die Ausbeute einer ganzen Ernte!\n\nDiese magischen Samen waren womöglich die Antwort auf unsere Essenskrise. Ihr werdet das wieder richten, {name}, das könnt Ihr mir glauben!", sourceObjectiveStatus = "unverified-source-field" }
quests[12226] = { id = 12226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wieder raus damit", description = "Wir müssen schnell handeln, {race}! Wir können es nicht riskieren, dass diese wertvollen Samen vollständig verdaut werden. Sie müssen raus, und zwar JETZT!\n\nBesorgt ein paar Schwarzwurzeln vom Flussufer westlich von hier und ich werde Euch ein Abführmittel zubereiten, das die Sache ins Rollen bringen sollte.\n\nBeeilt Euch! Und denkt dran, Ihr habt Euch das selbst eingebrockt...", sourceObjective = "Anderhol bei der Ammertannhütte möchte, dass Ihr ihm 5 Schwarzwurzelstrünke bringt.", progress = "Habt Ihr die Schwarzwurzel gefunden?", completion = "Mit denen hier sollte es gut klappen…\n\n<Anderhol bricht geschickt die Strünke auf und sammelt die austretende Flüssigkeit in einer kleinen Phiole.>\n\nSo, und jetzt zur Sache.", sourceObjectiveStatus = "unverified-source-field" }
quests[12227] = { id = 12227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tut Eure Pflicht", description = "In Ordnung, {race}. Hier ist der Saft.\n\nDie Wirkung tritt sofort ein, benutzt ihn deshalb erst, wenn Ihr sicher das Plumpsklo erreicht habt.\n\nUnd jetzt besorgt mir diese Samen!", sourceObjective = "Anderhol bei der Ammertannhütte möchte, dass Ihr Anderhols Karussellstöffsche nehmt und das nahegelegene Plumpsklo aufsucht, um die teilweise verarbeiteten Bernsteinsamen zurückzuholen.", progress = "Na, habt Ihr diese Samen für mich, {race}?", completion = "Nun, {name}? Alles gut rausgekommen?\n\nHmm, sieht so aus, als hätten wir sie gerade noch rechtzeitig retten können…", sourceObjectiveStatus = "unverified-source-field" }
quests[12229] = { id = 12229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine mögliche Verbindung", description = "Vor nicht allzu langer Zeit haben wir eine Expedition in den Osten entsandt, wo sie von wahnsinnigen Furbolgs angegriffen wurde. Einer der Überlebenden beschrieb uns, wie er einen von ihnen erschlug und aus dessen Körper eine dunkle, schleimige Substanz austrat.\n\nTausende von Jahren waren die Furbolgs in dieser Gegend friedlich. Es ist möglich, dass eine Verbindung besteht zwischen dem Verhalten der Furbolgs und der dunklen Energie, die wir zuvor entdeckt haben.\n\nBringt mir ein paar Proben des Furbolgbluts. Ihr findet sie im Osten am Schrein des Grollfangs und am Schrein des Herzbluts.", sourceObjective = "Windseherin Grauhorn in der Burg Siegeswall möchte, dass Ihr 8 Proben des Bluts eines wahnsinnigen Furbolgs von den Furbolgs am Schrein des Herzbluts und am Schrein des Grollfangs sammelt.", progress = "Habt Ihr die Blutproben, {name}?", completion = "Dieses Blut scheint auf dieselbe Art verdorben zu sein wie der Schleim, den Ihr zuvor gesammelt habt… Dies lässt nichts Gutes erahnen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12230] = { id = 12230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von den Belagerungsschmieden klauen", description = "Ich bin mit der Zerstörung der Ballisten des Scharlachroten Ansturms beauftragt worden. Unglücklicherweise sind die Apotheker und ich über die Verteilung der uns gegebenen Ressourcen uneins, also steht mir nichts zur Verfügung, mit dem ich sie zerstören könnte!\n\nGen Nordosten liegen die Aasfelder. Die dortigen Belagerungsschmiede der Geißel bei ihren Schmieden und Fleischwagen sind so etwas wie Meister der Verwüstung.\n\nDoch zum Glück lassen sie ihre Bomben einfach so herumliegen.\n\nIch möchte, dass Ihr mir das Zeug bringt; vom Boden oder von den Schmieden selbst - ist mir egal.", sourceObjective = "Todeswache Molder in Gallgrimm möchte, dass Ihr 6 Bomben des Belagerungsschmiedes beschafft.", progress = "Man sollte doch meinen, dass sie mich ihre Seuchenverbreiter benutzen lassen würden... damit ich sie vielleicht mit irgendwas Gefährlichem beladen und die Ballisten zerstören könnte.\n\nAber nein, nein... sie meinen, dass die nur für Spezialmissionen gedacht seien.\n\nWas auch immer!", completion = "<Die Todeswache reibt sich vor Vorfreude die Hände.>\n\nAusgezeichnet. Ihr Verlust ist mein... ähhm... ist unser Gewinn!\n\nIhr hattet auf dem Weg hierher doch keine Probleme mit den Dingern, oder? Einige von denen sehen ziemlich instabil aus. Ich mag vielleicht untot sein, doch meine Existenz schätze ich allemal!", sourceObjectiveStatus = "unverified-source-field" }
quests[12231] = { id = 12231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jungen des Bärengottes", description = "Es ist möglich, dass die Furbolgs von den Grizzlyhügeln demselben Verderben unterliegen, das schon Vordrassil plagte. In letzter Zeit waren sie, nach Jahren der friedlichen Koexistenz, in einen tödlichen Stammeskrieg verwickelt.\n\nDie Schreine, die sie im Osten bewachen, sind das Zuhause von Ursocs Jungen.\n\nSollte die Verderbnis auch die Furbolgs betreffen, so ist es möglich, dass Kodian und Orsonn aufgrund ihrer Abstammung unversehrt geblieben sind.\n\nSollte dies der Fall sein, so findet sie und hört, was sie zu sagen haben.", sourceObjective = "Windseherin Grauhorn in der Burg Siegeswall möchte, dass Ihr mit Orsonn am Schrein des Grollfangs und Kodian am Schrein des Herzbluts sprecht.", progress = "Habt Ihr schon mit Ursocs Kindern gesprochen, {name}?", completion = "Ursocs Kinder sind weise. Ihre Worte erklären viel von dem, was wir bisher gesehen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12232] = { id = 12232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombardiert die Ballisten", description = "Zu guter Letzt bietet sich uns die Chance, ihre Belagerungsmaschinen anzugreifen! Vermasselt es nicht.\n\nWar nur Spaß - nur ein klein wenig.\n\n{class}, nehmt Neuherdweilers Ballisten mit diesen Bomben unter Beschuss.\n\nWir werden der Königlichen Apothekervereinigung zeigen, wie es auf die altmodische Art und Weise gemacht wird - ohne Gebräue!", sourceObjective = "Todeswache Molder in Gallgrimm möchte, dass Ihr mit den Bomben des Belagerungsschmiedes 5 Ballisten von Neuherdweiler unter Beschuss nehmt.", completion = "Welch freudiger Tag!\n\nDa ich zur Erledigung des Auftrags nicht die Zeit und Mittel der Apotheker in Anspruch genommen habe, ist mir die Aufmerksamkeit des Hochexekutors sicher!\n\nIch kann nämlich um die Ecke denken - das ist meine größte Stärke. Ja, ja, Ihr hattet dabei natürlich auch ein Händchen im Spiel.\n\nHier, wenn ich Euch etwas gebe, versprecht Ihr mir dann, nichts von Eurem Zutun zu erwähnen?", sourceObjectiveStatus = "unverified-source-field" }
quests[12233] = { id = 12233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Samen aussäen", description = "Nein, nein... Behaltet sie.\n\nIhr habt doch nicht ernsthaft erwartet, dass ich sie nach all dem an mich nehme, oder?\n\nIhr macht folgendes..." }
quests[12234] = { id = 12234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das muss ich wissen", description = "Ich muss wissen, was in Neuherdweiler los ist.\n\nIch möchte, dass Ihr ihre Tagesübersicht stehlt, damit ich genau das herausfinden kann.\n\nBegebt Euch nach Süden. Die Pläne sollten sich in der Abtei, der Kaserne und auf dem Strand befinden. Sucht und findet sie!\n\nUnd nur für den Fall, dass Ihr Euch nicht auskennen solltet. Die Kaserne ist das große Gebäude gleich neben der Schmiede.", sourceObjective = "Spionagemeisterin Repine möchte, dass Ihr die \"Tagesübersicht des Scharlachroten Ansturms: Abtei\", \"Tagesübersicht des Scharlachroten Ansturms: Kaserne\" und die \"Tagesübersicht des Scharlachroten Ansturms: Strand\" stehlt.", progress = "Wenn Ihr zu lange braucht, dann werden sich ihre Pläne ändern und wir müssen wieder von vorne anfangen.\n\nLasst Euch nicht zu viel Zeit!", completion = "Nun, worauf wartet Ihr noch, {race}? Gebt sie schon her!", sourceObjectiveStatus = "unverified-source-field" }
quests[12235] = { id = 12235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naxxramas und der Fall von Wintergarde", description = "Lord Fordragon hat bei der Pforte des Zorns einen vernichtenden Angriff gegen Arthas' Truppen eingeleitet. Als Antwort auf diesen Affront hat Arthas Naxxramas in den Kampf gegen uns geschickt. Während Kel'Thuzad sich in der schwebenden Zitadelle versteckt hält, wird Wintergarde von seinem Feldkommandanten Thel'zan belagert. Das untere Dorf ist bereits verloren und die Chance, Überlebende aus den Ruinen zu bergen, schwindet von Minute zu Minute.\n\nWir müssen schnell handeln! Meldet Euch umgehend bei Greifenkommandant Urik an der Greifenstation! Er wird Euch Flügel verleihen.\n\nVerlasst mich nun!", sourceObjective = "Sprecht mit dem Greifenkommandanten Urik an der Greifenstation in der Feste Wintergarde.", completion = "<Urik deutet auf einen Greifen.>\n\nHabt Ihr jemals schon einen von denen hier geritten? Es ist ganz einfach, {class}. Schwingt Euch einfach auf den Sattel und sagt ihm, wohin er fliegen soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[12236] = { id = 12236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursoc, der Bärengott", description = "Der Augenblick ist gekommen, {name}. Nun werden wir sehen, ob unsere Anstrengungen Früchte tragen oder nicht.\n\nNehmt diese Asche und sucht den Furbolg Tur Wutpranke, von dem Kodian Euch erzählt hat. Er hält sich in der Nähe von Ursocs Höhle auf, die Ihr nördlich des Grauschlunds findet.\n\nÜberzeugt Tur, Euch zu helfen, denn Ihr werdet alle Hilfe brauchen, die Ihr kriegen könnt.\n\nSobald Ihr den Bärengott bezwungen habt, streut diese Asche über seinen Körper.\n\nSelbst wenn seine weltliche Hülle zerstört ist, muss sein Geist gerettet werden.", sourceObjective = "Windseherin Grauhorn in Burg Siegeswall möchte, dass Ihr Tur Wutpranke in der Nähe von Ursocs Höhle findet und Ursoc mit seiner Hilfe besiegt. Streut die geläuterte Asche von Vordrassil auf Ursocs Leiche, nachdem Ihr ihn getötet habt.", completion = "<Die Druidin sieht blass aus und ihre Augen starren an Euch vorbei. Sie hat anscheinend auf Eure Rückkehr gewartet und ein Paket für Euch hingestellt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12237] = { id = 12237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug des Verteidigers von Wintergarde", description = "Mit dieser Pfeife könnt Ihr einen Greifen von Wintergarde zu Euch rufen. Steigt anschließend auf, macht Euch auf den Weg nach Südosten zu den Ruinen des Dorfs Wintergarde, jetzt Aasfelder genannt, und haltet dort nach hilflosen Dorfbewohnern von Wintergarde Ausschau. Fliegt nah an sie heran, wenn Ihr einen gesichtet habt, hebt sie mithilfe des Greifs vom Boden auf und fliegt anschließend mit dem Geretteten hierher zur Greifenstation zurück.\n\nDie Diener der Geißel sind überall in der Gegend verstreut, also müsst Ihr auf der Hut sein, {class}. Viel Glück!", sourceObjective = "Rettet 10 hilflose Dorfbewohner von Wintergarde und kehrt anschließend zum Greifenkommandanten Urik in Wintergarde zurück.", progress = "Beeilt Euch, {name}! Ihr müsst die Hilflosen Dorfbewohner befreien!", completion = "Bemerkenswerte Arbeit, {name}! Jetzt, da unsere Bürger wieder hier sind, können wir diese Festung wieder auf Vordermann bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12238] = { id = 12238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Drak'Tharons", description = "Die Zeit is' endlich gekommen, <guter Freund/gute Freundin>.\n\nBald wird Drak'Tharon von den verdorb'nen Untoten gereinigt und wieder ihrer ursprünglichen noblen Aufgabe unterstellt werden. Meine Seele wird Frieden finden, und als Belohnung für deine Hilfe werd'n dir die wertvollsten Schätze der Feste zur Verfügung steh'n, Mann!\n\nDie Feste wird zu 'ner heiligen Ziggurat. Sobald du die Spitze erreicht hast, musste mich ein letztes Mal beschwör'n, und ich führ' das Ritual durch.\n\nAber mich zu ruf'n, Mann, wird einiges kosten. Du musst das Mojo von den Überlebenden der Feste sammeln.", sourceObjective = "Drakuru möchte, dass Ihr Drakurus Elixier an seinem Kohlenbecken innerhalb Drak'Tharons benutzt. Um das Elixier dort benutzen zu können, benötigt Ihr 5 Ausdauermojos.", completion = "Wir ham' großes geleistet, Mann! Un' das is' nur der Anfang…\n\nSuch mich in Zul'Drak auf, wenn die Zeit reif is'.\n\nEs gibt 'nen Krieg zu gewinnen, Mann!", sourceObjectiveStatus = "unverified-source-field" }
quests[12239] = { id = 12239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Spion in Neuherdweiler", description = "Ich habe eine meiner Spioninnen beim Scharlachroten Ansturm sitzen und möchte, dass ihr diese Tagesübersicht überbracht wird, damit sie die nächste Phase unseres Angriffes planen kann.\n\nSie wird Agentin Skully genannt und ist magisch verkleidet, um wie die Totengräberin des Ansturms auszusehen.\n\nHier, bringt Ihr dieses Schreiben und macht, was sie von Euch verlangt. Ihr findet den Friedhof gleich neben der Abtei.", sourceObjective = "Liefert die Tagesübersicht des Scharlachroten Ansturms bei Agentin Skully in Neuherdweiler ab.", progress = "<Die Agentin mustert Euch von Kopf bis Fuß und gibt Euch ein Zeichen, dass Ihr zu ihr kommen sollt.>\n\nLasst mich bloß nicht auffliegen, {class}!", completion = "Ihr habt Nachricht von der Spionagemeisterin?\n\n<Die Agentin vergewissert sich, dass niemand zusieht, und legt die Schaufel ab.>\n\nLasst mich diese Pläne einmal sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12240] = { id = 12240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Mittel zum Zweck", description = "Mit der letzten Lieferung habe ich von meiner Schwester am Bollwerk ein paar Fässer mit Termiten geschickt bekommen. Sie werden bei dem, was ich mit Euch vorhabe, nützlich sein, denke ich.\n\nDie Abholzungsarbeiten bei Neuherdweiler sind uns ein Dorn im Auge, doch bisweilen haben wir es noch nicht geschafft, jemandem Zugang zu verschaffen, um ihren Vorarbeiter auszuschalten.\n\nIch denke jedoch, dass er mit Sicherheit angerannt käme, wenn Ihr diese Termiten auf seine kostbaren Holzarbeiten loslassen würdet.\n\nBereit, ihn auszuschalten, {class}?", sourceObjective = "Apothekerin Vicky Levine in Gallgrimm möchte, dass Ihr mithilfe der Termiten der LevinefamilieGroßknecht Kaleiki hervorlockt und ihn tötet.", completion = "Ich habe gewusst, dass meine Schwester uns nicht im Stich lassen würde.\n\nGut gemacht, {name}. Das Sägewerk des Scharlachroten Ansturms wird eine ganze Weile außer Betrieb sein, was die Herstellung neuer Bauwerke oder Ballisten erst einmal lahmlegt.\n\nIch danke Euch, dass Ihr mir dabei geholfen habt, meinem Familiennamen gerecht zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12241] = { id = 12241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstört den Schössling", description = "Die Taten der Furbolgs müssen rückgängig gemacht werden, {name}. Der beste aller Vorsätze zählt nicht viel, wenn das Resultat von solch starker Verderbnis durchzogen ist.\n\nDer Schössling muss zerstört werden, da er die Quelle dieses finsteren Einflusses ist. Nehmt diese Fackel und benutzt sie, um den verderbten Schössling in Flammen aufgehen zu lassen, und bringt mir dann seine Asche.\n\nEinmal durch das Feuer gereinigt, werde ich alle Macht, die ich habe, einsetzen, um den Schatten, der auf der Asche liegt, zu beseitigen. Ihr werdet sie brauchen, um Ursoc von der bösen Macht zu befreien, die ihn beherrscht.", sourceObjective = "Windseherin Grauhorn in Burg Siegeswall möchte, dass Ihr die grüne Fackel nehmt und sie benutzt, um Vordrassils Schössling zu verbrennen. Bringt Vordrassils Asche zurück zu Windseher Grauhorn.", progress = "Habt Ihr die Asche für mich, {name}?", completion = "Ich kann nichts versprechen, {name}. Aber ich werde mein Bestes geben, um sie zu reinigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12242] = { id = 12242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordrassils Samen", description = "Wir müssen dafür sorgen, dass Vordrassil niemals wieder wächst. Die Furbolgs müssen seine Samen eingesammelt haben.\n\nGeht nach Grauschlund in der Mitte der Grizzlyhügel und beschafft alle Samen, die Ihr finden könnt. Ich werde dafür sorgen, dass sie auf jeden Fall vernichtet werden.", sourceObjective = "Windseherin Grauhorn in Burg Siegeswall möchte, dass Ihr nach Grauschlund geht und 8 Samen von Vordrassil beschafft.", progress = "Habt Ihr Vordrassils Samen dabei, {name}?", completion = "Habt Dank, {name}. Ich werde sie dann an mich nehmen.\n\nDie verderbende Macht dieser Samen ist gefährlich. Ich muss sie umgehend zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[12243] = { id = 12243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer auf dem Wasser", description = "Ich hab' noch einen Auftrag für Euch.\n\nIch habe es geschafft, ein wenig der Seuche so zu manipulieren, dass ich daraus mein weltbekanntes brennendes Wasser zusammenbrauen konnte. Ich möchte, dass Ihr damit die Segel der Sündenbabel in Brand steckt!\n\nWerft es vom Dock aus auf die Segel. Die Deckmatrosen werden damit beschäftigt sein, das Feuer zu löschen, was Euch die Gelegenheit bietet, unter Deck zu huschen und an die Seekarten des Kapitäns heranzukommen.\n\nDas Schiff liegt im Hafen des Kreuzzüglers vor Anker, südlich von Neuherdweiler. Die Kapitänskajüte befindet sich auf dem ersten Unterdeck hinter der Treppe.", sourceObjective = "Apothekerin Vicky Levine in Gallgrimm möchte, dass Ihr mithilfe des Feuerwassers des Apothekers die Segel der Sündenbabel in Brand steckt.\n\nGeht unter Deck, während die Deckmatrosen damit beschäftigt sind, das Feuer zu löschen, und sucht nach Kapitän Shelys Seekarten.", progress = "Bitte sagt mir NICHT, dass mein Feuerwasser keine Wirkung auf ihre Segel hatte!\n\nIch hätte rein gar keine Lust, es wieder dort draußen austesten zu müssen.", completion = "Ahhahahahahahahahaha!\n\nOhne ihre Seekarten gibt es für sie kein Entrinnen mehr.\n\nSieht mir nach dem Ende des Scharlachroten Ansturms aus - gerade, als sie richtig in Fahrt kamen. Wie traurig.\n\nHeh.", sourceObjectiveStatus = "unverified-source-field" }
quests[12244] = { id = 12244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schredder reparieren", description = "Hört mal, Freundchen. Wieso krempelt Ihr nicht Eure Ärmel hoch und schnappt Euch 'nen Schraubenschlüssel? Gibt viel zu tun! Diese Schredder müssen aufgemöbelt und runter zur Venturebucht geschickt werden, und das schon gestern...\n\nKein Schraubenschlüssel? Und zu was seid Ihr dann gut? Könnt dann genauso gut mit dem Rest der Blechköpfe runtergehen und mit der Horde spielen!\n\nSolang' könntet Ihr auch versuchen, 'n paar von den kaputten Schreddern hier hoch zur Reparatur zu bringen. Seid vorsichtig! Sie sind in einem ziemlich miesen Zustand.", sourceObjective = "Synipus beim Holzfällerposten Blauhimmel möchte, dass Ihr ihm 3 kaputte Schredder bringt.", completion = "<Synipus pfeift.>\n\nOh, was für 'ne Schönheit! Wir richten sie gleich wieder her!\n\nWenn Ihr nix zu tun habt, dann sprecht mit Gordun und lasst Euch runter zur Venturebucht bringen. Die brauchen da sicher 'ne helfende Hand.\n\nOh, und solange Ihr dort seid, benutzt doch diese Schlüssel an 'nem runderneuerten Schredder. Wartet, bis Ihr seht, was die Babys anrichten, wenn sie mal repariert sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[12245] = { id = 12245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Gnade für Gefangene", description = "Wir haben noch mehr Narren für Euch, die Ihr umbringen müsst.\n\nMeine Männer berichten mir, dass einige unserer guten Bürger es geschafft haben, dem Scharlachroten Ansturm in die Hände zu fallen.\n\nDas kann so nicht angehen.\n\nGeht zurück nach Neuherdweiler und tötet Todeswache Schneider, Chefschreiber Kinnedius, Ingenieur Hindermann und Kanzler Amai.\n\nBerichten nach zu urteilen, sind sie über das gesamte Gebiet verteilt und werden in Käfigen festgehalten; doch auf sie wartet zweifellos die Folter.\n\nSprecht mit ihnen und tötet sie dann!", sourceObjective = "Spionagemeisterin Repine hat Euch gebeten, Todeswache Schneider, Chefschreiber Kinnedius, Ingenieur Hindermann und Kanzler Amai zu töten.\n\nFalls Ihr Erfolg habt, berichtet Hochexekutor Zürner in Gallgrimm davon.", completion = "Was? Ihr habt angenommen, wir würden Euch ausschicken, um sie zu retten?\n\nWarum sollten wir das denn tun, wenn sich bereits gezeigt hat, dass sie sich ohne weiteres gefangen nehmen lassen?\n\nNordend ist ein kalter Ort, junger {name}. Ich schlage vor, Ihr gewöhnt Euch dran.", sourceObjectiveStatus = "unverified-source-field" }
quests[12246] = { id = 12246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine mögliche Verbindung", description = "Die Furbolgs, die östlich von hier leben, sind aggressiver und bestialischer als die, an die wir gewöhnt sind. Unsere Streitkräfte sind mehr als einmal mit ihnen aneinandergeraten und die Überlebenden sprechen immer von einer dunklen, schleimigen Substanz, die aus ihren Körpern tropft.\n\nIhr Zustand könnte mit den Verunreinigungen zu tun haben, die wir auf Vordrassils Überresten gefunden haben.\n\nBringt mir Proben des Furbolgbluts. Ihr findet sie am Schrein des Grollfangs und am Schrein des Herzbluts, weit im Osten.", sourceObjective = "Hierophant Thayreen bei der Ammertannhütte möchte, dass Ihr am Schrein des Grollfangs und am Schrein des Herzbluts 8 Blutproben von wahnsinnigen Furbolgs sammelt.", progress = "Habt Ihr die Blutproben sammeln können, {name}?", completion = "Die Verderbnis in diesem Blut gleicht der in dem Schleim. Ich habe kein gutes Gefühl bei der Sache.", sourceObjectiveStatus = "unverified-source-field" }
quests[12247] = { id = 12247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kinder von Ursoc", description = "Die Furbolgs der Grizzlyhügel sind von einer Art Verderbnis befallen, so viel steht fest. Nun ist ein Stammeskrieg zwischen ihnen ausgebrochen, nachdem sie jahrelang friedlich miteinander gelebt hatten.\n\nWas wir noch herausfinden müssen, ist, ob die Bären, die sie als Götter verehren, auch der Verderbnis anheim gefallen sind.\n\nUrsocs zwei Kinder, Orsonn und Kodian, halten sich im Schrein des Herzensblutes und des Grollfangs auf, süd- und südöstlich von Grauschlund.\n\nSeht nach, ob sie mit Euch über das, was dort geschehen ist, sprechen werden.", sourceObjective = "Hierophant Thayreen bei der Ammertannhütte möchte, dass Ihr mit Orsonn im Schrein des Grollfangs und mit Kodian im Schrein des Herzensblutes sprecht.", completion = "Ursocs Kinder sind weise. Ihre Worte erklären einiges von dem, was wir gesehen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12248] = { id = 12248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordrassils Schössling", description = "Die Druiden von einst scheinen guten Grund gehabt zu haben, Vordrassil zu zerstören. Wir können nicht zulassen, dass die Furbolgs ihn wieder gedeihen lassen.\n\nAuf der anderen Seite hängt die Rettung von Ursocs Geist von der Magie ab, die in diesem Schössling steckt.\n\nNehmt diese Fackel und steckt mit ihrer Hilfe den Baum in Brand. Er befindet sich in der Mitte von Grauschlund im Inneren von Vordrassils altem Baumstamm. Bringt mir die Asche von Vordrassil. Ich hoffe, dass, sobald er vom Feuer gereinigt wurde, wir mithilfe seiner Magie Ursocs Geist von seiner Dunkelheit läutern können.", sourceObjective = "Hierophant Thayreen in der Ammertannhütte möchte, dass Ihr mithilfe der grünen Fackel Vordrassils Schössling anzündet und ihr die daraus entstehende Asche von Vordrassil bringt.", progress = "Habt Ihr mir die Asche gebracht, {name}?", completion = "Ja! Vordrassils Magie ist erhalten geblieben und steckt noch immer in dieser Asche. Vielleicht gibt es doch noch Hoffnung für Ursoc.", sourceObjectiveStatus = "unverified-source-field" }
quests[12249] = { id = 12249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursoc, der Bärengott", description = "Es ist Zeit, {name}. Nehmt diese Asche und sucht nach dem Furbolg, von dem Kodian gesprochen hat. Wenn er sich auf die Suche nach Ursoc gemacht hat, dann wird er in der Nähe seines Baus nördlich von Grauschlund sein.\n\nIhr werdet seine Hilfe benötigen. Alleine werdet Ihr Ursoc nicht besiegen können.\n\nBenutzt die Asche, um seinen Geist zu läutern, sobald Ihr Ursoc besiegt habt. Erst dann werden wir wissen, ob unsere Mühen umsonst waren oder nicht.", sourceObjective = "Hierophant Thayreen bei der Ammertannhütte möchte, dass Ihr Tur Wutpranke in der Nähe von Ursocs Höhle aufsucht und mit seiner Hilfe Ursoc besiegt. Streut anschließend die geläuterte Asche von Vordrassil auf Ursocs Leiche.", completion = "<Die Druidin sieht blass aus und ihre Augen starren an Euch vorbei. Sie hat anscheinend auf Eure Rückkehr gewartet und ein Packet für Euch hingestellt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12250] = { id = 12250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordrassils Samen", description = "Wir können nicht zulassen, dass Vordrassil wieder wächst. Wenn die Furbolg es einmal geschafft haben, ihn wachsen zu lassen, dann können sie es wieder tun.\n\nGeht zum Grauschlund im Zentrum der Grizzlyhügel und besorgt Vordrassils Samen. Ich werde dann sicherstellen, dass sie ein für allemal verschwinden.", sourceObjective = "Hierophant Thayreen in der Ammertannhütte will, dass Ihr zum Grauschlund geht und 8 Samen von Vordrassil besorgt.", progress = "Habt Ihr die Samen, {name}?", completion = "Danke, {name}. Ich werde sie an mich nehmen.\n\nDie verderbende Macht dieser Samen ist äußerst gefährlich. Ich muss sie sofort zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[12251] = { id = 12251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zum Oberkommandanten zurück", description = "{name}, Ihr müsst umgehend zum Oberkommandanten Halford Wyrmbann zurückkehren. Lasst ihn wissen, dass unsere Mission ein voller Erfolg war und dass die wenigen verbliebenen Dorfbewohner, die gerettet wurden, wieder bei der Arbeit sind.", sourceObjective = "Sprecht mit Oberkommandant Halford Wyrmbann in Wintergarde in der Drachenöde.", completion = "<Halford salutiert vor Euch.>\n\nDas Stadtvolk ist wieder bei der Arbeit? Jetzt schon? Ausgezeichnet, Soldat! Wir werden diese Stadt im Handumdrehen wieder aufgebaut und befestigt haben. Nicht mehr lange und unsere Truppen werden einsatzbereit sein und Lord Fordragon bei seinem Kampf an der Pforte des Zorns zur Seite stehen.\n\nIch bin natürlich etwas zu voreilig - bevor wir nämlich überhaupt erst daran denken können, Euch zu Bolvars Hilfe zu schicken, muss hier noch einiges getan werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12252] = { id = 12252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foltert den Folterer", description = "Genug! Ich möchte, dass Ihr den Qualen meines Volkes ein Ende setzt!\n\nDer Folterer des Scharlachroten Ansturms, Alphonse, erzwingt auf die blutigste Art und Weise Informationen von allen, die von diesen Scheusalen gefangen genommen werden! Ich muss wissen, was sie wissen.\n\nAus gewissen Quellen habe ich erfahren, dass er sich im Keller ihrer Kaserne, die sich gleich neben der Schmiede befindet, eingerichtet hat.\n\nIch werde Euch mein eigenes Brandeisen ausleihen, damit die Arbeit auch richtig erledigt wird.\n\nFindet ihn und beschafft Euch die Informationen.", sourceObjective = "Hochexekutor Zürner in Gallgrimm möchte, dass Ihr Folterer Alphonse fünfmal mit dem Brandeisen bearbeitet und die Informationen aus ihm herausquetscht. Anschließend sollt Ihr ihn töten.", completion = "Sie wussten das alles? Und wer zum Teufel ist dieser Großadmiral Westwind, den er erwähnt hat?!\n\n<Der Hochexekutor murmelt vor sich hin und meint, dass er Überraschungen nicht ausstehen kann.>\n\nGut zu wissen. Besser das, als nur Vermutungen anzustellen. Ich hoffe, dass Ihr Euer... ähm, ich meine, dass Ihr mein Mal hinterlassen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12253] = { id = 12253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung vom Marktplatz", description = "Gleich diesen Weg entlang befindet sich der Dorfplatz von Wintergarde. Einst war dies ein geschäftiger Ort für die Bürger von Wintergarde, doch nun ist aus ihm ein Kampfschauplatz geworden und wimmelt nur so von blutrünstigen Spuken, die sich um jeden Preis an den Lebenden rächen wollen.\n\nIn den Gebäuden um den Platz herum befinden sich gefangene Dorfbewohner, die unbedingt befreit werden müssen! Dies mag jetzt vielleicht etwas viel verlangt sein, {name}, doch Ihr seid <der einzige Soldat, den/die einzige Soldatin> die; ich entbehren kann. Befreit unsere Leute. Folgt diesem Pfad zum Dorfplatz, geht zu den Häusern und tötet alles, was sich Euch in den Weg stellt! Kehrt wieder zu mir zurück, falls Ihr überleben solltet.", sourceObjective = "Oberkommandant Halford Wyrmbann in der Feste Wintergarde in der Drachenöde möchte, dass Ihr 6 gefangene Dorfbewohner von Wintergarde befreit.", completion = "<Halford spricht ein Gebet für die Verstorbenen.>\n\nIhr verrichtet des Lichtes Arbeit, {name}.\n\nIch fürchte, dass unsere Arbeit gerade erst begonnen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[12254] = { id = 12254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohne Gebet", description = "Diese Pläne lassen darauf schließen, dass etwas kurz bevorsteht.\n\nDoch zuerst ist da noch die Sache mit diesem seltsamen Schutz, über den die Truppen des Ansturms verfügen. Wenn Gallgrimm ein für alle Mal mit ihnen abrechnen will, dann müssen wir den Verantwortlichen dafür finden und ihn ausschalten.\n\nIch habe bemerkt, dass der Bischof in der Kapelle gegenüber dem Sägewerk auf der anderen Seite von Neuherdweiler häufiger als sonst den Truppen seinen Segen erteilt. Tötet ihn und nehmt ihm sein Gebetsbuch ab.\n\nVielleicht wird es uns einen Hinweis geben.", sourceObjective = "Agentin Skully in Neuherdweiler möchte, dass Ihr das Gebetsbuch von Bischof Straß besorgt.", progress = "Ihr habt das Gebetsbuch des Bischofs? Habt Ihr darin auch irgendetwas Ungewöhnliches gefunden?", completion = "Ihr meint also, dass auf der letzten Seite des Buches ein neuer Segen geschrieben steht?\n\n<Die Agentin blickt Euch über die Schulter, als Ihr die letzte Seite aufschlagt.>\n\nVerdammt nochmal! Das ist die Handschrift des Hochabtes! Ich würde Euer Leben darauf verwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12255] = { id = 12255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Than von Voldrune", description = "Nun, da Ihr die flammenerfüllten Talismane in Händen haltet und die Verteidigung von Voldrune geschwächt habt, können wir einen Schlag gegen ihren Anführer ausführen, den Than Torvald Eriksson.\n\nSein Lieblingsreittier ist ein nicht zu bändigender Protodrache, den er Flammenbringer nennt. Er wird im westlichen Teil von Voldrune in Ketten gehalten, doch mithilfe der Talismane solltet Ihr ihn lange genug beherrschen können, um ihn gegen den Than einzusetzen.\n\nDer Than hält sich irgendwo oben auf den Türmen von Voldrune auf. Sucht dort nach ihm, sobald Ihr Flammenbringer unter Eure Kontrolle gebracht habt, und zeigt keine Gnade.", sourceObjective = "Besiegt mithilfe von Flammenbringer den Than Torvald Eriksson und meldet Euch anschließend bei Förster Drach bei der Ammertannhütte.", completion = "Gute Arbeit, {name}. Ich bezweifle, dass irgendeiner der Förster sich an dem Protodrachen hätte versuchen wollen, doch wir konnten es einfach nicht zulassen, dass die Drachenschinder eine Basis in den Grizzlyhügeln errichten. Wenn es mit der Horde nur auch so leicht wäre...", sourceObjectiveStatus = "unverified-source-field" }
quests[12256] = { id = 12256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnis der Flammenbinder", description = "Während die feige Allianz unsere Stellungen angreift, bereiten sich die Vrykul der Drachenschinder im Außenposten Voldrune gen Südosten auf den Krieg vor. Die Vrykul sind bei Weitem nicht der stärkste Feind, dem wir uns hier gegenübersehen, doch wir müssen sie aus dem Weg räumen, bevor sie eine wirkliche Bedrohung für uns darstellen.\n\nDen stärksten ihrer Krieger ist es gestattet, auf schlecht trainierten Protodrachen in die Schlacht zu reiten. Um die Bestien zu kontrollieren, erschaffen die Flammenbinder mächtige Talismane. Ihr werdet sie töten und die Talismane an Euch bringen müssen, damit unser Plan funktioniert.", sourceObjective = "Bringt 3 flammenerfüllte Talismane zu Unteroffizier Nazgrim in Burg Siegeswall.", progress = "Habt Ihr diese Talismane dabei?", completion = "Die Macht der Talismane bewirkt, dass die Drachen keine andere Wahl haben, als Euren Befehlen zu gehorchen. Das Schicksal des Thans ist besiegelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12257] = { id = 12257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Demonstration der Stärke", description = "Das Vrykuldorf Voldrune im Südosten bereitet sich auf den Krieg vor. Der Than von Voldrune kann keine große Armee in die Schlacht führen, aber durch unsere reduzierte Truppenstärke sind wir dennoch in Gefahr.\n\nWir können nicht riskieren, einem Angriff ausgesetzt zu werden, also müssen wir die Initiative ergreifen. Wenn Ihr <ein wahrer/eine wahre:c> {class} der Horde seid, werdet Ihr auf eine Chance brennen, Eure Stärke zu demonstrieren.\n\nMäht die Huscarls nieder und beweist diesem Drachenschinderklan, dass mit der Horde nicht zu spaßen ist!", sourceObjective = "Tötet 12 Huscarls der Drachenschinder und kehrt zu Unteroffizier Nazgrim am Siegeswall zurück.", completion = "Ihr habt getan, worum ich Euch gebeten habe. Jetzt sind die Drachenschinder in der Defensive und es ist bald an der Zeit, sich um ihren Anführer zu kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[12258] = { id = 12258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal der Toten", description = "Der Dorfplatz am Ende dieses Weges wimmelt nur so von untoten Bürgern von Wintergarde! Unsere eigene Krypta versorgt die Geißel mit einer schier endlosen Zahl Krieger, die sie dann auf uns hetzen kann. Zeigt ihnen jedoch keine Gnade, {name}. Einst waren sie Sterbliche wie wir, des Mitgefühls und Denkens fähig, doch jetzt sind aus ihnen wütende Untote geworden, die nur ein Ziel kennen: unsere völlige Zerstörung.\n\nGeht zum Dorfplatz, wenn Ihr den Mut dazu habt, und befördert die rachsüchtigen Spuke wieder zu ihrem Schöpfer zurück. Sorgt dafür, dass sie in Frieden ruhen können.", sourceObjective = "Kommandantin Lynore Windstreich in der Feste Wintergarde in der Drachenöde möchte, dass Ihr 15 rachsüchtige Spuke tötet.", completion = "Vielleicht werden sie jetzt in Frieden ruhen können, da es ihren Geistern nicht mehr verwehrt ist, zum Licht emporzusteigen.\n\nMeine Gedanken und Gebete gehen nun an Lord Fordragon und unsere Streitkräfte an der Pforte des Zorns. Wir müssen hier ausharren, auch wenn ihnen das vielleicht nur genug Zeit verschaffen wird, um den Lichkönig zu besiegen. Wintergarde darf nicht fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12259] = { id = 12259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Than von Voldrune", description = "Mit den flammenerfüllten Talismanen können wir den Than endlich herausfordern!\n\nSein Lieblingsreittier ist ein wilder Protodrache namens Flammenbringer. Er wird im westlichen Teil Voldrunes in Fesseln gehalten, aber mit der Kraft der Talismane solltet Ihr ihn Eurem Willen unterwerfen und gegen den Than einsetzen können.\n\nSobald Ihr Flammenbringer unter Kontrolle gebracht habt, sucht auf den Turmspitzen von Voldrune nach dem Than, um ihn mit Flammenbringer zu erledigen.", sourceObjective = "Besiegt mithilfe von Flammenbringer Than Torvald Eriksson und meldet Euch anschließend bei Unteroffizier Nazgrim in Burg Siegeswall.", completion = "Die wenigen verbliebenen Drachenschinder wagen es nicht, sich uns nach dem Kampf mit dem Than entgegenzustellen. Kein Erbarmen mit unseren Feinden - das ist der Weg der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[12260] = { id = 12260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die perfekte Heuchelei", description = "Womöglich fragt Ihr Euch, wie ich diese Gestalt aufrechterhalten kann... Ich verwende einen magischen Spiegel, den mir die Spionagemeisterin geliehen hat.\n\nEr hat zwar nur eine gewisse Menge an Energie, doch ich denke, dass genug für uns beide da ist. Hier, nehmt ihn. Ich möchte, dass Ihr Euch mit seiner Hilfe als Rabenpriester des Ansturms ausgebt.\n\nMacht schnell... ich weiß nicht, wie lange ich noch so bezaubernd aussehen werde, wenn Ihr den Spiegel habt.\n\nIhr müsst wissen, dass Eure Verkleidung nicht sofort perfekt sein wird. Idiotensicher ist sie erst dann, wenn ich eine Chance hatte, Euch zu helfen.", sourceObjective = "Agentin Skully in Neuherdweiler möchte, dass Ihr das Abbild eines Rabenpriesters des Ansturms stehlt. Bringt den magischen Spiegel der Banshee wieder zurück, wenn Ihr das getan habt.", progress = "Bitte sagt mir, dass Ihr den Spiegel nicht zerbrochen habt!", completion = "Nicht schlecht, {class}. Nun, da das Abbild des Priesters im Spiegel gefangen ist, hätte ich noch eine andere Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[12261] = { id = 12261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Ausweg", description = "Sie beziehen ihre Macht aus den Knochen meiner toten Brüder...\n\nFür den Kult habe ich nichts übrig, aber ihre Dreistigkeit verblüfft mich. Es wird keine Gnade für sie geben... ich würde ihnen ohnehin keine gewähren, so oder so.\n\nStellt sicher, dass ihnen kein Fluchtweg bleibt, wenn das Schlachten beginnt. Stellt eine zerstörerische Barriere am Ende des Pfades auf, der aus dem Obsidiandrachenschrein hinausführt; dort, wo die Straße in Schnee übergeht. Schützt die Barriere, bis sie vollständig aufgeladen ist.", sourceObjective = "Stellt eine zerstörerische Barriere am Ende des Pfades auf, der aus dem Obsidiandrachenschrein hinausführt; dort, wo die Straße in Schnee übergeht. Schützt die Barriere, bis sie vollständig aufgeladen ist und kehrt dann zu Serinar zurück.", progress = "Habt Ihr die Barriere aufgestellt?", completion = "Exzellent. Sobald sie in Panik fliehen, wird die Barriere dort bereit sein, um ihnen einen freundlichen Abschied zu bereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12262] = { id = 12262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und niemand, der Euch retten wird...", description = "Niemand wird verschont. \n\nDort draußen besudelt dieser Nekrolytenabschaum und seine Skelettdiener mein Land mit seiner Anwesenheit. Schlachtet sie ab, alle.", sourceObjective = "Tötet außerhalb des Obsidiandrachenschreins 6 Nekrolyten der Brennenden Tiefen und 10 glimmende Skelette. Kehrt zu Serinar zurück, sobald Eure Aufgabe abgeschlossen ist.", completion = "Haben sie um ihre jämmerlichen Leben gebettelt? Schwächlinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[12263] = { id = 12263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur die besten Absichten", description = "Der Kult der Verdammten ist nicht nur hier, um die Macht aus toten Drachen zu extrahieren. Ich hege einen Verdacht, was ihre Absichten betrifft. Aber ich brauche Euch, um ihn zu bestätigen.\n\nIch werde Euch das Aussehen dieses toten Nekrolyten verleihen. Dringt in das Innerste der Höhle vor und überprüft ihre Gründe, diesen geheiligten Ort heimzusuchen. Ich werde alles durch Eure Augen beobachten. \n\nSeid vorsichtig, {name}. Die Illusion ist empfindlich, erleidet Ihr Schaden wird sie wahrscheinlich zerbrechen.", sourceObjective = "Wartet, bis Serinar Euch in die Verkleidung eines Nekrolyten der Brennenden Tiefen gehüllt hat. Dringt in die Tiefen des Schlundes von Neltharion vor, um aufzudecken, was den Kult der Verdammten hierher lockt. Kehrt mit Details ihres Vorhabens zu Serinar zurück.", progress = "Diese Pestilenz ermüdet mich.", completion = "Wir sind der schwarze Drachenschwarm. Seit tausenden von Jahren haben wir Chaos und Verwüstung auf Azeroth verbreitet. Der Kult der Verdammten verehrt den Tod - was sie so lieben werden wir ihnen mit Freuden servieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[12264] = { id = 12264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ausmerzen der Verdammten", description = "Die Tiefen der Höhle wimmelten nur so von den Scheusalen der Kultisten. Es gibt nur eine Art, mit solchen Kreaturen fertig zu werden... Ihr wisst, was zu tun ist.", sourceObjective = "Tötet in Neltharions Schlund 3 Nekromanten der Brennenden Tiefen, 6 glimmende Konstrukte und 6 glimmende Spuke. Kehrt dann zu Serinar zurück.", progress = "Ich komme nicht umhin, mich zu fragen, ob sie naiv genug sind, um zu glauben, dass ich es damit bewenden lasse oder ob sie einfach gern getötet werden.", completion = "Ihre Schreie zu hören... zuzusehen, wie das letzte Quäntchen Leben aus ihren erbärmlichen Körpern sickert... so erfrischend, nicht wahr?\n\nIch liebe es.", sourceObjectiveStatus = "unverified-source-field" }
quests[12265] = { id = 12265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schändung der Entweiher", description = "In den Runen, die wir auf dem Weg in die Höhle entdeckt haben, habe ich eine große Ansammlung von Magie gespürt. Mit Spielereien, wie ihnen die Magie zu entziehen, brauchen wir uns nicht abzugeben... zumeist ist die direkte Lösung die Effektivste.\n\nZerstört die Runen... löscht sie aus und stellt sicher, dass der Kult zu der Macht, die er hier angesammelt hat, keinen Zugriff hat.", sourceObjective = "Findet 8 nekromantische Runen, die auf den Boden von Neltharions Schlund gezeichnet wurden und löscht sie aus. Kehrt zu Serinar zurück, sobald die Aufgabe abgeschlossen ist.", completion = "Gut. Es gibt mehr zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[12266] = { id = 12266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kunde der Zerstörung", description = "Ihr könnt nun gehen, {race}.\n\nSagt Yntrige, sie hat ein üppiges Schlachtfest verpasst.", sourceObjective = "Kehrt zum Wyrmruhtempel zurück und lasst Yntrige wissen, dass Serinars Aufgabe abgeschlossen ist.", completion = "Oh, Ihr seid es.\n\nIch hatte gehofft, dass Serinar einfach zurückkehren würde, sobald die Aufgabe erledigt gewesen wäre... Ich nehme mal an, dass er irgendwas gefunden hat, das er töten muss. Er verpasst eine wunderbar chaotische Schlacht!\n\nSeid Ihr noch immer da? Ich bin mit Euch fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[12267] = { id = 12267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharions Flamme", description = "Die Reihen des Kults sind dünner geworden, ein Teil ihrer Macht ist vergangen - es ist Zeit, gegen die Quelle der Verderbnis vorzurücken.\n\nRothin der Verfallende belebt im hinteren Teil der Höhle schwarze Drachen als Magmawyrm wieder. Geht zur Beschwörungskammer und läutert die verbliebenen Knochen auf die einzige Art und Weise, wie man sicherstellen kann, dass niemand je wieder mit ihnen herumspielen wird... mit Feuer.\n\nDie Knochen zu verbrennen wird mit Sicherheit Rothins Aufmerksamkeit erregen - und wenn dem so sein sollte, dann kümmert Euch auch darum, dass er vernichtet wird.\n\nIn der Phiole sollte sich genug magische Kraft befinden, um die Aufgabe zu erledigen.", sourceObjective = "Äschert mit Neltharions Flamme die Beschwörungskammer im hinteren Teil von Neltharions Schlund ein. Tötet Rothin den Verfallenen, nachdem Ihr seine Aufmerksamkeit auf Euch gezogen habt, und kehrt anschließend zu Serinar am Eingang der Höhle zurück.", progress = "Ihr seid ein ziemlich effektives Werkzeug, {class}. Eure Beteiligung an dieser Läuterung wird mit Wohlwollen betrachtet.", completion = "Den Knochen meines Schwarms wurde diese Besudelung erspart. Ihr habt mir gut gedient und sollt dafür angemessen entlohnt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12268] = { id = 12268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzelteile", description = "Bah! Das Ding ist ein einziges Durcheinander!\n\nGoblinische Ingenieurskunst lässt 'ne Menge zu wünschen übrig, das könnt Ihr mir glauben. Schaut Euch das hier nur an! Ein Wunder, dass es überhaupt jemals funktioniert hat.\n\nHelft mir mal, ja? Um dies auch nur ansatzweise zum Laufen zu bringen, muss ich diverse Zahnräder, Winkel und Federn ersetzen. Ihr solltet keine Probleme haben, sie in der Nähe des Sägewerks zu finden.", sourceObjective = "Pipthwak beim Holzfällerposten Blauhimmel möchte, dass Ihr ihm 4 gefalzte Zahnräder, 3 gekerbte Winkel und 2 Hochspannungsfedern bringt.", progress = "Habt Ihr diese Ersatzteile für mich, {class}?", completion = "In der Tat. Nun sollte es hinhauen...\n\nSo, bitte. Ein weiterer Schredder bereit für den Kampf. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12269] = { id = 12269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht in unserer Mine", description = "Wir wurden von dieser verdammten Nekropole völlig überrumpelt! Durch den Überfall haben wir auch die Minen von Wintergarde an den Feind verloren. Und was noch viel schlimmer ist: Kel'Thuzads Akolyten haben die toten Bergarbeiter in Diener der Geißel verwandelt und benutzen sie, um ihre Belagerungsingenieure mit Rohstoffen aus unserer Mine zu versorgen!\n\nIhre Rohstoffquelle muss zum Erliegen kommen und unsere verlorenen Brüder wieder ihre Ruhe finden.\n\nGeht nach Nordosten zu den Minen von Wintergarde im Bereich der Aasfelder und vernichtet die auferstandenen Bergarbeiter. Bringt ihre Ausweise wieder zu mir zurück, damit ich sie als verstorben in unser Register aufnehmen kann.", sourceObjective = "Hochlord Leoric von Zeldig in der Feste Wintergarde in der Drachenöde möchte, dass Ihr 10 Bergarbeiterausweise von Wintergarde beschafft.", progress = "Habt Ihr ihre Ausweise dabei?", completion = "<Leoric nimmt Euch die Ausweise ab.>\n\nIch werde die hier unserem Buchhalter geben und den Familien der Bergarbeiter die schlimmen Neuigkeiten überbringen.\n\nEs gibt noch immer viel zu tun, wenn wir hier und letztendlich an der Pforte des Zorns die Oberhand gewinnen wollen. Lord Fordragon ist auf uns angewiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12270] = { id = 12270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreddert die Allianz", description = "Sperrt die Ohren auf, {class}: Ich brauche diese Schredder! Und genauso wichtig: Ich muss sie von der Allianz fernhalten!\n\nSie haben die Schredder rundum erneuert und setzen sie nun gegen unsere Brüder in der Venturebucht ein. Nun werden wir sie ihre eigene Medizin schmecken lassen!\n\nWenn Ihr einen Schredder da draußen seht, dann schnappt ihn Euch! Wenn Ihr dabei irgendwelchen Allianzlern über den Weg lauft, bringt sie um und schnappt Euch dann den Schredder! Sobald Ihr einen habt, bringt ihn zurück zu mir und wir machen uns an die Arbeit.\n\nWeggetreten!", sourceObjective = "Grekk im Holzfällerlager Blauhimmel möchte, dass Ihr 3 Schredder besorgt und diesen zu ihm zurückkehrt.", progress = "Habt Ihr mir schon diese Schredder geholt, {class}?", completion = "Gute Arbeit, Soldat!\n\nNun nehmt diesen Schlüssel und begebt Euch runter zur Venturebucht. Verwendet einen der runderneuerten Schredder, um Chaos unter unseren Feinden zu verbreiten.\n\nAch ja, wendet Euch an Darrok, wenn Ihr die Abkürzung nehmen wollt!", sourceObjectiveStatus = "unverified-source-field" }
quests[12271] = { id = 12271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rute des Zwangs", description = "Ein Stab fällt aus Alphonses toter Hand. Er ist mit pulsierenden magischen Runen versehen.\n\nHat er damit seine Geständnisse bekommen?\n\nDer Hochexekutor sollte sich das besser einmal ansehen.", sourceObjective = "Liefert den Stab des Folterers bei Hochexekutor Zürner in Gallgrimm ab.", progress = "Habt Ihr diesen Stab dem Folterer abgenommen?", completion = "Alphonse hatte ihn bei sich, meint Ihr? Das ergibt Sinn.\n\nIch habe so etwas früher schon einmal gesehen, als ich noch jünger war, zu der Zeit, als Lordaeron noch bestand und ich als Folterer in den Diensten des Königs Terenas stand. Man nennt es einen Stab des Zwangs.\n\n<Der Hochexekutor ringt die Hände in hämischer Vorfreude.>\n\nIch habe eine Idee, wie wir ihn uns zunutze machen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12272] = { id = 12272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das blutende Erz", description = "Stunden vor der Invasion durch Naxxramas stolperte einer der Bergarbeiter über ein dunkles Erz, aus dem eine zähe Flüssigkeit tropfte. In dem Chaos, das bei der Evakuierung der Mine herrschte, verloren wir jedoch die aus der seltsamen Ader herausgehauenen Proben. Nun untersucht die Geißel das Erz, um herauszufinden, wie sie es in ihren todbringenden Maschinen verwenden können.\n\nIhr müsst zurück zur Mine von Wintergarde gehen, die nordöstlich von hier in den Aasfeldern gelegen ist, und in Besitz dieses seltsamen Erzes gelangen. Die Sache ist für den Erfolg unserer Mission unerlässlich!", sourceObjective = "Belagerungsingenieur Viertelblitz in der Feste Wintergarde in der Drachenöde möchte, dass Ihr 10 Proben des seltsamen Erzes aus der Mine von Wintergarde beschafft.", progress = "Habt Ihr die Proben des seltsamen Erzes mitgebracht?", completion = "Vielleicht ist dies der Moment, der Augenblick an dem sich die Dinge gegen die Geißel wenden werden. Ihr habt Euch als Held der Allianz erwiesen - zumindest in meinen Augen, {name}.\n\nWenn Ihr nun so freundlich sein könntet und mir etwas Freiraum ließet. Ich werde etwas mehr Zeit benötigen, um dieses Erz zu untersuchen und Unreinheiten und Schwächen zu entfernen.\n\nWeiter an die Arbeit, Verbündeter. Ich werde mich bei Euch melden, sobald ich Neues habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[12273] = { id = 12273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verleumdung", description = "Es ist Zeit, dass wir die Streitkräfte des Scharlachroten Ansturms vollkommen demoralisieren!\n\nIch möchte, dass Ihr diesen Stab nehmt und mit ihm vier ihrer Anführer bezaubert: Kommandant Jordan im oberen Stockwerk der Kaserne, Kanonierführer Zierhut auf der südöstlichen Rampe am Strand, Schmied Gutmann in der Schmiede und Stallmeister Mercer bei den Ställen.\n\nBeherrscht sie mithilfe des Stabes, lasst sie den Scharlachroten Ansturm verleumden und tötet sie anschließend!", sourceObjective = "Hochexekutor Zürner in Gallgrimm hat Euch damit beauftragt, den Stab des Zwangs auf Kommandant Jordan, Kanonierführer Zierhut, Schmied Gutmann und Stallmeister Mercer anzuwenden.\n\nTötet sie, sobald Ihr den Stab verwendet habt, um ihnen als letzte Worte die Verleumdung des Scharlachroten Ansturms abzuverlangen.", completion = "<Ihr meint, ein flüchtiges Lächeln über Zürners Gesicht huschen zu sehen.>\n\nIhr seid nun offiziell mein Lieblingstodesritter, {name}. Falls Ihr Lust dazu habt, dann solltet Ihr es vielleicht in Erwägung ziehen, ein Offizier der Hand der Rache zu werden.\n\nIhr würdet als Todeswache anfangen und ich meine, dass Ihr nach ein paar Jahrzehnten das Zeug zum Juniorexekutor hättet!\n\nNein? Nun ja, übereilen wollen wir es ja nicht... Lasst Euch Zeit und denkt einmal darüber nach.", sourceObjectiveStatus = "unverified-source-field" }
quests[12274] = { id = 12274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Ungnade fallen", description = "Wir müssen noch mehr vom Hochabt erfahren. Nun, da uns das Gesicht eines Rabenpriesters zur Verfügung steht, können wir Euch nahe genug an ihn heranbringen, damit Ihr mit ihm sprechen könnt.\n\nLeider müssen wir ihn zuerst von seinen Leibwächtern trennen, ansonsten werdet Ihr nie etwas aus ihm herausbekommen.\n\n<Die Agentin stützt sich auf ihre Schaufel und scheint nachzudenken.>\n\nIch denke, ich hab's! Geht die Abtei hinauf und läutet die Glocke, während Ihr verkleidet seid. Daraufhin sollten die Leibwächter des Abtes angerannt kommen, worauf Ihr hinuntergehen und mit ihm sprechen könnt.", sourceObjective = "Agentin Skully in Neuherdweiler möchte, dass Ihr die Glocke der Abtei läutet und anschließend vom Hochabt die benötigten Informationen beschafft.", progress = "Was habt Ihr herausfinden können? Habt Ihr überhaupt schon mit ihm gesprochen?", completion = "Was zum Teufel ist hier los?!\n\nEr ist von alleine gesprungen? Seid Ihr Euch sicher, dass Ihr ihn nicht gestoßen habt?\n\n<Die Agentin blickt Euch skeptisch an.>\n\nGut. Offensichtlich wird hier mehr gespielt, als wir zuerst dachten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12275] = { id = 12275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sprenggnom", description = "Viertelblitz hat vor Kurzem einen meiner Spezialisten angefordert, um eine Aufklärungsmission in den Minen von Wintergarde durchführen zu können; also habe ich ihm Schleicha geschickt, meinen Sprengmeister. Dummerweise dachte ich, dass er die Grube der Verdammnis nach abgeschlossener Mission hätte zuschütten können, um uns damit einen weiteren Sieg über die Geißel zu bescheren.\n\nNun ist schon ein ganzer Tag vergangen und Schleicha ist noch immer nicht zurück. Ich will wissen, was los ist! Sprecht mit Belagerungsingenieur Viertelblitz und findet meinen vermissten Agenten!", sourceObjective = "Sprecht mit Belagerungsingenieur Viertelblitz in der Feste Wintergarde in der Drachenöde.", completion = "Ich hab' so ein schlechtes Gefühl deswegen, {class}. Ich fürchte, dass ich in meiner Eile, an das seltsame Erz aus der Mine von Wintergarde heranzukommen, Agent Schleicha womöglich zum Tode verurteilt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[12276] = { id = 12276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Schleicha", description = "Ich hab zwar noch nichts von Schleicha gehört und weiß auch nicht, welches Schicksal ihn ereilt hat, doch vielleicht kann ich dabei helfen, ihn zu finden.\n\n<Viertelblitz hält ein kleines mechanisches Spielzeug in die Höhe.>\n\nDas ist kein Spielzeug, {class}. Tatsächlich handelt es sich hier um meine neueste mechanische Errungenschaft. Sie ist nur dafür da, um das zu finden, was verloren gegangen ist. Die Umstände sind zwar nicht die besten, doch die Maschine ist Eure beste Chance, Schleicha zu finden.\n\nStellt den Roboter neben mir auf den Boden, sobald Ihr mit der Suche beginnen wollt.", sourceObjective = "Sucht und findet Schleicha den Sprenggnom in den Minen von Wintergarde. Holt Euch Viertelblitz' Zielsuchroboter zu Hilfe, wenn Ihr die Minen nicht finden könnt.\n\nBereitgestellter Gegenstand:", completion = "<Schleichas leblose Hand umklammert einen Zettel.>\n\nSie sind hinter mir her. Kein Ausweg. Habe mich versteckt, aber sie wissen, dass ich hier bin. Bald werden sie mich finden.\n\nDie Bergarbeiter schürfen ununterbrochen nach dem seltsamen Erz, mit dem die Kriegsmaschinen der Geißel betrieben werden. Es gibt viel Gerede. Die Sprache des Todes verwirrt mich, doch ich konnte ein paar häufig verwendete Laute und Sätze identifizieren. Das Wort \"Yogg-Saron\" wird dabei mit einem verachtenden Tonfall ausgesprochen, worauf gewöhnlich laute Wutausbrüche folgen. Sie nennen das Erz \"Saronit\". Und das bedeutet?", sourceObjectiveStatus = "unverified-source-field" }
quests[12277] = { id = 12277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überlasst nichts dem Zufall", description = "Lest weiter, wenn Ihr guten Herzens und reinen Gewissens seid.\n\nIn dieser Mine ruht in der Nähe des Schafotts des Vorarbeiters eine ordentliche Ladung Dynamit. Geht hin, nehmt Euch mehrere Stangen Sprengstoff und schlagt Euch zum Eingang der Mine durch. Platziert das Dynamit und sprengt den Eingang in die Luft, sobald Ihr dort angekommen seid. Vergesst nicht, dass es sowohl auf der oberen als auch der unteren Ebene einen Eingang zu den Minen von Wintergarde zu sprengen gibt.\n\nIhr dürft nichts dem Zufall überlassen. Das Böse dort darf niemals freigelassen werden. Möge das Licht Euch den Weg weisen.", sourceObjective = "Beschafft eine Minenbombe von Wintergarde und verwendet sie, um den oberen und unteren Minenschacht von Wintergarde zu sprengen. Erstattet Belagerungsingenieur Viertelblitz bei der Feste Wintergarde in Drachenöde Bericht, sobald Ihr die Aufgabe erfüllt habt.", completion = "Sein Tod soll nicht umsonst gewesen sein, mein Freund. Die Informationen, für die Schleicha sein Leben gelassen hat, werden Verwendung finden, um den Lichkönig zu bezwingen. Ich verspreche Euch, dass wir das in Ordnung bringen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12278] = { id = 12278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bier des Monats e.V.", description = "Mitgliedschaft hat ihre Vorteile. Als Mitglied des \"Bier des Monats e.V.\" weiß man einfach immer, wo es das beliebteste und beste Bier gibt.\n\nBringt noch heute Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Larkin Donnerbräu in der Steinfeuertaverne in Eisenschmiede.", sourceObjective = "Bringt Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Larkin Donnerbräu in der Steinfeuertaverne in Eisenschmiede.", progress = "Habt Ihr Euren Antrag ausgefüllt?", completion = "Euer Papierkram sieht in Ordnung aus. Willkommen im Verein, {name}!\n\nStellt Euch schon mal darauf ein, zu Beginn jedes Monats Post von uns zu erhalten. Schaut doch mal vorbei, wenn Euch das Bier schmeckt, das Ihr bekommen habt, und wir werden Euch noch mehr davon verkaufen. Dieser Verein gibt und gibt und gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12279] = { id = 12279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bärenhunger", description = "Zum Glück seid Ihr zurück, Hinkejoe! Ich hatte Sorge, dass Griselda und ich ganz allein sein würden.\n\nIch koche uns gerade eine schöne Mahlzeit, aber Griselda will davon nichts wissen.\n\nSie hätte gerne den Fisch, der sich an der Ostwindküste im Osten tummelt. Für mich ist der ja nichts, aber sie war schon immer ziemlich wählerisch. Sechs große Fische sollten eigentlich reichen, um sie glücklich zu machen.\n\nNun, rennt... ähh... hinkt los, Joe. Wir wollen das Mädchen doch nicht warten lassen, oder?", sourceObjective = "Bringt Hugh Glass am Handelsposten von Rotholz 6 Nordlachse.", progress = "Wenn Ihr Euch nicht beeilt, wird hier gleich nicht nur ihr Magen knurren...", completion = "Ihr! Ihr seid ja gar nicht Hinkejoe!", sourceObjectiveStatus = "unverified-source-field" }
quests[12280] = { id = 12280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reparaturen", description = "Zwanzig Schredder bis morgen Mittag!\n\nWer macht diese Pläne überhaupt? Auf jeden Fall niemand, der diese Mülleimer schon mal wieder zusammensetzen musste, so viel ist mal sicher…\n\nWenn ich mein Soll erfüllen soll, dann brauche ich Unterstützung. Helft mir und ich teile meine Kommission mit Euch - das ist doch gerecht, oder?\n\nIch brauche Zahnräder, Winkel und Federn. Sie liegen überall auf dem Boden bei den Schreddern herum.", sourceObjective = "Lurz beim Holzfällerposten Blauhimmel möchte, dass Ihr 4 gefalzte Zahnräder, 3 gekerbte Winkel und 2 Hochspannungsfedern sammelt.", progress = "Und, habt Ihr die Teile für mich?", completion = "Danke, {name}. Das sollte die Arbeit am Laufen halten - bis morgen jedenfalls…\n\nHier ist das versprochene Geld.", sourceObjectiveStatus = "unverified-source-field" }
quests[12281] = { id = 12281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kriegsmaschine der Geißel verstehen", description = "Wir müssen uns mit dem Gedanken trösten, dass Schleichas Tod, wenn auch tragisch, dem Wohle aller gedient hat. Seine Entdeckung in Verbindung mit Euren Heldentaten in der Mine und den von Euch zurückgebrachten Proben bringen uns einen Schritt näher, die Kriegsmaschinerie der Geißel zu verstehen.\n\nBringt Viertelblitz' Paket zu Oberkommandant Halford Wyrmbann. In ihm befinden sich eine Probe des seltsamen Erzes und meine Analyse.", sourceObjective = "Liefert Viertelblitz' Paket bei Oberkommandant Halford Wyrmbann in der Feste Wintergarde ab.", progress = "Ich habe davon gehört, wie tapfer Ihr in der Mine gewesen seid, {name}.", completion = "<Halford öffnet das Paket und liest sich die Analyse durch.>\n\nIch bin weit davon entfernt, ein Wissenschaftler zu sein, {name}, Ihr müsst also mein pöbelhaftes Verständnis über das Geschriebene entschuldigen. Nun, sollte ich zumindest die Intelligenz eines heranwachsenden Schuljungens besitzen, dann lässt sich aus dieser Analyse schließen, dass wir noch rein gar nichts über die Kriegsmaschinerie der Geißel wissen. Das Einzige, was wir wissen, ist, dass die Geißel dieses schmutzige Metall zur Herstellung ihrer Belagerungsmaschinen verwendet.", sourceObjectiveStatus = "unverified-source-field" }
quests[12282] = { id = 12282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spuren der Vergangenheit", description = "Dieses Land wird von den Erinnerungen der Vergangenheit heimgesucht, {name}. Ich kann die Schreie der Gefallenen hören, wie sie über ganz Nordend hallen.\n\nArthas hat auf allem, das er berührt hat, ein schreckliches Mal hinterlassen. Es ist also wichtig für uns, etwas über die Vergangenheit zu lernen, damit wir unseren Feind besser verstehen können. Womöglich werden verborgene Wahrheiten zutage treten, die uns bei unserem Unternehmen helfen könnten.\n\nZuerst müsst Ihr meine Seherkugel aus dem Rathaus besorgen, {name}. Verlasst diesen Turm und biegt nach Links ab, den Pfad entlang, um zum Dorfplatz zu gelangen.", sourceObjective = "Zelig der Visionär in der Feste Wintergarde in der Drachenöde möchte, dass Ihr seine Seherkugel holt.", progress = "Habt Ihr meine Seherkugel geholt?", completion = "Gut gemacht, {name}. Wie vom Schicksal vorherbestimmt, werdet Ihr uns durch diese schweren Zeiten führen. Jetzt beginnt die lange Reise.", sourceObjectiveStatus = "unverified-source-field" }
quests[12283] = { id = 12283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wahrheit wird herauskommen", description = "Wir müssen herausfinden, was hier vorgeht - und dazu brauchen wir das Tagebuch des Generals!\n\nIch bin mir ziemlich sicher, dass es auf ihrem Nachtkästchen im oberen Stockwerk ihres Hauses liegt - das Haus neben der Kirche, gegenüber den Ställen und dem Sägewerk.\n\nBringt das Tagebuch zum Hochexekutor in Gallgrimm, sobald Ihr es gefunden habt.\n\nIhr werdet das wohl auf die altmodische Art und Weise machen müssen; der Spiegel besitzt nur noch wenig Energie - gerade noch genug für mich.\n\n<Die Agentin grinst.>", sourceObjective = "Agentin Skully möchte, dass Ihr das Tagebuch von Hochgeneral Abbendis beschafft und es zu Hochexekutor Zürner in Gallgrimm bringt.", progress = "Es wurde auch langsam Zeit, {name}! Was hat Euch nur aufgehalten?", completion = "Verdammt! Wieso konntet Ihr mir keine guten Neuigkeiten bringen?!", sourceObjectiveStatus = "unverified-source-field" }
quests[12284] = { id = 12284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet sie auf Trab", description = "Wir mussten hier schlimme Verluste hinnehmen, {race}.\n\nDie einzige gute Nachricht ist, dass wir genauso viel ausgeteilt wie eingesteckt haben. Ich habe um Verstärkung gebeten, doch der Großteil unserer Truppen steckt in der Venturebucht fest. Sieht so aus, als ob wir fürs Erste auf uns allein gestellt wären.\n\nEgal, wie schlimm es wird, wir dürfen nicht zurückweichen! Die wertvollen Ressourcen, die diese Region bietet, sind ausschlaggebend für den langfristigen Erfolg der Horde in Nordend.\n\nWir müssen die Allianzler auf Trab halten, bis Hilfe eintrifft. Macht Euch auf den Weg und verpasst ihnen einen Denkzettel.", sourceObjective = "Kommandant Bargok möchte, dass Ihr beim Holzfällerposten Blauhimmel 15 Einheiten oder Spieler der Allianz tötet.", completion = "Fünfzehn umgelegt, hm? Schön, das zu hören, {class}.\n\nDas hat uns zumindest ein wenig Zeit erkauft - ich schätze wenigstens einen Tag.\n\nHier ist Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12285] = { id = 12285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tu anderen...", description = "Ihr Angriff steht kurz bevor, {class}. Ihr müsst dort hineingehen und den Kopf des Scharlachroten Ansturms buchstäblich vom Rumpf abtrennen!\n\nEs wird nicht einfach sein... Abbendis wird sicherlich von einer großen Zahl ihrer Mannen umgeben sein. Ich schlage also vor, dass Ihr auf jeden Fall ein paar Freunde mitnehmen solltet.\n\nBringt mir ihren Kopf und ich werde dafür sorgen, dass Ihr für Gallgrimms Rettung eine anständige Belohnung erhaltet.\n\nSolltet Ihr jedoch versagen, dann kommt bloß nicht wieder zurück!", sourceObjective = "Hochexekutor Zürner in Gallgrimm hat Euch befohlen, mit dem Kopf des Hochgenerals zurückzukehren.", progress = "Soll ich etwa meinen Truppen sagen, dass wir gen Agmars Hammer ziehen sollen?\n\nOder konntet Ihr den Hochgeneral töten?", completion = "Dann lasst uns mal sehen, ob sie ohne ihren Kopf wieder ins Leben gerufen werden kann!\n\n<Das Gelächter des Hochexekutors zieht etliche verstohlene Blicke auf sich.>\n\nIch mach' mir zwar ein wenig Sorgen darüber, dass Ihr diesen Großadmiral habt entkommen lassen, doch der Held des Tages seid Ihr allemal, {name}!\n\nSucht Euch etwas aus... Ihr habt es verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[12286] = { id = 12286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie diese hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[12287] = { id = 12287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orik Treuherz und der Vergessene Strand", description = "Ich habe in die Kugel gesehen und sah den Pfad, den Ihr gehen müsst, {name}.\n\nVor vielen Jahren wurde ein Gräuel an den Küsten der Drachenöde begangen. Die Tat selbst verbleibt im Dunkel, doch ich bin sicher, dass Euer Schicksal im Süden liegt, inmitten der Ruinen des Vergessenen Strands.\n\nNehmt die Straße nach Südosten über den verwüsteten Dorfplatz. Folgt dem Pfad bis Ihr die Dämmerkuppe erreicht. Dort werdet Ihr einen meiner alten Freunde treffen, Orik Treuherz. Er wird Euch erwarten.", sourceObjective = "Sucht Orik Treuherz auf der Dämmerkuppe in der Drachenöde auf.", completion = "Zelig schickte Nachricht, mein Freund. Wir haben Euch erwartet.\n\nIch bin Orik Treuherz, Paladin des Argentumkreuzzugs. Die Priesterin auf der anderen Seite des Feuers ist Tilda Darathan. Wir sind im Namen der Argentumdämmerung hier, um die unglücklichen verdammten Seelen, die versuchen Wintergarde zu verlassen, zu bezwingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12288] = { id = 12288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überfordert!", description = "Ihr da, {class}! Helft mir!\n\nWertvolle Leben gehen verloren! Es gibt einfach viel zu viele Verwundete, als dass ich mich um sie alle alleine kümmern könnte. Wenn wir unsere Soldaten nicht heilen können, dann können wir gleich allesamt unsere sieben Sachen packen und aus den Grizzlyhügeln verschwinden!\n\nHier, nehmt diese Abschnürbinde und verbindet damit die unten auf dem Schlachtfeld liegenden Verwundeten.\n\nBeeilt Euch, {name}! Sie liegen im Sterben!!", sourceObjective = "Aumana beim Holzfällerposten Blauhimmel möchte, dass Ihr die erneuernde Abschnürbinde auf 10 verwundete Scharmützler anwendet.", completion = "Oh, ich danke Euch, ich danke Euch.\n\nDank Euch werden wir einen weiteren Tag erleben. Vielleicht gibt es noch Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12289] = { id = 12289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tritt rein, solang' sie am Boden liegen", description = "Dies ist ein schwarzer Tag für die Allianz. Viele gute Menschen sind tot oder liegen im Sterben. Unser einziger Trost ist, dass sie gut gekämpft und viele unserer Feinde mit in den Tod gerissen haben.\n\nDa der Großteil unserer Streitkräfte in der Venturebucht stationiert ist, müssen wir uns diesem Sturm alleine stellen. Die Ressourcen dieser Region sind für die Allianz essentiell und können das Zünglein an der Waage im Kampf gegen die Horde bedeuten. Wir dürfen nicht versagen!\n\nGeht nun, {name}. Schlagt zu, während sie noch ihre Wunden lecken. Nehmt Rache für Eure gefallenen Kameraden und seid das Licht unserer Hoffnung!", sourceObjective = "Unteroffizier Hartsmann möchte, dass Ihr 15 Einheiten oder Spieler der Horde im Holzfällerlager Blauhimmel besiegt.", completion = "Gut gemacht, {name}.\n\nIhr habt uns hier etwas Zeit verschafft, wenn auch wohl nicht mehr als einen Tag. Dennoch dankt Euch die Allianz für Euren Einsatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[12290] = { id = 12290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Düstergraselixier", description = "Die Geister der Verdammten spuken an der Küste umher. Zu Lebzeiten waren sie tapfere und ehrenhafte Soldaten der Allianz, doch im Tod sind sie verflucht. Wenn wir sie befreien wollen, müssen wir die Quelle ihrer Pein finden!\n\nIm Südosten, auf den Düsterhöhen werdet Ihr ein seltenes Kraut finden, das Düstergras genannt wird. Daraus werde ich ein Elixier zubereiten, welches Euch zeitlich begrenzten Zugang zur Welt der Vergessenen gewähren wird. Geht jetzt und sammelt das Gras.", sourceObjective = "Orik Treuherz auf der Dämmerkuppe in der Drachenöde möchte, dass Ihr 5 Düstergräser von den Düsterhöhen holt.", progress = "Habt ihr das Düstergras besorgt?", completion = "<Orik nimmt das Düstergras und beginnt, ein Elixier zu mixen.>\n\nEs dauert nicht mehr lange, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12291] = { id = 12291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die vergessene Geschichte", description = "Die Toxine im Düstergraselixier werden Euch bewusstlos werden lassen. Die Wirkung des Düstergrases ist so stark, dass selbst Euer Geist getäuscht wird, wodurch Ihr für kurze Zeit in die Welt der Toten eintreten könnt.\n\nWenn Ihr dann ein Geist seid, müsst Ihr mit den geisterhaften Bewohnern des Vergessenen Strands reden. Findet die Quelle ihrer Pein und kehrt zu mir zurück.\n\nDenkt daran, {name}, diese Geister waren einst Soldaten der Allianz. behandelt sie mit Respekt, Ehre und Würde.\n\nNun nehmt das Elixier und wagt Euch nach Süden zur Vergessenen Küste.", sourceObjective = "Orik Treuherz auf der Dämmerkuppe in der Drachenöde möchte, dass Ihr Euch die Geschichte der vergessenen Arbeiter, vergessenen Scharfschützen, vergessenen Ritter und der vergessenen Fußsoldaten anhört.", progress = "Ich habe genug Düstergras, um noch mehr Elixiere herzustellen, {name}.", completion = "<Tränen sammeln sich in Oriks Augen.>\n\nSie wissen es nicht. Keiner von ihnen weiß es! Sie halten Arthas für einen großen Helden, wo es in Wirklichkeit doch Arthas war, der die Schiffe verbrennen lies. Es war Arthas der uns in dieser gefrorenen Öde dem Tod überließ!\n\n<Orik weint.>\n\nNicht alle Soldaten der Flotte des Prinzen sind im frostigen Winter umgekommen. Ich war nur ein Jüngling, als ich die Chance bekam, gegen die Geißel zu kämpfen... und unsere Heimat vor der sicheren Zerstörung zu retten. Ich ergriff diese Chance, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12292] = { id = 12292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Unterstützung der Einheimischen", description = "Der Kampf mit der Horde ist in den Grizzlyhügeln zum Stillstand gekommen. Unsere Streitkräfte sind fast gleich stark und alle Zeichen deuten darauf hin, dass wir eine Pattsituation erreicht haben.\n\nBis zu diesem Morgen jedenfalls. Die einheimischen Fallensteller und Pelzjäger haben um unsere Hilfe gebeten. Anscheinend hat die Horde etwas, das ihnen gehört... Irgendein Relikt.\n\nWir holen es ihnen zurück und gewinnen dank ihrer Unterstützung den Vorsprung, den wir benötigen. Macht Euch auf zum Handelsposten Immergrün, westlich von Burg Siegeswall, und seht Euch nach einer Zedernholzkiste um.", sourceObjective = "Leutnant Dumont bei der Ammertannhütte möchte, dass Ihr Euch zum Handelsposten Immergrün begebt und die Zedernholzkiste beschafft.", progress = "Habt Ihr die Kiste für mich, {name}?", completion = "Sie ist verschlossen, oder? Sieht ziemlich gewöhnlich aus.\n\n<Leutnant Dumont schüttelt die Kiste, was ein hölzernes Klappern hervorruft.>\n\nIch denke, das macht nichts. Solange uns das hier einen Vorsprung gegenüber der Horde verschafft, ist es mir auch egal, wenn hier drin das Heilmittel gegen die Seuche wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[12293] = { id = 12293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schließt den Handel ab", description = "Wir haben, was die Fallensteller wollen. Nun ist es an uns, sie auf unsere Seite zu bringen.\n\nBringt die Kiste zu einem Fallensteller namens Ivan im Posten des Espenhains, gleich nördlich von hier.\n\nWenn alles gut geht, werden wir bald Waldmänner als Späher für die königliche Armee einsetzen können.", sourceObjective = "Bringt die Zedernholzkiste zu Ivan im Posten des Espenhains.", progress = "Habt Ihr etwas für uns?", completion = "Ihr habt es geschafft! Ihr habt die Kiste, welche die Horde uns gestohlen hat, zurückgebracht. Wir danken Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12294] = { id = 12294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein vorläufiger Pakt", description = "Nun gut, {name}. Euer Volk hat seinen Teil der Abmachung eingehalten.\n\nSagt Dumont, dass wir auch unseren Teil einhalten werden.", sourceObjective = "Kehrt zu Leutnant Dumont in der Ammertannhütte zurück.", completion = "Ausgezeichnete Arbeit, {name}. Mit der Hilfe der Einheimischen steht uns auch die logistische Unterstützung zur Verfügung, die wir dazu brauchen, um die Horde in dieser Region auszumanövrieren.\n\nIch habe noch mehr Aufgaben für Euch, falls Ihr daran interessiert seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[12295] = { id = 12295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Übung in Sachen Diplomatie", description = "Wir hatten wochenlang versucht, mit den Fallenstellern zu verhandeln, jedoch erfolglos, bis Ihr ihre verdammte Kiste gefunden habt.\n\nDas sollten gute Neuigkeiten für unseren Entsandten in Silberwasser sein. Vor ungefähr einer Woche haben wir Ducal dorthin geschickt und sein letzter Brief lässt darauf schließen, dass er nur wenig Fortschritt gemacht hat.\n\nGeht nach Silberwasser und helft ihm bei seinen diplomatischen Angelegenheiten. Folgt den Straßen in Richtung Norden. Nach ein paar Brücken solltet Ihr dort ankommen.", sourceObjective = "Sprecht mit dem Entsandten Ducal in Silberwasser.", completion = "Gut, Euch endlich kennenzulernen, {name}! Wir haben hier oben von Euch gehört. Willkommen in Silberwasser.\n\nDiese Fallensteller sind ein toller Haufen Jungs und Mädels. Ein hartes Völkchen - sie kennen sich sehr gut mit dem hiesigen Gelände aus. Ihr werdet sehen, dass es eine großartige Sache ist, dass wir sie endlich auf unsere Seite geholt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12296] = { id = 12296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leben oder Tod", description = "Oh, dieses Gemetzel...\n\nIch habe schon viele Schlachten erlebt, {class}, aber das war brutaler als alles, was ich bisher gesehen habe. Unser Kampf gegen die Horde ist erbarmungsloser denn je geworden. Es heißt hier in Nordend sie oder wir... Leben oder Tod.\n\nWenn wir hier auch nur einen Tag länger überleben wollen, müssen wir unsere Verletzten heilen. Es sind zu viele, als dass ich sie alleine retten könnte.\n\nIch habe besondere Verbände hergestellt, die es ermöglichen, dass Ihr mir helfen könnt. Nehmt sie und behandelt diejenigen damit, die ihren Wunden noch nicht erlegen sind.", sourceObjective = "Rheanna beim Holzfällerposten Blauhimmel möchte, dass Ihr die erneuernde Bandage bei 10 verwundeten Westfall-Einheiten anwendet.", completion = "Wundervoll!\n\nDie Allianz wird noch einen weiteren Tag erleben, nicht zuletzt dank Eures Fleißes.\n\nNehmt meinen Dank an, Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[12297] = { id = 12297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Verrätern und Verrat", description = "Die Liste, die ich in Händen halte, muss an Oberkommandant Halford Wyrmbann überbracht werden. Er kommandiert die 7. Legion, die in der Feste Wintergarde an der östlichen Grenze der Drachenöde stationiert ist.\n\nWenn sich irgendeiner der Verräter auf dieser Liste in Wintergarde befindet... könnten die Folgen katastrophal sein.\n\nBeeilt Euch, {name}. Zeigt Greer Erzhammer hier in Westwacht dieses Schreiben und erklärt ihm, was es mit Eurer Mission auf sich hat. Für die Reise nach Wintergarde wird er Euch seinen schnellsten Greifen geben!", sourceObjective = "Hauptmann Adams möchte, dass Ihr das Schreiben der Allianz zu Greer Erzhammer in Westwacht bringt.", progress = "Hallo, {class}.", completion = "<Greer schiebt seine Brille auf die Stirn, liest sich die Mitteilung durch und blickt Euch verwundert an.>\n\nIch werde Euch meinen schnellsten Greifen geben! Diese Information muss unverzüglich an Oberkommandant Wyrmbann ausgehändigt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[12298] = { id = 12298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oberkommandant Halford Wyrmbann", description = "<Greer gibt Euch das Schreiben wieder zurück.>\n\nHimmelsweise wird Euch nach Wintergarde bringen, {name}. Ich kann Euch versichern, dass dies der schnellste Flug sein wird, den Ihr je erlebt habt. Geht jetzt!", sourceObjective = "Überbringt Oberkommandant Halford Wyrmbann das Schreiben der Allianz. Er befindet sich in der Feste Wintergarde im Osten der Drachenöde.", progress = "Was habt Ihr denn da, Soldat?", completion = "<Der Oberkommandant liest sich das Schreiben durch und zerknüllt es anschließend.>\n\nWisst Ihr, wo sich diese Leute auf der Liste im Moment befinden? Seht Euch draußen in der Nähe des Eingangstores einmal um. Es sind diejenigen, die vom Torbogen baumeln.\n\nGhulköder...", sourceObjectiveStatus = "unverified-source-field" }
